import scala.reflect.ClassTag
case class Queue[T](len: Int)(implicit m: ClassTag[T]) {
    var que = m.newArray(len)
    var size = 0
    var headPtr = len - 1
    var tailPtr = len - 1

    def isEmpty(): Boolean = if (size == 0) true else false
    def isFull(): Boolean = if (len == size) true else false
    def enque(e: T): Unit = {
        if (!isFull) {
            size += 1
            que(headPtr) = e
            if (headPtr - 1 < 0) headPtr = len - 1
            else headPtr -= 1
        } else {
            throw new RuntimeException("error...")
        }
    }
    def deque(): T = {
        if (!isEmpty) {
            val ret = que(tailPtr)
            size -= 1
            if (tailPtr - 1 < 0) tailPtr = len - 1
            else tailPtr -=1
            ret
        } else {
            throw new RuntimeException("error...")
        }
    }
}
case class Proc(name: String, time: Int) {
    def exec(t: Int): (Proc, Int) = {
        if (time - t < 0) (new Proc(name, 0), time)
        else (new Proc(name, time - t), t)
    }
    def finished(): Boolean = if (time == 0) true else false
}
