    def process(que: Queue[Proc], quantum: Int): List[String] = {
        def go(total: Int, result: List[String]): List[String] = {
            if (que.isEmpty) result
            else {
                val (pProc, time) = que.deque.exec(quantum)
                if (pProc.finished) {
                    go(total + time, s"${pProc.name} ${total + time}" :: result)
                } else {
                    que.enque(pProc)
                    go(total + time, result)
                }
            }
        }
        go(0, Nil).reverse
    }
}

