class Queue[A](size: Int)(implicit m: ClassTag[A]) {
    private val arr = m.newArray(size);
    private var leftPtr = 0;
    private var rightPtr = 0;
    private var cnt = 0;
    def isEmpty: Boolean = cnt == 0;
    def isFull: Boolean = cnt == size;
    def enqueue(e: A): Unit = if (isFull) {
        throw new RuntimeException("queue full")
    } else {
        arr(rightPtr) = e;
        cnt += 1;
        rightPtr = if (rightPtr + 1 == size) 0 else rightPtr + 1;
    }

    def dequeue: A = if (isEmpty) {
        throw new NoSuchElementException("queue empty");
    } else {
        val e = arr(leftPtr);
        cnt -= 1;
        leftPtr = if (leftPtr + 1 == size) 0 else leftPtr + 1;
        e;
    }
}

