case class Queue[T](in: List[T], out: List[T]) {
    def isEmpty(): Boolean = if (in.isEmpty && out.isEmpty) true else false
    def head(): T = out match {
        case x :: xs => x
        case _ => throw new RuntimeException("error...")
    }
    def enque(e: T): Queue[T] = {
        val newIn = e :: in
        new Queue[T](newIn, newIn.reverse)
    }
    def deque(): Queue[T] = out match {
        case x :: xs => new Queue[T](xs.reverse, xs)
        case _ => throw new RuntimeException("error...")
    }
}
object Queue {
    def apply[T](): Queue[T] = new Queue[T](Nil, Nil)
}
case class Proc(name: String, time: Long) {
    def exec(t: Long): (Proc, Long) = {
        if (time - t < 0) (new Proc(name, 0), time)
        else (new Proc(name, time - t), t)
    }
    def finished(): Boolean = if (time == 0L) true else false
}
object Main {
