        val quantum = line(1).toLong
        val que: Queue[Proc] = (1 to procNum).foldLeft(Queue[Proc]()) { (que, a) => 
            val p = readLine.split(" ")
            que.enque(new Proc(p(0), p(1).toLong))
        }
        println(process(que, quantum).mkString("\n"))
    }

    def process(que: Queue[Proc], quantum: Long): List[String] = {
        def go(que: Queue[Proc], total: Long): List[String] = que match {
            case que if que.isEmpty => Nil
            case que => que.head.exec(quantum) match {
                case (pProc, time) if pProc.finished => s"${pProc.name} ${total + time}" :: go(que.deque, total + time)
                case (pProc, time) => go(que.deque.enque(pProc), total + time)
            }
        }
        go(que, 0)
    }
}

