int cnt = 0;
void insertsort(vector<int> &v, int g);

int a3()
{
	//插入排序的特点：当数据相对有序时效率较高。利用对已经排好的数据进行插入排序，只需比较N次，而不需要移动。
	//希尔排序：利用插入排序的特点。
	//首先生成希尔数列(h = 3 * h + 1)

	//输入数据
	int n;//元素数目
	vector<int> v1;
	cin >> n;
	int temp;
	for (int i = 0; i<n; i++)
	{
		cin >> temp;
		v1.push_back(temp);
	}

	//生成数列
	vector<int> G;//希尔数列
	int h = 1;
	while (h <=n)
	{
		G.push_back(h);
		h = 3 * h + 1;
	}

	//间隔插入排序

	for (int i = G.size() - 1; i >= 0; i--)
	{

		insertsort(v1, G[i]);
	}

	//输出
	cout << G.size() << endl;;
	for (int i = G.size()-1; i >=0; i--)
	{
		if (i == G.size() - 1) cout << G[i];
		else cout << " " << G[i];
		cout<< endl;
	}

	cout << cnt << endl;
	for (int i = 0; i < v1.size(); i++)
		cout << v1[i] << endl;

	return 0;
}
void insertsort(vector<int> &v, int g)//间隔为g的插入排序
{
	int n = v.size();

	//cout << n << endl;
	for (int i = g; i < n; i++)
	{
		int t = v[i];
		int j = i - g;
		while (j >= 0 &&v[j]>t )//实际上只需要把v[i]插入到里面即可，v[j]都是已经排好序的...记住应该首先判断j,
			//对与每个 i 循环代码实际只运行一次
		{
			v[j + g] = v[j];
			j -= g;
			cnt++;//计算交换次数
			//cout << cnt << endl;

		}
		v[j + g] = t;
		//for (int i = 0; i < v.size(); i++)
		//	cout << v[i];
		//cout << endl;
	}
}

