// グローバル変数
const int len = 100005;
P Q[len];
int head, tail, n;

void enqueue(P x){
    // tailが指す場所にxを追加し、要素が増えたのでtailをincrement
    // lenで割って余りを求める = キューが満杯でないかどうか
    Q[tail] = x;
    tail = (tail + 1) % len;
}

P dequeue(){
    // headが指す先頭の要素を返す．要素を一つ取り出したのでheadをincrement
    // lenで割って余りを求める = キューが満杯でないかどうか
    P x = Q[head];
    head = (head + 1) % len;
    return x;
}

int min(int a, int b){
    // 最小値を返す
    return a < b ? a : b;
}

int main(){
