        cin >> Q[i].name >> Q[i].t;
    }
    head = 1;
    tail = n + 1;

    // シミュレーション開始
    while(head != tail){
        u = dequeue();
        c = min(q, u.t); // qまたは，必要な時間(u.t)だけ処理を行う
        u.t -= c; // 残り時間を計算
        elaps += c; // 経過時間を加算

        if(u.t > 0){
            // 処理が完了していなければqueueに追加
            enqueue(u);
