  Proc(){
    nam = "";
    tim = 0;
  }
};

Proc Q[100001];
class Queue{
private:
  int f;
  int r;
public:
  Queue(){
    f = 0;
    r = 0;
  }
  int next(int p) const{
    return (p+1)%100001;
  }
  bool isFull() const{
    return (next(r) == f);
  }
  bool isEmpty() const{
    return (r == f);
  }
  void push(Proc d){
    if(isFull()){
      return;
    }
    Q[r] = d;
    r = next(r);
  }
  Proc front(){
    if(isEmpty()){
      Proc er;
      er.tim = -1;
      return er;
    }
    return Q[f];
  }
  void pop(){
    if(isEmpty()){
      return;
    }
    f = next(f);
  }
};

