    cout << "queue:head " << q->head << " queue:tail " << q->tail << endl;
}

void initialize(queue_mine_t *t){
    t->tail = t->head = 0;
}

int isEmpty(queue_mine_t *t){
    return t->tail == t->head;
}

int isFull(queue_mine_t *t){
    return t->head == (t->tail +1)%MAX;
}

int enqueue_mine(queue_mine_t *t, process_mine_t *p){
    if (isFull(t)){ return 0; }
    else{
        t->p[t->tail] = p;
        if (t->tail +1 == MAX){
            t->tail =0;
        }else{t->tail += 1;}
        return 1;
    }
}

int dequeue_mine(queue_mine_t *t, process_mine_t **p){
    if(isEmpty(t)){ return 0;}
    else{
        *p = (t->p[t->head]);
        if(t->head + 1 == MAX){
            t->head = 0;
        }else{
            t->head++;
        }
        return 1;
    }

}



