    int next(int p)const{
        return (p+1)%100001;
    }
    bool isFull()const{
        return (next(rp)==fp);
    }
    bool isEmpty()const{
        return (rp==fp);
    }
    void push(Proc p);
    Proc front();
    void pop();
};

void Queue::push(Proc p){
    if(isFull()){
        return;
    }

    Q[rp] = p;
    rp = next(rp);

}

Proc Queue::front(){
    if(isEmpty()){
        Proc e;
        e.tim = -1;
        return e;
    }

    return Q[fp];
}

void Queue::pop(){
    if(isEmpty()){
        return;
    }
    fp = next(fp);
}

