#define MAX_N 100000
#define MAX_NAME 10

typedef struct Queue {
	char name[MAX_NAME];
	int time;
	struct Queue *qnext;
	struct Queue *qprev;
}Queue;

int main() {
	int n, q;
	int sum = 0;
	Queue *pPoint;
	int sTime = 0;

	scanf("%d %d", &n, &q);

	Queue *queue = new Queue[n];
	if (NULL == queue) {
		return -1;
	}

	//　Queueの初期化処理
	for (int i = 0; i < n; i++) {
		if (i == 0) {
			queue[i].qprev = queue + (n - 1);
			queue[i].qnext = queue + (i + 1);
		}
		else if (i == (n - 1)) {
			queue[i].qnext = queue;
			queue[i].qprev = queue + (i - 1);
		}
		else {
			queue[i].qprev = queue + (i - 1);
			queue[i].qnext = queue + (i + 1);
		}
		scanf("%s", &(queue[i].name));
		scanf("%d", &(queue[i].time));
		sum += queue[i].time;
	}

	Queue *tmpQ;
	pPoint = queue;
	while (sum > 0) {
		if (pPoint->time <= q) {
			sTime += pPoint->time;
			printf("%s %d\n", pPoint->name, sTime);
			sum -= pPoint->time;
			// prev, next を外す
			tmpQ = pPoint;
			pPoint = tmpQ->qnext;
			pPoint->qprev = tmpQ->qprev;
			pPoint->qprev->qnext = pPoint;
		}
		else {
			pPoint->time -= q;
			sTime += q;
			sum -= q;
			pPoint = pPoint->qnext;
		}
	}
	delete[] queue;
	return 0;
}

