  Queue(){ fp=0; rp=0;}
  int next(int p) { return (p+1)%10001;}
  bool isFull() { return (next(rp)==fp);}
  bool isEmpty() { return (rp==fp);}
  void push(Proc d);
  Proc front();
  void pop();
};

void Queue::push(Proc d){
  if(isFull())
  return;

  Q[rp]=d;
  rp=next(rp);
}

Proc Queue::front(){
  if(isEmpty()){
    Proc er;
    er.tim=-1;
    return er;
  }
  return Q[fp];
}

void Queue::pop(){
  if(isEmpty())
  return;
  fp=next(fp);
}

