    if (tail < N_QUE - 1) {
      tail++;
    } else {
      tail = 0;
    }
  }

  Process deque() {
    Process p = que[head];
    if (head < N_QUE - 1) {
      head++;
    } else {
      head = 0;
    }
    return p;
  }
  bool isEmpty() { return head == tail; }
