class Queue{
private:
	int head, tail;	
public:
	int Q[100001];
	string name[100001];

	void initialize(){
		head = 0; tail = 0;
	}
	int isEmpty(){
		return head == tail;
	}
	int isFull(){
		return head == (tail + 1) % 100001;
	}
	void enqueue(int x, string c){
		if (isFull()) cout << "Error" << endl;
		Q[tail] = x ;
		name[tail] = c ;
		if (tail + 1 == 100001) tail = 0;
		else tail++;
	}
	int dequeue(){
		if (isEmpty()) cout << "Error" << endl;
		int x = Q[head];
		if(head + 1 == 100001) head = 0;
		else head++;
		return x;
	}	
	string outname(){
		if (head == 0) return name[100000];		
		else return name[head-1];
	}
};

