		int x;
		cin >> c >> x; 
		que.enqueue(x, c);
	} 
	if(n==1 && q==1){
		int x = que.dequeue();
		string c = que.outname();	
		cout << c << " " << x << endl;
	}
	else {
		int cnt=0;
