        int t, totalTime=0;
        queue q;
        q.init();
        while( cin >> s >> t ){
                struct proc p;
                p.name = s;
                p.time = t;
                totalTime += t;
                q.enque(p);
        }

        int curTime=0;
        struct proc p;
        while( totalTime != curTime ){
                p  = q.deque();
                if( p.time > time ){
                        p.time -= time;
                        curTime += time;
                        q.enque(p);
                }else{
                        curTime += p.time;
                        cout << p.name << " " << curTime << endl;
                }
        }

        return 0;
}

