#include<iostream>
#include<string>
#include<vector>
using namespace std;

struct process
{
	string name;
	int    time;
};

vector<process> RoundRobin(vector<process> X, int q)
{
	vector<process> Y;
	int totaltime = 0;
	while(!X.empty()){
		int i = 0;
		while(i < X.size()){
			if(X[i].time <= q){
				totaltime += X[i].time;
				process finished;
				finished.name = X[i].name;
				finished.time = totaltime;
				Y.push_back(finished);
				X.erase(X.begin() + i);
			}else{
				totaltime += q;
				X[i].time -= q;
				i++;
			}
		}
	}
	return Y;
}

int main()
{
	int n, q;
	cin >> n;
	cin >> q;
	vector<process> X;
	X.resize(n);
	for(int i = 0; i < n; i++){cin >> X[i].name >> X[i].time;}
	vector<process> Y = RoundRobin(X, q);
	for(int i = 0; i < n; i++){cout << Y[i].name << " " << Y[i].time << endl;}
	return 0;
}

