/**
 * @brief Process Class
 */
class Process
{
public:
    string name;
    int time;

    /* Constructor */
    Process(string n, int t) :
    name(n),
    time(t)
    {
    }
};

/**
 * @brief Result Output
 * @param [in] name Process Name
 * @param [in] time Process Exec Times
 * @return none
 */
void output( string name, int time )
{
    cout << name << " " << time << endl;
    return;
}

int main(void)
{
    /* Input Process Number */
    int numData;
    cin >> numData;

    /* Input Quantum */
    int quantum;
    cin >> quantum;

    /* Input Each Process Info */
    queue<Process> que;
    string p;
    int num;
    for( int loopCnt=0; numData > loopCnt; loopCnt++ )
    {
        cin >> p;
        cin >> num;
        que.push( Process(p,num) );
    }

    /* Round-Robin Scheduling */
    int time = 0;
    while( !que.empty() )
    {
        Process p = que.front();
        que.pop();
        if( p.time <= quantum )
        {
            time += p.time;
            output(p.name,time);
        }
        else
        {
            time += quantum;
            p.time -= quantum;
            que.push( p );
        }
    }

    return 0;
}

