using namespace std;
const int QUEUE_SIZE = 100000;


//リングバッファ
class MyQueue {
    private:
        int m_head = 0;
        int m_tail = 0;
        vector<pair<string, int>> m_buffer;
    public:
        void init();
        void enqueue(pair<string, int> v);
        pair<string, int> dequeue();
        bool isEmpty();
        bool isFull();
        void show();

};

void MyQueue::init() {
    m_head = 0;
    m_tail = 0;
    m_buffer.resize(QUEUE_SIZE);
}

void MyQueue::enqueue(pair<string, int> v) {
    if(isFull()) {
        cout << "error: queue is full." << endl;
        return;
    }

    m_buffer[m_tail++] = v;

    //終端に来たとき
    if(m_tail == QUEUE_SIZE) {
        m_tail = 0;
    }
}

pair<string, int> MyQueue::dequeue() {
    if(isEmpty()) {
        cout << "error: queue is empty." << endl;

        //空の要素を返す
        pair<string, int> res;
        res.first = "";
        res.second = -1;
        return res;
    }

    pair<string, int> res = m_buffer[m_head];
    m_head++;

    //終端に来たとき
    if(m_head == QUEUE_SIZE) {
        m_head = 0;
    }

    return res;
}


bool MyQueue::isEmpty() {
    return (m_head == m_tail);
}

bool MyQueue::isFull() {
    return (m_head == (m_tail + 1) % QUEUE_SIZE);
}

void MyQueue::show() {
    for (int i = 0; i < m_buffer.size(); ++i)
    {
        if(i == m_tail) {
            break;
        }
        cout << i << " : " << m_buffer[i].first << ", " << m_buffer[i].second << endl;
    }
}



int main() {
    int n ,q;
    cin >> n >> q;

    MyQueue queue;
    queue.init();

    for (int i = 0; i < n; ++i)
    {
        string process;
        int    time;
        cin >> process >> time;

        pair<string, int> p;
        p.first  = process;     //プロセス名
        p.second = time; //必要処理時間

        queue.enqueue(p);
    }
    //queue.show();


    int total_time = 0; //処理時間を入れる
    while(!queue.isEmpty()) {
        pair<string, int> p = queue.dequeue();

        //1回で処理が終了しないときは実行後にキューの後ろに入れる
        if(p.second > q) {
            //残りの処理時間を減らす
            p.second -= q;

            //処理時間を記録する
            total_time += q;

            //キューに戻す
            queue.enqueue(p);
        } else { //処理が終了するときは、キューには戻さない
            //処理時間を記録する
            total_time += p.second;

            //回答を出力
            cout << p.first << " " << total_time << endl;
        }
    }

    return 0;
}

