    int work_time;
    int spend;
};

int curr = 0;
int all = 0;


struct Task t[100000];

bool compare(struct Task a, struct Task b)
{
    return a.spend < b.spend;
}


int main()
{
    int n;
    int limit;
    cin>>n>>limit;

    for(int i = 0;i < n;i++)
    {
        cin>>t[i].name;
        cin>>t[i].work_time;
        all += t[i].work_time;
    }

    int i = 0;

    while(curr < all)
    {
        if(i >= n)
            i = 0;

        if(!t[i].work_time)
        {
            i++;
            continue;
        }
        else if(t[i].work_time <= limit)
        {
            curr += t[i].work_time;
            t[i].work_time = 0;
            t[i].spend = curr;
        }
        else
        {
            curr += limit;
            t[i].work_time -= limit;
        }

        i++;

    }

    sort(t, t + n, compare);

    for(int j = 0;j < n;j++)
    {
       cout<<t[j].name<<" "<<t[j].spend<<endl; 
    }
}

