		process p = que.front();
		que.pop();
		time = p.getTime();
		if(time > q) {
			p.setTime(time - q);
			total += q;
			que.push(p);
		} else {
			total+=time;
			p.setTime(total);
			cout << p.getName() << " " << p.getTime() << endl;
		}
	}
}

