using namespace std;
template <typename T>
class Queue {
	T* q;
	T* guard;
	T* head;
	T* tail;
public:
	Queue() {
		q = new T[100001];
		guard = q + 100000;
		head = q;
		tail = q;
	}
	~Queue() {
		delete[] q;
	}
	bool isFull() {
		if (tail == guard) {
			return head == q;
		} else {
			return (tail + 1) == head;
		}
	}

	bool isEmpty() {
		return head == tail;
	}

	void push(T x) {
		if (!isFull()) {
			if (tail == guard) {
				if (head != q) {
					tail = q;
					*tail = x;
				}
			} else {
				*tail = x;
				tail++;
			}
		}
	}

	T pop() {
		T retValue;
		if (!isEmpty()) {
			retValue = *head;
			head++;
			if (head == guard) {
				head = q;
			}
		}
		return retValue;
	}
};

struct Process {
	string name;
	int quantum;
public:
	Process() {

	}

	Process(const string& n, int q){
		name = n;
		quantum = q;
	}

	void Decrease(int q) {
		quantum -= q;
	}
};

int main() {
	Queue<Process> queue;
	int n, q;
	cin >> n >> q;
	for (int i = 0; i < n; i++) {
		char name[10];
		int time;
		cin >> name >> time;
		Process p = Process(name, time);
		queue.push(p);
	}

	Queue<Process> finished;
	int time = 0;
	while (!queue.isEmpty()) {
		Process p = queue.pop();
		if (p.quantum >= q) {
			p.quantum -= q;
			time += q;
		} else {
			time += p.quantum;
			p.quantum = 0;
		}
		if (p.quantum <= 0) {
			p.quantum = time;
			finished.push(p);
		} else {
			queue.push(p);
		}
	}

	while (!finished.isEmpty()) {
		Process p = finished.pop();
		cout << p.name << ' ' << p.quantum << endl;
	}
	return 0;
}

