typedef pair<string,int> P;
struct node{
  node *next;
  P v;
  node(){next=NULL;}
  node(P v):v(v){next=NULL;}
};
struct mqueue{
  node *head,*cur;
  mqueue(){
    head=new node();
    cur=NULL;
  }
  void push(P v){
    node *tmp=new node(v);
    if(cur!=NULL) cur->next=tmp;
    cur=tmp;
    if(head->next==NULL) head->next=cur;
  }
  void pop(){
    if(head->next==NULL) return;
    node *tmp=head->next->next;
    if(tmp!=NULL) delete(head->next);
    head->next=tmp;
  }
  P front(){
    return head->next->v;
  }
  bool empty(){
    return head->next==NULL;
  }
};
