void enqueue(Process p){
    P[++top] = p;
}

Process dequeue(int q){
    if (P[bottom].time - q > 0){
        t += q;
        P[bottom].time -= q;
    }
    else {
        t += P[bottom].time;
        P[bottom].time = 0;
    }
    bottom++;
    return P[bottom-1];
}

