void roundRobin(std::queue<std::pair<std::string, int> > &list, int quantum){
    int timeSpent = 0;
    while (!list.empty()) {
        if (list.front().second<=quantum) {
            timeSpent += list.front().second;
            std::cout << list.front().first << " " << timeSpent << std::endl;

        } else {
            timeSpent += quantum;
            list.front().second -= quantum;
            list.push(list.front());
        }
        list.pop();
    }
        //print_array(list);
        //std::cout << i << std::endl;
}


