struct Process {
    string name;
    int time;
    int count;
};

class Queue {
    private:
        Process store[10000];
        int head, tail;
        Process firstProcess;

    public:
        Queue() {
            head=0;
            tail=0;
        }

        void enqueue(string name, int time) {
            Process p;
            p.name = name;
            p.time = time;
            store[tail] = p;
            tail++;
        }

        Process dequeue() {
            firstProcess = store[head];
            head++;
            return firstProcess;
        }
};

int main() {
    Queue q;
    int n, rr, time, diff, total;
    string name;
    Process p;

    cin >> n >> rr;
    for (int i=0; i<n; i++) {
        cin >> name >> time;
        q.enqueue(name, time);
    }

    total = 0;
    while (n) {
        p = q.dequeue();
        diff = p.time - rr;
        if (diff >0) {
            total += rr;
            q.enqueue(p.name, diff);
        } else {
            total += p.time;
            n--;
        }
    }
    return 0;
}

