using namespace std;

struct Process {
public:
    char n[10];
    int t;
};

class Queue {
public:
    Process data[100005];
    int head;
    int tail;
    int max = 100005;

    void enqueue(Process p) {
        data[tail] = p;

        if (tail + 1 >= max) {
            tail = 0;
        } else {
            tail++;
        }
    }

    Process dequeue() {
        Process p = data[head];

        if (head + 1 >= max) {
            head = 0;
        } else {
            head++;
        }

        return p;
    }
};

int main() {
    int n;
    scanf("%d", &n);

    int q;
    scanf("%d", &q);

    int elaps = 0;

    Queue queue;
    for (int i = 0; i < n; i++) {
        Process p;

        char name[10];
        scanf("%s", name);
        int t;
        scanf("%d", &t);

        strcpy(p.n, name);
        p.t = t;

        queue.enqueue(p);
    }
    queue.head = 0;
    queue.tail = n;

    while (queue.head != queue.tail) {
        Process u = queue.dequeue();
        int c = min(q, u.t);
        u.t -= c;
        elaps += c;
        if (u.t > 0) {
            queue.enqueue(u);
        } else {
            printf("%s %d\n", u.n, elaps);
        }
    }

    return 0;
}

