struct Que{
	int head,tail;
	std::vector<int> time;
	std::vector<std::string> name;
};

int initialize(Que &q,int n){
	int qt;
	std::cin>>qt;
	for(int i=0;i<n;i++){
		int time;
		std::string name;
		std::cin>>name;
		std::cin>>time;
		q.time.push_back(time);
		q.name.push_back(name);
		q.tail++;
	}
	q.time.push_back(0);
	q.name.push_back("end");
	return qt;
}

void enque(int x,std::string str,Que &q,int n){
	q.time[q.tail%(n+2)]=x;
	q.name[q.tail%(n+2)]=str;
	q.tail++;
}

int deque(Que &q,int n){
	q.head++;
	return q.time[(q.head-1)%(n+2)];
}

int main(void){
	Que q;
	q.head=0;
	q.tail=0;
	int time=0,n;
	std::cin>>n;
	int qt=initialize(q,n);
	while(q.head!=q.tail){
		std::string str=q.name[(q.head)%(n+2)];
		int x=deque(q,n);
		x-=qt;
		if(x<=0){
			time+=qt+x;
			std::cout<<q.name[(q.head-1)%(n+2)]<<' '<<time<<'\n';
		}else{
			enque(x,str,q,n);
			time+=qt;
		}
	}
	return 0;
}

