};
template<class Type> class Queue
{
    public:
        int head = 0, tail = 0;
        Type *Q;
        Queue(int size)
        {
            Q = new Type[2 * size];
        }
        void push(Type x)
        {
            Q[tail] = x;
            tail++;
        }
        Type pop(){
            Type ret = Q[head];
            head++;
            return ret;
        }
        Type front()
        {
            return Q[head];
        }
        bool empty(){
            return head == tail;
        }
};
int main()
{
    int n, t;
    cin >> n >> t;
    Queue<P> que(MAX_N);
    for(int i = 0; i < n; i++)
    {
        P info;
        cin >> info.name >> info.val;
        que.push(info);
    }
    int sum = 0;
    while(!que.empty())
    {
        P tmp = que.front(); que.pop();
        if(tmp.val - t <= 0) 
        {
            sum += tmp.val;
            cout << tmp.name << " " << sum << "\n";
        }
        else
        {
            tmp.val -= t;
            sum += t;
            que.push(tmp);
        }
    }
    return 0;
}

