};

Que Q;
Process P[100000];

void enqueue(Process p) {
    P[Q.tail] = p;
    Q.tail++;
    if (Q.tail==100000) Q.tail=0;
}

Process dequeue() {
    Process p = P[Q.head];
    Q.head++;
    if (Q.head==100000) Q.head=0;
    return p;
}

bool isEmpty() {
    return Q.head == Q.tail;
}

int main() {
    int t, i, n, MAX_PROCESS_TIME;

    scanf("%d %d", &n, &MAX_PROCESS_TIME);
    for (i=0; i<n; i++) scanf("%s %d", P[i].name, &P[i].time);
    Q.head = 0;
    Q.tail = n;
    t = 0;

    while (!isEmpty()) {
        Process p = dequeue();
        if (p.time > MAX_PROCESS_TIME) {
            p.time -= MAX_PROCESS_TIME;
            t += MAX_PROCESS_TIME;
            enqueue(p);
        } else {
            t += p.time;
            printf("%s %d\n", p.name, t);
        }
    }

    return 0;
}

