const int MAX = 100000;

struct Proc
{
    std::string name;
    int time;
};

class Queue
{
    private:
        Proc procs[MAX];
        int num;
        int tail;

    public:
        Queue()
        {
            tail = 0;
        }
        void enqueue(Proc p)
        {
            procs[tail++] = p;
        }

        Proc dequeue()
        {
            Proc ret = procs[0];
            for (int i = 0; i < tail; ++i)
                procs[i] = procs[i + 1];
            --tail;
            return ret;
        }

        bool isempty()
        {
            return tail == 0;
        }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);

    Queue queue;
    int n, q;
    std::cin >> n >> q;
    while (n--) {
        std::string name;
        int time;
        std::cin>> name >> time;
        Proc p;
        p.name = name;
        p.time = time;
        queue.enqueue(p);
    }
    int time = 0;
    while (!queue.isempty()) {
        Proc p = queue.dequeue();
        if (p.time <= q) {
            time += p.time;
            p.time = 0;
            std::cout << p.name << " " << time << std::endl;
            continue;
        }
        p.time -= q;
        queue.enqueue(p);
        time += q;
    }
