#define MAX 100000 + 10

typedef struct {
    char name[20];
    int time;
} TASK;

template <class T> class Queue {
    T A[MAX];
    int head = 0;
    int tail = 0;

  public:
    bool isFull() {
        return (tail + 1) % MAX == head;
    }
    bool isEmpty() {
        return tail == head;
    }
    void enqueue(T x) {
        if (isFull()) {
            exit(1);
        }
        A[tail++] = x;
        if (tail > MAX) {
            tail = 0;
        }
    }
    T dequeue() {
        if (isEmpty()) {
            exit(1);
        }
        T val = A[head++];
        if (head > MAX) {
            head = 0;
        }
        return val;
    }
};

int main() {
    Queue<TASK> Q;
    int n, q;
    scanf("%d %d", &n, &q);
    for (int i = 0; i < n; i++) {
        TASK x;
        scanf("%s %d", x.name, &x.time);
        Q.enqueue(x);
    }
    int cnt = 0;
    while (!Q.isEmpty()) {
        TASK x = Q.dequeue();
        if (x.time > q) {
            x.time -= q;
            cnt += q;
            Q.enqueue(x);
        } else {
            cnt += x.time;
            printf("%s %d\n", x.name, cnt);
        }
    }
    return 0;
}

