  Q[tail] = x;
  if (tail + 1 == LEN) {
    tail = 0;
  }
  else {
    tail++;
  }
}

P dequeue() {
  P x = Q[head];
  if(head + 1 == LEN) {
    head = 0;
  }
  else {
    head++;
  }
  return x;
}

