class Queue {
private:
    int head;
    int tail;
    const int MaxSize = 100002;
public:
    Queue() {
        head = tail = 0;
    }
    int getSize() {
        return (tail-head+MaxSize) % MaxSize;
    }
    bool check_full() {
        return (tail+1)%MaxSize == head;
    }
    bool check_empty() {
        return tail == head;
    }
    void push(node x) {
        if(!check_full()) {
            a[tail] = x;
            tail = (tail+1) % MaxSize;
        }
    }
    void pop() {
        if(!check_empty()) {
            head = (head+1) % MaxSize;
        }
    }
    node top() {
        if(!check_empty()) {
            return a[head];
        }
    }
    ~Queue() {}
};

