	process& dequeue();
	bool isEmpty();
	bool isFull();
};

void queue::enqueue(const process& p)
{
	if( isFull() ){
		cout<<"full!"<<endl;
		exit(1);
	}


	data[tail+1]=p;
	tail= (tail+1) % LEN;
}
process& queue::dequeue()
{
	if( isEmpty() ){
		cout<<"empty!"<<endl;
		exit(1);
	}


	head= (head+1) % LEN;
	return data[head];
}
bool queue::isEmpty()
{
	return head == tail;
}
bool queue::isFull()
{
	return (tail+1) % LEN == head;
}

