  Q(int n) : head(0),tail(1),n(n+1) {
    t = new T[n];
  }
  ~Q(){
    delete [] t;
  }
  void enqueue(T _t){
    if(head==tail) throw 1;
    t[(tail-1)%n] = _t;
    tail++;
  }
  T dequeue(){
    if(head+1==tail) throw 2;
    T _t =t[head%n];
    head++;
    return _t;
  }
};

