	string Name;
	int    Time;
};

struct TFinished
{
	string Name;
	int    Time;
};

queue<TFinished> RoundRobin(queue<TProcess> Input, int q)
{
	queue<TFinished> Output;
	int TotalTime = 0;
	while(!Input.empty()){
		if(Input.front().Time <= q){
			TotalTime += Input.front().Time;
			TFinished Finished;
			Finished.Name = Input.front().Name;
			Finished.Time = TotalTime;
			Output.push(Finished);
		}else{
			TotalTime += q;
			Input.front().Time -= q;
			Input.push(Input.front());
		}
		Input.pop();
	}
	return Output;
}

