}
///-------------------------------------------------
void output(PQue& vec)
{
	while(!vec.empty()){
		Proc proc = vec.front();
		vec.pop();
		std::cout << proc.name << " " << proc.time << std::endl;
	}
}
///-------------------------------------------------
PQue calc(PQue queue, int q)
{
	PQue vec;
	int  time = 0;
	while(!queue.empty()){
		if(queue.front().time > q){
			time += q;
			queue.front().time -= q;
			queue.push(queue.front());
		}else{
			time += queue.front().time;
			queue.front().time = time;
			vec.push(queue.front());
		}
		queue.pop();
	}
	return vec;
}
