        name = name1;
        t = time;
    }
    // 残り時間を計算
    unsigned int remainTime(unsigned int time) {
        t -= time;
    }
    unsigned int getTime() {
        return t;
    }
    string getName() {
        return name;
    }
};

P Q[LEN];   // キュー
unsigned int head;   // キューの先頭の場所
unsigned int tail;   // キューの末尾＋ 1 の場所（最後の要素の隣）
unsigned int n;      // キューにいれるプロセスの数

void enqueue(P x) {
    Q[tail] = x;
    tail = (tail + 1) % LEN;
}

P dequeue() {
    P x = Q[head];
    head = (head + 1) % LEN;
    return (x);
}

unsigned int min(unsigned int a, unsigned int b)
{
    return a < b ? a : b;
}

