  void push(Proc d){
    if(isFull()){
      return;
    }
    Q[rp] = d;
    rp = next(rp);
  }
  Proc front(){
    if(isEmpty()){
      Proc er;
      er.tim = -1;
      return er;
    }

    return Q[fp];
  }
  void pop(){
    if(isEmpty()){
      return;
    }
    fp = next(fp);
  }
};

int main(){
  Queue que;

  int n,q;
  cin >> n >> q;

  for(int i=0;i<n;i++){
    Proc p;
    cin >> p.nam >> p.tim;

    que.push(p);
  }

  int total_tim = 0;

  while(!que.isEmpty()){
    Proc p = que.front();
    que.pop();

    if(p.tim <= q){
      total_tim += p.tim;

      cout << p.nam << ' ' << total_tim << endl;
    }else{
      total_tim += q;
      p.tim -=q;

      que.push(p);
    }
  }

  return 0;
}

