using namespace std;

template <class T> class Queue
{
private:
	vector<T> q;
	int head;
	int tail;
	bool is_full;
	bool is_empty;
public:
	Queue(int n)
	{
		q.resize(n);
		head = 0;
		tail = 0;
		is_full = false;
		is_empty = true;
	}
	bool isEmpty()
	{
		return is_empty;
	}
	bool isFull()
	{
		return is_full;
	}
	void enqueue(T a)
	{
		if (this->is_full)
		{
			cout << "ERROR : Queue is full" << endl;
			return;
		}
		else if (this->is_empty)
		{
			this->is_empty = false;
		}
		if (tail == q.size() - 1)
		{
			q[tail] = a;
			tail = 0;
		}
		else
		{
			q[tail++] = a;
		}
		if (tail == head)
		{
			is_full = true;
		}
	}
	T dequeue()
	{
		T ret;
		if (this->is_empty)
		{
			cout << "ERROR : Queue is empty" << endl;
			return NULL;
		}
		else if (this->is_full)
		{
			this->is_full = false;
		}
		if (head == q.size() - 1)
		{
			ret = q[head];
			head = 0;
		}
		else
		{
			ret = q[head++];
		}
		if (tail == head)
		{
			this->is_empty = true;
		}
		return ret;
	}
};

