	Queue<int> q_time(n);
	for (int i = 0; i < n; i++)
	{
		cin >> name >> time;
		q_name.enqueue(name);
		q_time.enqueue(time);
	}
 	int timestamp = 0;
	Queue<string> out_name(n);
	Queue<int> out_time(n);
	while (!q_name.isEmpty())
	{
		name = q_name.dequeue();
		time = q_time.dequeue();
		if (q >= time)
		{
			timestamp += time;
			out_name.enqueue(name);
			out_time.enqueue(timestamp);
		}
		else
		{
			timestamp += q;
			q_name.enqueue(name);
			q_time.enqueue(time - q);
		}
	}
	while (!out_name.isEmpty())
	{
