///-------------------------------------------------
PList calc(PList queue, int q)
{
	PList vec;
	int  time = 0;
	while(!queue.empty()){
		if(queue.front().time > q){
			time += q;
			queue.front().time -= q;
			queue.push_back(queue.front());
		}else{
			time += queue.front().time;
			queue.front().time = time;
			vec.push_back(queue.front());
		}
		queue.pop_front();
	}
	return vec;
}
