};
class Queue{
    private:
        int max;
        Process *array;
        int head;
        int tail;
    public: Queue(int n){
        max = n+1;
        array = new Process[n+1];
        head = 0;tail = 0;
    }
    public: bool isEmpty(){return head==tail;}
    public: bool isFull(){return head == (tail + 1) % max;}

    public: int enqueu(Process o){
        if(isFull()) throw "Overflow";
        array[tail] = o;
        if(tail + 1 == max){
            tail = 0;
        } else{
            tail++;
        }
        return 1;
    }

    public: Process dequeu(){
        if(isEmpty()) throw "Underflow";
        Process o = array[head];
        if(head + 1 == max){
            head = 0;
        } else{
            head++;
        }
        return o;
    }

};

