#define MAX_N 100000

//data structure
typedef struct task
{
    string name;
    int time;
} Task;

class Queue
{
    Task *data; //data pointer
    int pp;     //first position data
    int np;     //next position data
    int size;

public:
    Queue()
    {
        data = NULL;
        pp = np = 0;
        size = 0;
    }
    Queue(int size)
    {
        this->size = size;
        data = new Task[size + 1];
        pp = np = 0;
    }
    ~Queue()
    {
        if (data)
            delete[] data;
    }

    bool enqueue(Task x);

    Task dequeue();

    bool isFull() { return (pp - np) == 1; }

    bool isEmpty() { return (np == pp); }
};

bool Queue::enqueue(Task x)
{
    if (isFull())
    {
        return false;
    }
    else
    {
        data[np++] = x;
        np %= (size + 1);

        return true;
    }
}

Task Queue::dequeue()
{
    if (isEmpty())
    {
        Task null;
        null.time = -1;
        return null;
    }
    else
    {
        Task tmp;

        tmp = data[pp++];
        pp %= (size + 1);

        return tmp;
    }
}

