        tmp.time = atoi(number.c_str());

        task.enqueue(tmp);
    }

    while (!task.isEmpty())
    {
        Task tmp;
        tmp = task.dequeue();

        if (tmp.time > q)
        {
            tmp.time -= q;
            time += q;
            task.enqueue(tmp);
        }
        else
        {
            time += tmp.time;
            cout << tmp.name << " " << time << endl;
        }
    }

    return 0;
}

