#define MAX 100001

struct Process {
  char name[40];
  int time;
};

class Queue {
  Process ps[MAX];
  int head, tail;
  public:
    Queue() {
      head = 0;
      tail = 0;
    }
    void enqueue(Process p) {
      if (!isFull()) {
        ps[tail++] = p;
        tail = tail % MAX;
      } else {
        printf("%d %d\n", head, tail);
        printf("error is happened in enque\n");
        throw;
      }
    }
    Process dequeue() {
      if (!isEmpty()) {
        Process cp = ps[head++];
        head = head % MAX;
        return cp;
      } else {
        printf("error is happened in deque\n");
        throw;
      }
    }
    bool isFull() {
      return (tail % MAX) + 1 == head;
    }
    bool isEmpty() {
      return head == tail;
    }
};

int main() {
  int n, q;
  long long total = 0;
  Process p;
  Queue queue;
