  for ( int i = 0; i < n; i++ ) {
    scanf("%s %d", p.name, &p.time);
    queue.enqueue(p);
  }
  while (!queue.isEmpty()) {
    p = queue.dequeue();
    if (p.time <= q) {
      total += p.time;
      printf("%s %lld\n", p.name, total);
    } else {
      p.time -= q;
      total += q;
      queue.enqueue(p);
    }
  }
  return 0;
}

