struct Queue{
  int table[SIZE];
  int tail,head;

  void init(){
    head=tail=0;
  }

  bool empty(){
    return head==tail;
  }

  void inqueue(int x){
    table[tail]=x;
    tail++;
    tail%=SIZE;
  }

  int dequeue(){
    if(empty())return 0;
    int res=table[head];
    head++;
    head%=SIZE;
    return res;
  }
};

