#include "bits/stdc++.h"

using namespace std;
using ll = long long;
using pll = pair<ll, ll>;

/*********** Constants ***********/
const auto INF = static_cast<ll>(1e15);
const auto MOD = static_cast<ll>(1e9 + 7);

/*********** Variables ***********/
ll N, TIME;
queue<pair<string, ll>> TASK, ANS;

/*********** Functions ***********/
bool init() {
    cin >> N >> TIME;
    for (ll i = 0; i < N; i++) {
        string str; ll time;
        cin >> str >> time;
        TASK.emplace(str, time);
    }
    return true;
}

void solve() {
    ll T = 0;
    while (!TASK.empty()) {
        pair<string, ll> task = TASK.front(); TASK.pop();
        if (task.second > TIME) {
            T += TIME;
            task.second -= TIME;
            TASK.emplace(task);
        }
        else {
            ANS.emplace(task.first, task.second + T);
            T += task.second;
        }
    }
}

void output() {
    while (!ANS.empty()) {
        cout << ANS.front().first << " " << ANS.front().second << endl;
        ANS.pop();
    }
}

int main() {
    init();
    solve();
    output();
    return 0;
}

