#define rep(i, n) for (int i = 0; i < (n); ++i)
using namespace std;

struct Process {
    string name;
    int time;
};

class Queue {
  public:
    Queue(int size = 100005);
    void enqueue(Process);
    Process dequeue();
    bool is_empty();

  private:
    Queue(const Queue &src);
    Process *process;
    int size_;
    int head_;
    int tail_;
};

Queue::Queue(int size) : size_{size} {
    process = new Process[size_];
    head_ = tail_ = 0;
}

void Queue::enqueue(Process p) {
    process[tail_] = p;
    tail_ = (tail_ + 1) % size_;
}

Process Queue::dequeue() {
    Process p = process[head_];
    head_ = (head_ + 1) % size_;
    return p;
}

bool Queue::is_empty() {
    return head_ == tail_;
}

