	ss = std::istringstream(sInput);
	ss >> iInputProcessCnt;
	if (iInputProcessCnt > 100000 || 1 > iInputProcessCnt)
	{
		exit(0);
	}
	// プロセスの処理一回にかける時間の取得
	std::cin >> sInput;
	ss = std::istringstream(sInput);
	ss >> iInputUseTime;
	if (iInputUseTime > 1000 || 1 > iInputUseTime)
	{
		exit(0);
	}

	// プロセス名とプロセスの処理時間キューにプッシュ
	std::queue<std::string> queName;
	std::queue<int> queTime;
	std::string sInputName;
	int iTime;
	for (int i = 0; i < iInputProcessCnt; i++)
	{
		std::cin >> sInputName;
		queName.push(sInputName);
		std::cin >> sInput;
		ss = std::istringstream(sInput);
		ss >> iTime;
		queTime.push(iTime);
	}

	// プロセスを処理した順に合計時間とともに出力
	int goukei = 0;
	int iTemp;
	std::string sTemp;
	while (1)
	{
		if (queTime.empty() == true)
		{
			break;
		}
		for (unsigned int i = 0; i < queTime.size(); i++)
		{
			if (queTime.front() <= iInputUseTime)
			{
				goukei += queTime.front();
				std::cout << queName.front() << " " << goukei << std::endl;
				// 処理が終了したものから要素を消していく
				queTime.pop();
				queName.pop();
			}
			else
			{
				goukei += iInputUseTime;
				queTime.front() -= iInputUseTime;
				iTemp = queTime.front();
				sTemp = queName.front();
				queTime.pop();
				queName.pop();
				queTime.push(iTemp);
				queName.push(sTemp);
			}
		}
	}
}

