template<typename T> class Queue_FIFO
{
public:
	Queue_FIFO(int size)
	{
		m_Queue.clear();
		m_Queue.resize(size + 1);
		m_max = size + 1;

		// それぞれ存在する要素を指す
		m_head = 0;
		m_tail = size;
	}

	T& operator[](int index)
	{
		return m_Queue[index];
	}

	// 要素の追加
	bool Push(T element)
	{
		if (IsMax())
		{
			return false;
		}
		m_Queue[m_tail] = element;
		m_tail = (m_tail + 1) % m_max;
		return true;
	}

	// 要素の取得と削除
	T Pop()
	{
		int index = m_head;
		m_head = (m_head + 1) % m_max;
		return m_Queue[index];
	}

	int Size()
	{
		if (m_head > m_tail)
		{
			return m_head - m_tail;
		}
		return m_head + (m_max - m_tail);
	}

	bool IsEmpty()
	{
		return (m_head == m_tail) ? true : false ;
	}

private:

	bool IsMax()
	{
		return (m_head == (m_tail + 1) % m_max) ? true : false ;
	}

	vector<T> m_Queue;

	// 要素の先頭と最後尾を表すIndex
	int m_head;
	int m_tail;

	int m_max;
};

struct INFO
{
