	{
		name = "";
		processTime = 0;
	}
	INFO(string str, int time)
	{
		name = str;
		processTime = time;
	}
};

int main() {

	int n, q;
	cin >> n >> q;


	Queue_FIFO<INFO> vProcess(n);

	for (int i = 0; i < n; i++)
	{
		cin >> vProcess[i].name >> vProcess[i].processTime;
	}

	int totalTime = 0;
	vector<INFO> vResult;
	while (vProcess.IsEmpty() == false)
	{
		INFO tmp = vProcess.Pop();
		if (tmp.processTime <= q)
		{
			totalTime += tmp.processTime;
			// 処理完了
			cout << tmp.name << " " << totalTime << endl;
		}
		else
		{
			// 処理続行
			tmp.processTime -= q;
			totalTime += q;
			vProcess.Push(tmp);
		}
	}

	return 0;
}

