#define MAX 100005
#define min(a,b) a<b?a:b

typedef struct
{
	char name[100];
	int time;
}elem;

typedef struct
{
	int length=0;
	int front=0;
	elem Q[MAX];
}Queue;

void EnQueue(Queue &Q, elem e)
{
	int rear = (Q.front + Q.length) % MAX;
	Q.length++;
	Q.Q[rear] = e;
}

elem pop(Queue &Q)
{
	elem t = Q.Q[Q.front];
	Q.front = (Q.front + 1 + MAX) % MAX;
	Q.length--;
	return t;
}

int main()
{
	int  n = 0;
	scanf("%d", &n);
