		strcpy(t.name, name);
		t.time = time;
		EnQueue(Q, t);
	}
	int sum = 0;
	while (Q.length)
	{
		elem t = pop(Q);
		int m = min(q, t.time);
		t.time -= m;
		sum += m;
		if (t.time > 0)
			EnQueue(Q, t);
		else
			printf("%s %d\n", t.name , sum);
	}
