#include <iostream>
using namespace std;

int Q = 0;
int N = 0;
struct Pos
{
	int in;
	int out;
}POS;

struct Proc
{
	char name[11];
	int time;
}PQ[100000+1];

int enQueue(Proc p)
{
	int temp = POS.in + 1;
	if (temp > N)
	{
		temp = 0;
	}
	if (POS.out == temp)
	{
		//printf("Err: Queue Over Run\n");
		return -1;
	}
	POS.in = temp;
	PQ[POS.in]= p;
	return 0;
}

int deQueue(Proc *p)
{
	if (POS.out == POS.in)
	{
		//printf("Err: Queue is Empty.\n");
		return -1;	// empty
	}
	POS.out++;
	if (POS.out > N)
	{
		POS.out = 0;
	}
	*p = PQ[POS.out];
	return 0;
}

void initializeQueue()
{
	POS.in = 0;
	POS.out = 0;
}

int main()
{
	initializeQueue();

	cin >> N >> Q;
	for (int i = 0; i < N; i++)
	{
		Proc inputP;
		cin >> inputP.name >> inputP.time;
		if (enQueue(inputP) < 0)
		{
			return -1;
		}
	}

	int time = 0;
	Proc p;
	while (deQueue(&p) == 0)
	{
		if (p.time <= Q)
		{
			time = time + p.time;
			cout << p.name << " " << time << endl;
		}
		else
		{
			time = time + Q;
			p.time = p.time - Q;
			enQueue(p);
		}
