#define LEN 100005

typedef struct pp
{
    char name[100];
    int t;
} P;

class queue
{
public:
    P Q[LEN];
    int head;
    int tail;
    queue()
    {
        head = 0;
        tail = 0;
    }
    bool isEmpty()
    {
        return head == tail;
    }
    bool isFull()
    {
        return head == (tail + 1) % LEN;
    }
    void enqueue(P x)
    {
        Q[tail] = x;
        tail = (tail + 1) % LEN;
    }
    P dequeue()
    {
        P x = Q[head];
        head = (head + 1) % LEN;
        return x;
    }
};

int main()
{
    queue que;
    int n, q;
    int elaps = 0;
    int c;
    P u;
    cin >> n >> q;

    for (int i = 0; i < n; i++)
    {
