        cin >> que.Q[i].t;
    }

    que.head = 1;
    que.tail = n + 1;
    while (que.head != que.tail)
    {
        u = que.dequeue();
        c = std::min(q, u.t);
        u.t -= c;
        elaps += c;
        if (u.t > 0)
            que.enqueue(u);
        else
        {
            printf("%s %d\n", u.name, elaps);
        }
    }

    return 0;
}

