vector<string> split_naive(string &s, char delim) {
    vector<string> elems;
    string item;
    for (char ch: s) {
        if (ch == delim) {
            if (!item.empty())
                elems.push_back(item);
            item.clear();
        }
        else {
            item += ch;
        }
    }
    if (!item.empty())
        elems.push_back(item);
    return elems;
}
typedef struct Proc {
     string name;
     int time;
} proc;

vector<proc> schedule(deque<proc> &p, int q) {
    int use_time = 0;
    vector<proc> end;
    while (!p.empty()) {
        int remain = q;
        while (remain > 0 && !p.empty())
        {
            proc first = p.front();
            p.pop_front();
            if (first.time > remain)
            {
                first.time -= remain;
                use_time += remain;
                remain = 0;
                p.push_back(first);
            }
            else
            {
                remain = 0;
                use_time += first.time;
                proc n = {first.name, use_time};
                end.push_back(n);
            }
        }
    }
    return end;
}

