using namespace std;

namespace {

struct Proc {
  char name[12];
  int time;
};

class Queue {
 public:
  explicit Queue(size_t size)
      : size_(size), buf_(new Proc[size + 1]), head_(0), tail_(0) {}

  void Enqueue(Proc& p) {
    assert(!IsFull());
    buf_[tail_] = p;
    tail_ = next(tail_);
  }

  Proc& Dequeue() {
    assert(!empty());
    Proc& p = buf_[head_];
    head_ = next(head_);
    return p;
  }

  bool empty() const { return head_ == tail_; }

  bool IsFull() const {
    return (head_ == 0 && tail_ == size_) || head_ == tail_ + 1;
  }

 private:
  size_t next(size_t p) const { return p == size_ ? 0 : p + 1; }

  size_t size_;
  unique_ptr<Proc[]> buf_;
  size_t head_;
  size_t tail_;
};

}  // namespace

