template <typename M>
struct Queue {
  vector<M> members;
  int push_index = 0;

  void push(M m) {
    members.push_back(m);
    push_index++;
  }

  M pop() {
    M m = members[0];
    rotate(members.begin(), members.begin() + 1, members.end());
    members.pop_back();
    push_index--;
    return m;
  }

  int size() {
    return push_index;
  }

  bool empty() {
    return push_index == 0;
  }
};

void print(Queue<Process> queue, int n) {
  printf("[ ");
  for (int i = 0; i < queue.size(); i++) {
    Process p = queue.members[i];
    printf("[ %s %d ] ", p.name, p.time);
  }
  printf("]\n");
}

