template<typename T>
class queue {
public:
    explicit
    queue(int size) : size_(size), head_(0), tail_(0), data_(std::make_unique<T[]>(size)) {}

    void enqueue(T x) {
        data_[tail_] = x;
        tail_ = (tail_ + 1) % size_;
    }

    T dequeue() {
        auto x = data_[head_];
        head_ = (head_ + 1) % size_;
        return x;
    }

    bool is_empty() {
        return head_ == tail_;
    }

    bool is_full() {
        return tail_ == size_;
    }

private:
    int size_;
    int head_;
    int tail_;
    std::unique_ptr<T[]> data_;
};

