    for (int i = 0; i < n; ++i) {
        proc p;
        std::cin >> p.name_ >> p.value_;
        proc_q.enqueue(p);
    }

    int elapsed_time = 0;
    while (true) {
        auto p = proc_q.dequeue();
        if (p.value_ > 0) {
            elapsed_time += std::min(p.value_, q);
            p.value_ = std::max(p.value_ - q, 0);
            if (p.value_ == 0) {
                std::cout << p.name_ << " " << elapsed_time << std::endl;
            }
            else {
                proc_q.enqueue(p);
            }
        }

        if (proc_q.is_empty()) {
            break;
        }
    }

    return 0;
}

