    int time;
}Process;

class ProcessQueue
{
private:
    int m_Tail;
    int m_Head;
    int m_Size;
    Process* m_Queue;

public:
    ProcessQueue(int size):
    m_Size(size + 1),
    m_Head(0),
    m_Tail(0)
    {
        m_Queue = new Process[m_Size];
    };

    ~ProcessQueue()
    {
        delete[] m_Queue;
    };

    bool enqueue(Process val)
    {
        m_Queue[m_Tail] = val;
        m_Tail++;
        if(m_Tail == m_Size)
        {
            m_Tail = 0;
        }
        return true;
    }

    bool dequeue(Process* val)
    {
        if(isEmpty())
        {
            return false;
        }
        *val = m_Queue[m_Head];
        m_Head++;
        if(m_Head == m_Size)
        {
            m_Head = 0;
        }
        return true;

    }

private:
    bool isEmpty()
    {
        if(m_Head == m_Tail)
        {
            return true;
        }
        else
        {
            return false;
        }
    };

    bool isFull()
    {
        if( (m_Tail+1) % m_Size == m_Head)
        {
            return true;
        }
        else
        {
            return false;
        }

    }
};

