      return head == (tail + 1) % queue_size;
    }
    void enqueue(T x){
      if(isFull()){
        cout << "error";
      }else{
        queue[tail] = x;
        if(tail + 1 == queue_size){
          tail = 0;
        }else{
          tail++;
        }
      }
    }
    T dequeue(){
      if(isEmpty()){
        cout << "error Empty";
      }else{
        T x = queue[head];
        if(head + 1 == queue_size){
          head = 0;
        }else{
          head++;
        }
        return x;
      }
    }
  private:
    int head;
    int tail;
    T queue[queue_size];
};


