		 if (isEmpty()) return NULL;
		task* t = Q[m_iHead];
		if (m_iHead + 1 == m_iMAX) {
			m_iHead = 0;
		}
		else {
			m_iHead++;
		}
		return t;
	}

	 task ** getQ() {
		 return Q;
	 }

