typedef struct {
	char name[11] = "\0";
	int time;
} P;

class Queue {
private:
	int size;
	P *queue;
	int head = 0;
	int tail = 0;
public:
	Queue(int n);
	void enqueue(P p);
	void dequeue();
	bool isEmpty();
	P *get();
	void clear()
}

Queue::Queue(int n)
{
	size = n;
	queue = new P[n];
}

void Queue::enqueue(P p)
{
	queue[tail] = p;
	tail = (tail + 1) % size;
}

void Queue::dequeue()
{
	head = (head + 1) % size;
}

bool Queue::isEmpty()
{
	return head == tail;
}

P *Queue::get()
{
	return &queue[head];
}

void Queue::clear()
{
	delete[] queue;
}

int main(void)
{	
	int n, q;
	cin >> n >> q;

	Queue queue(n);
	for (int i = 0; i < n; i++) {
		P p;
		cin >> p.name;
		cin >> p.time;
		queue.enqueue(p);
	}

	int time = 0;
	while (!queue.isEmpty()) {
		P *p = queue.get();
		if (p->time <= q) {
			time += p->time;
			queue.dequeue();
			cout << p->name << " ";
			cout << time << endl;
		} else {
			time += q;
			p->time -= q;
			queue.dequeue();
			queue.enqueue(p);
		}
	}

	queue.clear();
	return 0;
}

