using namespace std;

template <class T>
class Queue{
  //メンバ関数
public:
  struct Node{
    Node* prev; //前のノードへのポインタ
    Node* next; //後のノードへのポインタ
    T value; //このノードに格納されているデータ
  };
private:
  Node* top;
  Node* end;
  int max;
  int element_num;
public:
  Queue(int num);
  T dequeue();
  void enqueue(T val);
  bool isEmpty();
  bool isFull();
};

template <class T>
Queue<T>::Queue(int num){
  top = end = nullptr;
  max = num;
  element_num = 0;
}

template <class T>
T Queue<T>::dequeue(){
  if(isEmpty()){
    printf("This Queue is empty.\n");
    //return nullptr;
    //部分型を考えるとTにできることが全部できるものでないと返り値としては適切でない。それにnullptrはもちろんポインタ限定なので無理かな。
    exit(1);
  }
  T out = top->value;
  top = top->next;
  if(element_num > 1){
    delete top->prev;
    top->prev = nullptr;
  }
  else{//要素が1個の時
    delete end;
    end = nullptr;
  }
  element_num--;
  return out;
}

template <class T>
void Queue<T>::enqueue(T val){
  if(isFull()){
    printf("This Queue is full.\n");
    return;
  }
  Node* next_end = new Node;
  next_end->value = val;
  next_end->next = nullptr;
  next_end->prev = end;
  if(isEmpty()){
    top = next_end;
  }
  else{
    end->next = next_end;
  }
  end = next_end;
  element_num++;
  return;
}

template <class T>
bool Queue<T>::isEmpty(){
  if(element_num == 0) return true;
  return false;
}

template <class T>
bool Queue<T>::isFull(){
  if(element_num == max) return true;
  return false;
}

