struct process {
    char name[10];
    int time;
};


void out (struct process a, int t)
{
    for (int i = 0; i < strlen(a.name); i++)
        printf("%c", a.name[i]);
    printf(" %d\n", t);
}

void scheduling(struct process a[], int n, int qms)
{
    int head = 0; int tail = n-1;
    int t_sum = 0;
    while (head != tail ){
        if (a[head].time <= qms){
            t_sum += a[head].time;
            out(a[head], t_sum);
            if (head == n-1)
                head = 0;
            else
                head++;
            }
        else{
            a[head].time -= qms;
            t_sum += qms;
            struct process tmp = a[head];
            if (head == n-1)
                head = 0;
            else
                head++;
            if (tail == n-1)
                tail = 0;
            else
                tail++;
            a[tail] = tmp;
        }
    }
    out(a[head], t_sum + a[head].time);
}

