struct Process
{
    char name[10];
    int time;
    Process(int t=0) : time(t) {}
};

class Queue
{
    int nelem, head, tail;
    Process *vec;

public:
    Queue(int n) : nelem(n), head(0), tail(n), vec(new Process[nelem+1]) {
        set_vec();
    }

    void set_vec(){
        for(int i=0; i < nelem; i++){
            cin >> vec[i].name >> vec[i].time;
        }
    }

    void inqueue(Process& v){
        if(tail == nelem + 1) tail = 0;
        vec[tail++] = v;
    }

    Process& dequeue(){
        if(head == nelem){
            head = 0;
            return vec[nelem];
        }
        return vec[head++];
    }

    bool empty(){
        return head == tail;
    }
};

