#include <bits/stdc++.h>
using namespace std;
#define Size 200000

// キューで実装すべき機能は以下の通り
// initialization -> void init()
// emptyの判定 -> empty()
// キューへ要素を定数時間で加える ->  push()
// キューの要素を定数時間で取り出す -> pop()

struct Queue{

    int table[Size];
    int tail, head; // headはキューの先頭を指す　tailはキューの末尾+1の場所を指す

    // initialization
    void init(){
        head = tail = 0;
    }

    bool empty(){
        return head == tail;
    }

    void push(int x){
        table[tail] = x;
        tail++;
        tail %= Size; // ポインタを循環させる
    }

    int pop(){
        if (empty()) return 0;

        int result = table[head]; // FIFO
        head++;
        head %= Size; // ポインタを循環させる
        return result;
    }

};

int main(){

    Queue queue, queue2;

    int n, q, num;

    string table[Size];

    cin >> n >> q;

    queue.init();
    queue2.init();

    for (int i = 0; i < n; i++){
        cin >> table[i] >> num;

        queue.push(num);
        queue2.push(i);
    }

    int now = 0, a, b;

    while(!queue.empty()){

        a = queue.pop();
        b = queue2.pop();

        if (a <= q){
            now += a, cout << table[b] << " " << now << endl; 
        }
        else{
            now += q;
            a -= q;
            queue.push(a);
            queue2.push(b);
        }
    }

}

