struct Task{
  string name;
  int tim;
};

template<typename T>
class Q{
  T* t;
  int head,tail,n;
  public:
  Q(int n) : head(0),tail(1),n(n+1) {
    t = new T[n];
  }
  ~Q(){
    delete [] t;
  }
  void enqueue(T _t){
    if(head==tail) throw 1;
    t[(tail-1)%n] = _t;
    tail++;
  }
  T dequeue(){
    if(head+1==tail) throw 2;
    T _t =t[head%n];
    head++;
    return _t;
  }
};

int main(){
  int n,q; cin>>n>>q;
  string name; int tim;
  Q<Task> que(n);
  for(int i=0;i<n;i++){
    Task t;
    cin>>t.name>>t.tim;
    que.enqueue(t);
  }

  int sumq = 0;
  try{
    while(true){
      Task task;
      task = que.dequeue();
      if(task.tim > q){
        task.tim -= q;
        que.enqueue(task);
        sumq += q;
      }else{
        cout<<task.name<<' '<<sumq+task.tim<<endl;
        sumq += task.tim;
      }
    }
  }catch(int err){
    que = NULL;
  } 
}

