using namespace std;

struct Queue
{
    int work[SIZE];
    int head, tail;


    void init()
    {
        head = tail = 0;
    }

    bool empty()
    {
        return head == tail;
    }

    void inqueue(int x)
    {
        work[tail++] = x;
        tail %= SIZE;
    }

    int dequeue()
    {
        int a = work[head++];
        head %= SIZE;
        return a;
    }
};

int main()
{
