    cout << mData[mHead].second << " " << mTimeFromStart << endl;
    mDone++;
};

int queue::calculate(int time){
    if(mData[mHead].first != 0) {
        if(mData[mHead].first - time <= 0) {
            int rest_time = time - mData[mHead].first;                        
            mTimeFromStart += mData[mHead].first;                
            mData[mHead].first = 0;
            dequeue();
            return 0;
        }
        else {
            mData[mHead].first -= time; 
            mTimeFromStart += time;
            return 0;
        }
    }
    else {
        return time;
    }
};

void queue::operation (){
    int operation_time = mOperationTime;
    while(1){
        operation_time = calculate(operation_time);
        if(operation_time==0) {
            operation_time = mOperationTime;
        }
        mHead++;
        if(mHead == mBufferSize) {
            mHead = 0;
        }
        if(mDone == mBufferSize) {
            break;
        }
    }
    return;
}

