class Process {
public:
  Process() {};
  Process(string name, int workload);
  ~Process() {};
  int run(int time);
  bool isDone();
  inline string name() { return name_; }
  inline int workload() { return workload_; }
private:
  string name_;
  int workload_;
};

Process::Process(string name, int workload) :
  name_(name),
  workload_(workload) {}

int Process::run(int time)
{
  if (workload_ > time) {
    workload_ -= time;
    return time;
  } else {
    int consume = workload_;
    workload_ -= consume;
    return consume;
  }
}

bool Process::isDone()
{
  return (workload_ <= 0);
}


