  Queue(vector<int> vec,int size){
    head=0;
    tail=0;
    queue=vec;
    length=size;
  }
  Queue(vector<int> vec,vector<string> prcss,int size){
    head=0;
    tail=0;
    queue=vec;
    length=size;
    str_queue=prcss;
  }

  bool isEmpty(){
    if(head==tail) return true;
    else return false;
  }

  bool isFull(){
    if((head+1)%length==tail) return true;
    else return false;
  }

  bool enqueue(int value){
    if((head+1)%length==tail) return false;
    else{
      queue.at(head)=value;
      head=(head+1)%length;
    }
  }

  int dequeue(){
    if(head==tail) return -1;
    else{
      int idx=tail;
      tail=(tail+1)%length;
      return queue.at(idx);
    }
  }
    bool enqueue_v2(int value,string pname){
      if((head+1)%length==tail) return false;
      else{
        queue.at(head)=value;
        str_queue.at(head)=pname;
        head=(head+1)%length;
      }
    }

    void dequeue_v2(){
      if(head==tail);
      else{
        int idx=tail;
        tail=(tail+1)%length;
      }
  }

  int get_tail(){
    if(head==tail) return -1;
    else return queue.at(tail);
  }

  string get_tail_str(){
    if(head==tail) return "\0";
    else return str_queue.at(tail);
  }
};

