    for (int i = 0; i < n; ++i) {
        getline(std::cin, buf);
        schedules.enqueue(
            buf.substr(0, buf.find(' ')),
            std::stoi(buf.substr(buf.find(' ') + 1, buf.size())));
    }
    process(schedules, q);

    return 0;
}

