void remove(Process *process,int pronum){
  for ( int i = 0 ; i < pronum - 1; i++){
    process[i].name = process[i+1].name;
    process[i].time = process[i+1].time;
  }
}

void move(Process *process,int pronum){
  Process temp;
  temp.name = process[0].name;
  temp.time = process[0].time;
  for ( int i = 0 ; i < pronum - 1 ; i++){
    process[i].name = process[i+1].name;
    process[i].time = process[i+1].time;
  }
  process[pronum - 1].name = temp.name;
  process[pronum - 1].time = temp.time;
}

void output(Process *process,int pronum){
  for ( int i = 0 ; i < pronum ; i++){
    cout << "process[" << i << "]:" << process[i].name << " " << process[i].time << endl;
  }
}

