	q[tail] = a;
	tail++;
	if (tail >= SIZE) {
		tail -= SIZE;
	}
}

int queue::dequeue() {
	int a=q[head];
	head++;
	if (head >= SIZE) {
		head -= SIZE;
	}
	return a;
}
void queue::init() {
	head = 0;
	tail = 0;
}

