#include<cstdio>

const int N_MAX = 100000;

struct Process{
  char name[10];
  int time;
};

Process Queue[N_MAX]; //ring buffer
int head = 0,tail = 0;

bool isEmpty(){
  return head == tail;
}

void enqueue(Process x){
  Queue[tail] = x;
  if(tail + 1 == N_MAX){
    tail = 0;
  }else{
    tail++;
  }
}

Process dequeue(){
  Process x = Queue[head];
  if(head + 1 == N_MAX){
    head = 0;
  }else{
    head++;
  }

  return x;
}

int main(){
  int n,q,sum=0;
  Process p[N_MAX];

  std::scanf("%d %d",&n,&q);

  for(int i = 0;i < n;i++){
    std::scanf("%s %d",p[i].name,&(p[i].time));
    enqueue(p[i]);
  }

  while(!(isEmpty())){
    Process x = dequeue();
    if(x.time - q <= 0){
      std::printf("%s %d\n",x.name,x.time + sum);
      sum += x.time;
    }else{
      x.time -= q;
      enqueue(x);
      sum += q;
    }
  }

  return 0;
}

