using namespace std;

struct Task {
    string name;
    int time;
    Task(string name, int time) : name(name), time(time) {}
};

struct RoundRobin {
    const int maxDur;
    int time;
    vector<Task> data;

    RoundRobin(int dur) : maxDur(dur), time(0) {}
    void addTask(Task t) {
        this->data.push_back(t);
    }
    void doSchedule() {
        while (not this->data.empty()) {
            auto task = this->data[0];
            this->time += min(task.time, maxDur);
            int rem = task.time - this->maxDur;
            if (rem > 0) {
                task.time = rem;
                this->data.push_back(task);
            } else {
                cout << task.name << " " << this->time << endl;
            }
            this->data.erase(this->data.begin());
        }
    }
};

int main() {
    int n, q;
    cin >> n >> q;

    RoundRobin rr(q);

    string name;
    int time;
    for (int i=0; i<n; i++) {
        cin >> name >> time;
        Task t(name, time);
        rr.addTask(t);
    }

    rr.doSchedule();

    return 0;
}

