template<class T>
class Queue{
  private:
    int head;
    int tail;
    T Q[queue_max_size];
  public:
    Queue(){
      head = tail = 0;
    }
    bool isEmpty(){
      return head == tail;
    }
    bool isFull(){
      return head == (tail + 1) % queue_max_size;
    }
    void push(T x){
      if(isFull()){
        cout << "Error Full" <<endl;
        assert(!isFull());
      }
      Q[tail] = x;
      tail = (tail + 1) % queue_max_size;
    }
    T front(){
      if(isEmpty()){
        cout << "Error Empty" <<endl;
        assert(!isEmpty());
      }
      return Q[head];
    }
    void pop(){
      if(isEmpty()){
        cout << "Error Empty" <<endl;
        assert(!isEmpty());
      }
      head = (head + 1) % queue_max_size;
    }
};
