using namespace std;

class Queue{
public:
	int* Q;
	int head;
	int tail;
	int size;

	Queue(int n);
	~Queue();
	Queue(const Queue &other);

	void enqueue(int x);
	int dequeue();
	bool isEmpty();
	bool isFull();
};

Queue::Queue(int n){
	Q = new int[n + 1];
	size = n + 1;
	head = 0;
	tail = 0;
	return;
}

Queue::Queue(const Queue &other){
	Q = new int[other.size];
	size = other.size;
	head = other.head;
	tail = other.tail;
	copy(other.Q, other.Q + size, Q);
}

Queue::~Queue(){
	delete[] Q;
}

void Queue::enqueue(int x){
	Q[tail] = x;
	tail = (tail + 1) % size;
	return;
}

int Queue::dequeue(){
	int x = Q[head];
	head = (head + 1) % size;
	return x;
}

bool Queue::isEmpty(){
	return (tail == head);
}

bool Queue::isFull(){
	return (tail - head == size - 1 || tail - head == -1);
}

