template<typename T>
struct Queue {
  vector<T> q;
  int head, tail;
  int MAX;
  Queue(int N_MAX) {
    MAX = N_MAX;
    q = vector<T>(MAX);
    head = tail = 0;
  }
  bool isEmpty() {
    return head == tail;
  }
  bool isFull() {
    return head == (tail + 1)%MAX;
  }
  void enqueue(T x) {
    assert(!isFull());
    q[tail] = x;
    if (tail + 1 == MAX) tail = 0;
    else tail++;
  }
  T dequeue() {
    assert(!isEmpty());
    T x = q[head];
    if (head + 1 == MAX) head = 0;
    else head++;
    return x;
  }
};

