struct task {
  string name;
  int time;
};

#define MAX_N (100100)
task tq[MAX_N];
int head, tail;

int size() {
  if (tail >= head) return tail - head;
  else return MAX_N - (head - tail);
}

bool empty() {
  return size() == 0;
}

bool full() {
  return size() == MAX_N - 1;
}

void push(const task& t) {
  if (full()) {
    cerr << "Stack is full" << endl;
    exit(1);
  }
  tq[tail] = t;
  tail = (tail+1)%MAX_N;
}

task pop() {
  if (empty()) {
    cerr << "Stack is empty" << endl;
    exit(1);
  }
  task& res = tq[head];
  head = (head+1)%MAX_N;
  return res;
}

