class Process {
public:
  Process() {};
  Process(string name, int workload);
  ~Process() {};
  int run(int time);
  bool isDone();
  inline string name() { return name_; }
  inline int workload() { return workload_; }
private:
  string name_;
  int workload_;
};

Process::Process(string name, int workload) :
  name_(name),
  workload_(workload) {}

int Process::run(int time)
{
  if (workload_ > time) {
    workload_ -= time;
    return time;
  } else {
    int consume = workload_;
    workload_ -= consume;
    return consume;
  }
}

bool Process::isDone()
{
  return (workload_ <= 0);
}


#ifdef RINGBUF
// Ring buffer
// One of issues is that it needs to determine variable data when construting Queue
// Since not appropriate to design queue with ring buffer...
template <class T>
class Queue {
public:
  Queue(int capacity);
  ~Queue();
  void push(T d);
  void pop();
  T front();
  bool empty();
  bool full();
private:
  int capacity_;
#ifdef DEBUG
public:
#else //DEBUG
private:
#endif //DEBUG
  T* d_;
  int put_, get_;
};


template <class T>
Queue<T>::Queue(int capacity) :
  capacity_(capacity),
  put_(0),
  get_(0)
{
  d_ = new T[capacity_];
}

template <class T>
Queue<T>::~Queue()
{
  delete [] d_;
}

template <class T>
void Queue<T>::push(T d)
{
  if (full()) {
    cout << "FULL!!" << endl;
    return ;
  }
  d_[put_] = d;
  put_ = (put_ + 1 ) % capacity_;
}

template <class T>
void Queue<T>::pop()
{
  if (empty()) {
    cout << "EMPTY!!" << endl;
    return ;
  }
  get_ = (get_ + 1 ) % capacity_;
}

template <class T>
T Queue<T>::front()
{
  return d_[get_];
}

template <class T>
bool Queue<T>::full()
{
  return get_ == ((put_ + 1) % capacity_);
}

template <class T>
bool Queue<T>::empty()
{
  return (put_ == get_);
}
