    int N, Q, clock=0;
    queue<Process> readyQue;
    cin>>N>>Q;
    for(int i=0; i<N; i++){
        string name;
        int remainTime;
        cin>>name>>remainTime;
        readyQue.push(Process(name, remainTime));
    }
    while(!readyQue.empty()){
        Process currentProcess=readyQue.front();
