struct Node
{
    int value;
    Node* pre;
    Node* next;
};
Node* nil;//申请指向首结点的指针
void initialize(void)
{
    nil=(Node*)malloc(sizeof(Node));
    nil->next=nil;
    nil->pre=nil;

}
void Insert(int key)//在链表开头添加元素x
{
    Node* x=(Node*)malloc(sizeof(Node));
    x->value=key;
    x->pre=nil;
    x->next=nil->next;
    nil->next=x;
}
void Delete(int key)
{
    Node* flag=nil;
    while(flag->next!=nil&&flag->next->value!=key)
    {
    flag=flag->next;
    }
    if(flag->next->value==key)
    {

    flag->next->next->pre=flag;
    flag->next=flag->next->next;
   // free(flag->next);
    }


}
void DeleteFirst(void)
{
    Node* flag=nil->next;
    nil->next=flag->next;
    flag->next->pre=nil;
    free(flag);
}
void DeleteLast(void)
{
    Node* flag=nil->pre;//指向最后一个元素
    flag->pre->next=flag->next;
    nil->pre=flag->pre;
}
void PRINT(void)
{
    Node* flag=nil;
    while(flag->next!=nil)
    {
    flag=flag->next;
    printf("%d ",flag->value);
    }
    printf("\n");
}
int main()
{
    int n;
    initialize();
    scanf("%d",&n);
    for(int i=0;i<n;i++)
    {
        char order[20];
        int x;
        scanf("%s",order);
        scanf("%d",&x);
        if(strcmp(order,"insert")==0)
        {
        Insert(x);
        }
        else if(strcmp(order,"delete")==0)
        {
        Delete(x);
        }
        else if(strcmp(order,"deleteFirst")==0)
        {
        DeleteFirst();
        }
        else
        {
        DeleteLast();
        }
    }
    PRINT();
    return 0;
}

