constexpr int Q_MAX = 131072;

template<typename T>
class MyQueue {
public:
	MyQueue() : list(new T[Q_MAX]), head(0), tail(1), size(0) {}

	~MyQueue()
	{
		delete[] list;
	}

	void inq(T val)
	{
		if (tail == head) {
			throw runtime_error("queue is full");
		}
		list[tail] = val;
		size++;
		tail = (tail + 1) % Q_MAX;
	}

	T deq()
	{
		if (size == 0) {
			throw runtime_error("queue is empty");
		}
		head = (head + 1) % Q_MAX;
		size--;
		return list[head];
	}

	int get_size()
	{
		return size;
	}
private:
	T* list;
	int head;
	int tail;
	int size;
};

