	}

bool isEmpty(){      //队列为空 
	return tail == head;
}

bool isFull(){        //队列为满 
	return (tail+1)%LEN == head;
}	

void enqueue(int x,char s[]) //入队 
{
	if(isFull())
	{
		printf("队列已满，上溢"); 
	}
	else
	{	
		Q[tail].t = x;
		strcpy(Q[tail].name,s);
		tail = (tail+1)%LEN;
	}
} 

P dequeue(void)     //出队   
{
	P X;
	if(isEmpty())
	{
		printf("队列为空，下溢"); 
	}
	else
	{
		X=Q[head];
		head = (head+1)%LEN;
			return X;
	}
}

