struct process{
    string name;
    int time;
};

struct processQueue{
    static const int queue_max = 1000000;
    process queue[queue_max];
    int top;
    int index;
    processQueue():top(0), index(0){};
    bool is_empty(){
        return top == index;
    }
    void push_back(process in){
        queue[index] = in;
        index ++;
        if(index >= queue_max)
            index = 0;
    }
    process pop_front(){
        process ret = queue[top];
        top ++;
        if(top >= queue_max)
            top = 0;
        return ret;
    }
    void printQueue(){
        for(int i=0; i<index; i++){
            cout << i << ":" << queue[i].name << ", "<< queue[i].time << endl;
        }
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    processQueue que;
    for(int i=0; i<n; i++){
        process temp;
        cin >> temp.name;
        cin >> temp.time;
        que.push_back(temp);
    }
    int count = 0;
    while(!que.is_empty()){
        process temp = que.pop_front();
        if(temp.time - q > 0){
            temp.time -= q;
            que.push_back(temp);
            count += q;
        }else{
            count += temp.time;
            cout << temp.name << " " << count << endl;
        }
    }
}

