class Process{
	string name;
	int t;
public:
	Process(string n, int i) : name(n), t(i){}
	Process() : name(""), t(0){}
	int execute(int j){return t -= j;};
	string get_name(){return name;};
	int get_time(){return t;};
};
int main(){
	int n, j;
	cin >> n >> j;
	Process queue[n];
	string name;
	int t;
	for (int i = 0; i < n; i ++){
		cin >> name >> t;
		queue[i] = Process(name, t);
	}
	int i = 0, last = 0, nt= 0, s = n, temp = 0;
	while (s > 0){
		nt += j;
		temp = queue[i].execute(j);
		if (temp <= 0){
			nt += temp;
			cout << queue[i].get_name() << " " << nt << "\n";
			s -= 1;
			i = (i + 1) % n;
		}else{
			queue[last] = queue[i];
			i = (i + 1) % n;
			last = (last + 1) % n;
		}
	}
}

