struct Process {
public:
    char name[10];
    int time;
};

class Queue {
public:
    Process* data;
    int first = 0;
    int last = 0;
    int max;

    Queue(int max) : max(max) {
        data = new Process[max];
    }

    void enqueue(Process p) {
        data[last] = p;

        if (last + 1 >= max) {
            last = 0;
        } else {
            last++;
        }
    }

    Process dequeue() {
        Process p = data[first];

        if (first + 1 >= max) {
            first = 0;
        } else {
            first++;
        }

        return p;
    }
};

int main() {
    int n;
    scanf("%d", &n);

    int q;
    scanf("%d", &q);

