        scanf("%d", &time);

        strcpy(p.name, name);
        p.time = time;

        queue.enqueue(p);
    }

    while (true) {
        if (queue.data[queue.first].time > q) {
            t += q;
            queue.data[queue.first].time -= q;
            Process p = queue.dequeue();
            queue.enqueue(p);
        } else {
            t += queue.data[queue.first].time;
            queue.data[queue.first].time = 0;

