}process;

process q[MAX];
int head = 0;
int tail = 0;
bool is_full = false;
bool is_empty = false;

void enqueue(process p){
    is_empty = false;
    q[tail] = p;
    if(tail == MAX - 1){
        tail = 0;
    }else{
        tail += 1;
    }
    if(tail == head){
        is_full = true;
    }
}


process dequeue(){
    process p;
    if(head == MAX - 1){
        p = q[head];
        head = 0;
    }else{
        p = q[head];
        head += 1;
    }
    if(head == tail){
        is_empty = true;
    }
    return p;
}

