#include<iostream>
#include<vector>
#include<string>
using namespace std;
class queue{
  public:
    queue(const int n, const int q);
    void enqueue(const pair<int,string>& data);
    void dequeue();
    void operation ();
    int calculate (int time);

  private:
    vector< pair< int, string> > mData;
    int mOperationTime;
    int mHead;
    int mTail;
    int mBufferSize;
    int mDone;
    int mTimeFromStart;
};

queue::queue(const int n ,const int q){
  mHead = 0; mTail = 0;
  mData.reserve(n);
  mBufferSize = n;
  mDone = 0;
  mTimeFromStart = 0;
  mOperationTime = q;
}

void queue::enqueue(const pair<int,string>& data){
    mData.push_back(data);
    mTail++;
    if(mTail==mBufferSize) 
        mTail=0;
