#include <cassert>
#include <cstdio>

template <typename T>
class queue {
  unsigned int head_ = 0U; // C++11
  unsigned int size_ = 0U;
  T* const dp_;
  const unsigned int max_;
public:
  queue(T* dp, unsigned int max) : dp_(dp), max_(max) {}
  void enqueue(const T& d) {
    assert(!is_full());
    const unsigned int tail = mod_by_max(head_+size_);
    dp_[tail] = d;
    ++size_;
  }
  const T& dequeue() {
    assert(!is_empty());
    const T& d = dp_[head_];
    head_ = mod_by_max(head_+1);
    --size_;
    return d;
  }
  inline bool is_empty() const { return size_ == 0; }
  inline bool is_full() const { return size_ == max_; }
private:
  inline unsigned int mod_by_max(const unsigned int i) const {
    return i < max_ ? i : i-max_;
  }
};

struct process {
  char name_[10+1];
  unsigned int time_;
  inline unsigned int exec(const unsigned int quantum) {
    const unsigned int elapse = time_ > quantum ? quantum : time_;
    time_ -= elapse;
    return elapse;
  }
  inline bool is_finished() const { return time_ == 0; }
};

int main(void) {
  unsigned int n, q;
  std::scanf("%d %d", &n, &q);

  process processes[n];
  queue<process> process_queue(processes, n);
  for (auto i = 0U; i < n; ++i) {
    std::scanf("%10s %d", processes[i].name_, &processes[i].time_);
    process_queue.enqueue(processes[i]);
  }

  const unsigned int quantum = q;
  unsigned int elapse = 0U;
  while (!process_queue.is_empty()) {
    process current_process = process_queue.dequeue();
    elapse += current_process.exec(quantum);
    if (current_process.is_finished()) {
      printf("%s %d\n", current_process.name_, elapse);
    } else {
      process_queue.enqueue(current_process);
    }
  }

  return 0;
}
