template <class T>
class Queue{
private:
	unsigned size;
	T* queue;
	T* in;
	T* out;
	T* guard;
public:
	Queue(unsigned s){
		size=s;
		queue=new T[size+1];
		in=queue;
		out=queue;
		guard=queue+size;
	}
	void enqueue(T x){
		*in=x;
		in++;
		if(in==queue+size+1)
			in=queue;
	}	
	T dequeue(){
		T tmp=*out;
		out++;
		if(out==queue+size+1)
			out=queue;
		guard++;
		if(guard==queue+size+1)
			guard=queue;
		return tmp;
	}
	bool isFull(){
		if(in==guard){
			return true;
		}else{
			return false;
		}
	}
	bool isEmpty(){
		if(out==in){
			return true;
		}else{
			return false;
		}
	}
	~Queue(){
		delete[] queue;
	}
};

