#include <iostream>
#define QUEUE_LENGTH 60000
#define QUEUE_NAME 100
#define QUEUE_MAX 50001
using namespace std;

class queue{
	int front=0;
	int back=0;
	int q[QUEUE_LENGTH];
public:
	bool isEmpty(void);
	bool isFull(void);
	int enQueue(int x);
	int deQueue(int *x);
	void initialize(void);

};

void queue::initialize(void){
	front=0;
	back=0;
	}

bool queue::isEmpty(void){
	return front==back;
}

bool queue::isFull(void){
	return back==(front+1 % QUEUE_LENGTH);
}

int queue::enQueue(int x){
	if(isFull())
		return -1;	//error
	else{
		q[front]=x;
		if(front+1>QUEUE_LENGTH)
			front=0;
		else
			front+=1;
		return 0;
	}
}

int queue::deQueue(int *x){
	if(isEmpty())
		return -1;
	else{
		*x=q[back];
		if(back+1>QUEUE_LENGTH)
			back=0;
		else
			back+=1;
		return 0;
	}
}

