class Roundrobin{
private:
	int count, r;
	int num[100000];
	char rabel[100000][11];

public:
	Roundrobin(){
		count = 0;
		r = 0;
	}
	void setround(int ro){
		r = ro;
	}
	void add(char* name, int n){
		num[count] = n;
		strcpy(rabel[count], name);
		count++;
	}
	int pick(char* name){
		int ret = num[0];
		strcpy(name, rabel[0]);
		for (int i = 1; count > i; i++){
			num[i - 1] = num[i];
			strcpy(rabel[i - 1], rabel[i]);
		}
		count--;
		return ret;
	}
	void dow(){
		char name[3];
		int n, time = 0;
		while (count){
			n = pick(name);
			n = n-r;
			if (n > 0){
				add(name, n);
				time += r;
			}
			else{
				time += r + n;
				printf("%s %d\n", name, time);
			}
		}
	}
};

