class Queue
{
private:
  int head, tail;
  enum { MAX = 100000 };
  Data deq[MAX+1];

public:

  Queue() : head(0), tail(0) {}

  void push(Data p)
  {
    deq[tail++] = p;
    if(tail == MAX+1) tail = 0;
  }

  Data pop()
  {
    Data ret = deq[head++];
    if(head == MAX+1) head = 0;
    return ret;
  }

  bool empty()
  {
    return head == tail;
  }

};

