struct TProcess
{
	string Name;
	int    Time;
};

struct TFinished
{
	string Name;
	int    Time;
};

queue<TFinished> RoundRobin(queue<TProcess> X, int q)
{
	queue<TFinished> Y;
	int TotalTime = 0;
	while(!X.empty()){
		if(X.front().Time <= q){
			TotalTime += X.front().Time;
			TFinished Finished;
			Finished.Name = X.front().Name;
			Finished.Time = TotalTime;
			X.pop();
			Y.push(Finished);
		}else{
			TotalTime += q;
			X.front().Time -= q;
			X.push(X.front());
			X.pop();
		}
	}
	return Y;
}

