	queue<TProcess> Input;
	for(int i = 0; i < n; i++){
		TProcess Process;
		cin >> Process.Name >> Process.Time;
		Input.push(Process);
	}
	queue<TFinished> Output = RoundRobin(Input, q);
	while(!Output.empty()){
		cout << Output.front().Name << " " << Output.front().Time << endl;
		Output.pop();
	}
	return 0;
}

