template <typename T>
class myQueue
{
public:
    myQueue(int n)
    : data(new T[n + 1]), N(n + 1), head(0), tail(0)
    {}

    ~myQueue() { delete[] data; }

    void enqueue(const T& x)
    {
        data[tail % N] = x;
        tail = (tail + 1) % N;
    }

    T& dequeue()
    {
        T& temp = data[head];
        head = (head + 1) % N;
        return temp;
    }

    bool full()
    {
        return head == (tail + 1) % N;
    }

    bool empty()
    {
        return head == tail;
    }

private:
    T* data;
    int N;
    int head;
    int tail;
};

