#include <iostream>
#include <string>
using namespace std;

typedef struct {
    int head, tail, num, max;
    int *que;
    string *name;
} queue;

void initialize(queue *q, int max)
{
    q->head = q->tail = q->num = 0;
    q->que = new int[max];
    q->name = new string[max];
    q->max = max;
}

int isEmpty(queue *q)
{
    return q->head == q->tail;
}

int isFull(queue *q)
{
    return q->head == (q->tail + 1) % q->max;
}

int enqueue(queue *q, string n, int x)
{
    if (isFull(q))
        return -1;
    q->name[q->tail] = n;
    q->que[q->tail] = x;
    if (q->tail + 1 == q->max)
        q->tail = 0;
    else
        q->tail++;

    return 0;
}

int dequeue(queue *q, string *n, int *x)
{
    if (isEmpty(q))
        return -1;
    *n = q->name[q->head];
    *x = q->que[q->head];
    if (q->head + 1 == q->max)
        q->head = 0;
    else
        q->head++;

    return 0;
}

int main()
{
    int n, q, time, cnt = 0, total = 0;
    queue que, queO;
    string name;

    cin >> n >> q;
    initialize(&que, n + 1);
    initialize(&queO, n + 1);
    for (int i = 0; i < n; i++) {
        cin >> name >> time;
        if (enqueue(&que, name, time) == -1)
            return -1;
        cnt += time;
    }

    while (cnt > 0) {
        dequeue(&que, &name, &time);
        if (time >= q) {
            cnt -= q;
            total += q;
            time -= q;
            if (time)
                enqueue(&que, name, time);
            else
                enqueue(&queO, name, total);
        } else {
            cnt -= time;
            total += time;
            time = 0;
            enqueue(&queO, name, total);
        }
    }

    for (int i = 0; i < n; i++) {
        if (dequeue(&queO, &name, &time) == -1)
            return -1;
        cout << name << ' ' << time << endl;
    }
}

