template <typename T>
class queue{
public :
	const static int LEN = 10000;
	queue<T>(){
		head = tail = 0;
	}

	void empty(){
		head = tail = 0;
	}

	bool isEmpty(){
		return (head == tail);
	}

	bool isFull(){
		return ((tail + 1)%LEN == head);
	}

	T dequeue(){
		if(isEmpty()){
			throw exception();
		}
		if(head == LEN - 1){
			head = 0;
			return body[LEN -1];
		}
		return body[head++];
	}

	void enqueue(T el){
		if(isFull()){
			throw exception();
		}
		if(tail == LEN -1){
			tail = 0;
			body[LEN-1] = el;
		}else{
			body[tail++] = el;
		}
	}

	T top(){
		if(isEmpty()){
			throw exception();
		}
		return body[head];
	}

private:
	T body[LEN];
	int head,tail;
};

