  while (front != rear) {
    struct Process *p = queue[front];
    front++;

    front = front % QUEUE_SIZE;

    p->time -= q;

    if (p->time > 0) {
	time += q;

	queue[rear] = p;
	rear++;

	rear = rear % QUEUE_SIZE;
      } else {
	time += q + p->time;

	std::cout << p->name << " " << time << std::endl;;
      }
  }

  return 0;
}

