template <typename T>
struct queueElm
{
  std::string name;
  T value;

  queueElm<T> *nextPtr = nullptr;
};

template <typename T>
struct queue
{
  queueElm<T> *head =  nullptr;
  queueElm<T> *tail = nullptr;

  bool isEmpty()
  {

    if ((head == nullptr) && (tail == nullptr))
      return true;
    else
      return false;
  };

  void enqueue(std::string name, T value)
  {
    queueElm<T> *newPtr;
    if (!isEmpty())
      {
        newPtr = tail;
      }
    else
      {
        newPtr = new queueElm<T>;
        head = newPtr;
      }

    newPtr->name = name;
    newPtr->value = value;
    queueElm<T> *nextPtr = new queueElm<T>;
    newPtr->nextPtr = nextPtr;
    tail = nextPtr;
  };

  queueElm<T> dequeue()
  {
    auto tmpPtr = head;
    auto retVal = *tmpPtr;
    head = tmpPtr->nextPtr;
    delete tmpPtr;

    if (head == tail)
      {
        head = nullptr;
        tail = nullptr;
      }

    return retVal;
  };

  void print()
  {
    auto tmpPtr = head;
    while (tmpPtr != tail)
      {
        std::cout << tmpPtr->name << " " << tmpPtr->value << std::endl;
        tmpPtr = tmpPtr->nextPtr;
      }
  }

};

