	int num[2];
	string buff;
	stringstream ss(str);
	while (getline(ss, buff, ' ')) {
		stringstream ss_buf(buff);
		ss_buf >> num[cnt];
		cnt++;
	}
	struct wait_que *ary = new struct wait_que[num[0]];
	// get wait objs
	for (int i = 0; i < num[0]; i++) {
		getline(cin, str);

		struct wait_que obj;

		int split_num = str.find_first_of(' ');
		obj.name = str.substr(0, split_num);

		string time_str = str.substr(split_num + 1, str.size() - split_num);
		stringstream time_ss(time_str);
		time_ss >> obj.time;

                obj.cmp_flg = 0;

		*(ary + i) = obj;
	}

	vector<struct wait_que> ans = completeProcess(ary, num[0], num[1]);

	int n = ans.size();
	for (int i = 0; i < n; i++) {
		cout << ans[i].name << " " << ans[i].time << endl;
	}
}
vector<struct wait_que> completeProcess(struct wait_que *wqs, int size,  int q) {
	vector<struct wait_que> rtn_vec;
	int total_time = 0;
	int cnt = 0;
	int target_num = 0;
	while (cnt < size) {
		// check target element.
		struct wait_que *tmp = &wqs[target_num];
		target_num = (target_num + 1) % size;

		if ((*tmp).cmp_flg == 1) {
			continue;
		}

		if ((*tmp).time - q > 0) {
			(*tmp).time -= q;
			total_time += q;
		} else {
			total_time += (*tmp).time;
			(*tmp).time = total_time;
			(*tmp).cmp_flg = 1;
			rtn_vec.push_back(*tmp);
			cnt++;
		}
	}
	return rtn_vec;
}

