#define FOR(i, start, end) for(int i = (start); i < (end); ++i)
#define REP(i, n) FOR(i, 0, n)

struct Proc {
    string name;
    int remain;
    Proc(const string& n, int r) : name(n), remain(r) {}
};

void read_problem(queue<Proc>& que, int& quant)
{
    int n;
    scanf("%d %d\n", &n, &quant);

    REP(_, n) {
        char name[64];
        int remain;
        scanf("%s %d\n", name, &remain);
        que.push(Proc(name, remain));
    }
}

void schedule(queue<Proc>& que, int quant)
{
    int t = 0;

    while(!que.empty()) {
        Proc proc = que.front();
        que.pop();
        if(proc.remain > quant) {
            t += quant;
            proc.remain -= quant;
            que.push(proc);
        }
        else{
            t += proc.remain;
            printf("%s %d\n", proc.name.c_str(), t);
        }
    }
}

int main()
{
    queue<Proc> que;
    int quant;

    read_problem(que, quant);

    schedule(que, quant);

    return 0;
}

