Proc Q[100001];

class Queue{
private:
  int fp;
  int rp;
public:
  Queue(){fp=0;rp=0;}
  int next(int p) const {return (p+1)%100001;}
  bool isFull() const {return (next(rp)==fp);}
  bool isEmpty() const {return(rp==fp);}
  void push(Proc d){
    if(isFull())
      return;
    Q[rp] = d;
    rp = next(rp);
  }
  Proc front(){
    if(isEmpty()){
      Proc er;
      er.tim = -1;
      return er;
    }

    return Q[fp];
  }
  void pop(){
    if(isEmpty())
      return;
    fp = next(fp);
  }
};

