// Queue(Round Robin)
class MyQueue {
	private:
		queue<Process> q;
		int quantom;
		int elapsed;

	public:
		MyQueue() {
			elapsed = 0;
		}
		void setQuantom(int q);
		void addProcess(Process p);
		bool isDone();
		void simulate();
};

void MyQueue::setQuantom(int q) {
	quantom = q;
}

void MyQueue::addProcess(Process p) {
	q.push(p);
}

bool MyQueue::isDone() {
	return q.size() <= 0;
}

void MyQueue::simulate() {
	Process proc = q.front(); q.pop();

	elapsed += min(quantom, proc.cost);
	proc.cost -= min(quantom, proc.cost);
	if(proc.cost <= 0) {
		cout << proc.name << " " << elapsed << endl;
	} else {
		q.push(proc);
	}
}

