        cin >> n >> time;

        string s;
        int t, totalTime=0, curTime=0;
        queue q;
        struct proc p;

        q.init();
        while( cin >> s >> t ){
                totalTime += t;
                p.name = s;
                p.time = t;
                if( t <= time ){
                        curTime += t;
                        cout << p.name << " " << curTime << endl;
                }else{
                        p.time -= time;
                        curTime += time;
                        q.enque(p);
