using namespace std ;

template<class T> class myQueue{
  vector<T> v;
  public:
  myQueue(){};
  void push(T n_){
    v.push_back(n_) ;
  }
  void pop(){
    v.erase(v.begin()) ;
  }
  bool empty(){
    return v.empty() ;
  }
  T front(){
    return v[0] ;
  }
  T back(){
    return v[v.size()-1] ;
  }
  size_t size(){
    return v.size() ;
  }
};

int main(){
  myQueue<pair<string,int>> mq;
  vector<pair<string,int>> vsi ;
  int n,q,n2,time = 0 ;
  string s;
  pair<string,int> psi;
  cin >> n >> q ;
  for(int i = 0; i < n; ++i){
    cin >> s >> n2 ;
    mq.push(make_pair(s,n2)) ;
  }
  while(!mq.empty()){
    psi = mq.front() ;
    n2 = psi.se - q ;
    if(n2 <= 0){
      time += psi.se ;
      vsi.push_back(make_pair(psi.fi,time)) ;
    }
    else{
      time += q ;
      psi.se = n2 ;
      mq.push(psi) ;
    }
    mq.pop() ;
  }
  for(auto n3: vsi){
    cout << n3.fi << " " << n3.se << endl;
  }

  return 0 ;
}

