		scanf("%s", Q[i].name);
		scanf("%d", &Q[i].t);
	}
	head = 1;
        tail = n + 1;

	// シミュレーション
	while (head != tail) {
		u = dequeue(); // 先頭プロセスを処理するためにデキューする
		c = min(q, u.t); // クォンタムか残り処理時間のどちらか小さい方をcに入れる
		u.t -= c; // 処理時間を引いて残り処理時間とする
		elaps += c; // 経過時間を加算
		if (u.t > 0) {
			enqueue(u); // 処理時間がまだ残っていればキュー末尾に追加する
		}
		else {
			printf("%s %d\n", u.name, elaps);
		}
	}

	return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define LEN 100005

typedef struct pp{
  string name;
  int t;
}P;

//P Q[LEN+1];
vector<P> Q(LEN+1);
int head, tail, n;

bool is_full() {
    return (head == (tail+1) % LEN ? true : false);
}
void enqueue(P x){
    assert(!is_full());

    Q.at(tail) = x;
    tail = (tail + 1) % LEN;
}

bool is_empty(void) {
    return head == tail;
}

P dequeue(){
    assert(!::is_empty());
    P p = Q.at(head);
    head = (head + 1) % LEN;

    return p;
}

void initialize(void) {
    head = 0;
    tail = 0;
}

int main(){
  int elaps = 0, c;
  int n, q;
  P u;
  scanf("%d %d", &n, &q);

  initialize();

  for (int i = 0; i < n; i++){
    cin >> Q[i].name;
    cin >> Q[i].t;
    P p;
    p.name = Q[i].name;
    p.t = Q[i].t;
    enqueue(p);
//    scanf("%s", Q[0].name);
//    scanf("%d", &Q[0].t);
  }


  vector<P> ans_s;
  int time = 0;

  while (::is_empty() != true) {
      P p = dequeue();

      if (p.t <= q) {
          time += p.t;
          p.t = time;
          ans_s.push_back(p);
      }
      else {
        p.t -= q;
        time += q;
        enqueue(p);
      }
  }

  for (auto ans : ans_s) {
      cout << ans.name << " " << ans.t << endl;
  }
  return 0;
}

