			f = 0;
			b = 0;
		}
		bool empty() {
			return f == b;
		}
		void push(pair<string,int> e) {
			if(f + 1 == b) throw "Error: full";
			a[f] = e;
			f++;
			if(f == size) f = 0;
		}
		pair<string,int> front() {
			return a[b];
		}
		void pop() {
			if(!empty()) {
				b++;
				if(b == size) f = 0;
			}
			else throw "Error: empty";
		}
};

