struct Process{
  char name[100];
  int time;
};

int top = 0; // 最後尾
int bottom = 0; // 先頭-1
const int SIZE = 1000000;
Process Q[SIZE];

Process pop() {
  if (bottom < SIZE-1) bottom++;
  else bottom = 0;
  return Q[bottom];
}

void push(Process pro) {
  if (top < SIZE-1) top++;
  else top = 0;
  Q[top] = pro;
}

bool isEmpty(){
  if (top == bottom) return true;
  else return false;
}

int main() {
  // 読み込み
  int n, q;
  scanf("%d %d", &n, &q);
  for (int i=0; i<n; i++) {
    Process pro;
    scanf("%s", pro.name);
    scanf("%d", &pro.time);
    push(pro);
  }
  // 処理
  int count = 0;
  while (! isEmpty()) {
    Process pro = pop();
    if (pro.time>q) {
      count += q;
      pro.time -= q;
      push(pro);
    }
    else {
      count += pro.time;
      printf("%s %d\n", pro.name, count);
    }
  }
}

