template <typename M>
struct Queue {
  vector<M> members;
  int count = 0;

  void push(M m) {
    members.push_back(m);
    count++;
  }

  M pop() {
    M m = members[0];
    rotate(members.begin(), members.begin() + 1, members.end());
    members.pop_back();
    count--;
    return m;
  }

  int size() {
    return count;
  }

  bool empty() {
    return count == 0;
  }
};

int main() {
  int n, q;
  scanf("%d %d", &n, &q);

  Queue<Process> processes;

  for (int i = 0; i < n; i++) {
    Process p;
    scanf("%s %d", &p.name, &p.time);
    processes.push(p);
  }

  int time_consumed = 0;
  while (!processes.empty()) {
    Process p = processes.pop();
    if (p.time <= q) {
      time_consumed += p.time;
      printf("%s %d\n", p.name, time_consumed);
    } else {
      p.time -= q;
      time_consumed += q;
      processes.push(p);
    }
  }

  return 0;
}

