#include <iostream>
#include <string>
#include <queue>

struct process {
  std::string name;
  int time;
};

class Scheduler {
public:
  explicit Scheduler(std::queue<struct process>& process_queue, int quantum)
      : quantum{quantum}, process_queue{process_queue} {};

  void run();

private:
  const int quantum;
  int time_running;
  std::queue<struct process>& process_queue;
  std::vector<struct process> finished;

  void run_process();
};

void Scheduler::run_process() {
  auto proc = process_queue.front();
  process_queue.pop();
  if (proc.time > quantum) {
    time_running += quantum;
    proc.time -= quantum;
    process_queue.push(proc);
  } else {
    time_running += proc.time;
    proc.time = time_running;
    finished.push_back(proc);
  }
}

void Scheduler::run() {
  time_running = 0;

  while (!process_queue.empty()) {
    run_process();
  }
  for (auto& proc: finished) {
    std::cout << proc.name << ' ' << proc.time << '\n';
  }
}

int main() {
  std::queue<struct process> process_queue;
  int nproc, quantum;
  std::cin >> nproc >> quantum;
  for (auto i = 0; i < nproc; i++) {
    struct process proc;
    std::cin >> proc.name >> proc.time;
    process_queue.push(proc);
  }

  Scheduler sched{process_queue, quantum};
  sched.run();
  return 0;
}

