		Proc front();
		void pop();
};

void Queue::push(Proc d){
	if(isFull()){
		return;
	}
	Q[rp]=d;
	rp=next(rp);
}

Proc Queue::front(){
	if(isEmpty()){
		Proc er;
		er.tim=-1;
		return er;
	}
	return Q[fp];
}

void Queue::pop(){
	if(isEmpty()){
		return;
	}
	fp=next(fp);
}


