class Queue {
public:
    Queue(int n) : len_(n) {
        queue_ = new P[len_];
        head_ = 0;
        tail_ = 0;
    };

    ~Queue() {
        delete queue_;
    };

    bool isEmpty() {
        return tail_ <= head_;
    }

    void enqueue(P p) {
        queue_[tail_ % len_] = p;
        tail_++;
    }

    P dequeue() {
        P p = queue_[head_ % len_];
        head_++;
