class Queue {
private:
    vector<T> vec;
    uint32_t head;
    uint32_t tail;

public:
    Queue(uint32_t n) {
        vec.resize(n + 1);
        head = 0;
        tail = 0;
    }

    void increment(uint32_t &x) {
        x++;
        x %= vec.size();
        return;
    }

    void enqueue(T x) {
        vec[tail] = x;
        increment(tail);
    }

    T dequeue() {
        T x = vec[head];
        increment(head);
        return x;
    }

    bool empty() {
        return head == tail;
    }
};

