};

void RoundRobin(vector<process> &X, int q)
{
	vector<process> Y;
	int totaltime = 0;
	while(!X.empty()){
		int i = 0;
		while(i < X.size()){
			if(X[i].time <= q){
				totaltime += X[i].time;
				process finished;
				finished.name = X[i].name;
				finished.time = totaltime;
				Y.push_back(finished);
				X.erase(X.begin() + i);
			}else{
				totaltime += q;
				X[i].time -= q;
				i++;
			}
		}
	}
	X = Y;
}

