const long LEN=510029;

class queue {
	process data[LEN];
	int head, tail;
public:
	queue(): head(0), tail(0) {}  

	void enqueue(const process&);
	process& dequeue();

	bool isEmpty(){ return head == tail;  }
	bool isFull(){  return (tail+1) % LEN == head;  }
};
void queue::enqueue(const process& p)
{
	if( isFull() ){
		cout<<"full!"<<endl;
		exit(1);
	}
	data[tail+1]=p;
	tail= (tail+1) % LEN;
}
process& queue::dequeue()
{
	if( isEmpty() ){
		cout<<"empty!"<<endl;
		exit(1);
	}
	head= (head+1) % LEN;
	return data[head];
}

