#include <bits/stdc++.h>

typedef std::pair<std::string, int> Process;

typedef struct Node {
  Node *left, *right;
  Process data;
} Node;

Node* base;

void Node_init() {
  base = new Node();
  base->left  = base;
  base->right = base;
  return;
}

void Node_push(Process x) {
  Node *node = new Node();
  node->data = x;
  node->right = base;
  node->left  = base->left;
  node->right->left = node;
  node->left->right = node;
  return;
}

Process Node_front(void) {
  if( base->right != nullptr ) {
    return base->right->data;
  }
  return Process(0, 0);
}

void Node_pop(void) {
  Node *node = base->right;
  node->right->left = node->left;
  node->left->right = node->right;
  delete node;
  return;
}

bool Node_empty() {
  return (base == base->right);
}

int main() {  
  int N;
  int ltime;
  std::string name;
  int time;
  int ttime = 0;

  Node_init();

  std::cin >> N >> ltime;
  for(int i = 0; i < N; ++i) {
    std::cin >> name >> time;
    Node_push(Process(name, time));
  }

  while( not Node_empty() ) {
    Process pp;
    pp = Node_front(); Node_pop();
    pp.second -= ltime;
    if( pp.second > 0 ) {
      Node_push(pp);
      ttime += ltime;
      continue;
    }
    else {
      ttime += ltime + pp.second;
      std::cout << pp.first << " " << ttime << std::endl;
    }
  }

  return 0;
}

