template<class T>
class cQueue
{
private:
    int64_t max;
    int64_t nQueue;
    int64_t pHead;
    T *pBuff;

public:
    cQueue()
    {
        nQueue = 0;
        max = 1;
        pBuff = new T[1];
        pHead = 0;
    }
    void push(T v)
    {
        if (max <= nQueue)
        {
            int64_t tmax = max * 2 + 1;
            T *tpBuff = new T[tmax];
            int64_t i = 0;
            for (int64_t i = 0; i < nQueue; ++i)
            {
                int64_t io = (pHead + i) % max;
                tpBuff[i] = pBuff[io];
            }
            max = tmax;
            delete[] pBuff;
            pBuff = tpBuff;
            pHead = 0;
        }
        pBuff[(pHead + nQueue) % max] = v;
        ++nQueue;
    }
    T front()
    {
        return pBuff[pHead];
    }
    void pop()
    {
        pHead = (pHead + 1) % max;
        --nQueue;
    }
    void show()
    {
        cCom << "[";
        for (int64_t i = 0; i < nQueue; ++i)
        {
            int64_t iq = (pHead + i) % max;
        }
        cCom << "], " << pHead << " " << nQueue << " " << max << "\n";
    }
    bool empty()
    {
        return 0 == nQueue;
    }
};
