    int exited = 0;
    int min = INT_MAX;

    scanf("%d%d", &n, &q);
    for(int i=0; i<n; i++){
        scanf("%s%d", name[i], &time[i]);
        if(time[i] < min)
            min = time[i];
    }

    if(min/q){
        int t = min/q;
        clock += t * q * n;
        for(int i=0; i<n; i++){
            time[i] -= t * q;
            if(time[i] == 0)
                exited++;
        }
    }

    for(int i=0; exited < n; i=(i+1)%n){
        if(time[i] == 0)
            continue;
        if(time[i] <= q){
            clock += time[i];
            time[i] = 0;
            exited++;
            printf("%s %d\n", name[i], clock);
        }else{
            clock += q;
            time[i] -= q;
        }
    }
}

