class ProcessQueue{
public:
    ProcessQueue(int size):
        m_size(size),
        m_head(0),
        m_tail(0),
        number(0)
    {
        m_process = new Process[m_size];
    };

    ~ProcessQueue(){
        delete[] m_process;
    };

    void enQueue(Process process){
        m_process[m_tail] = process;
        number++;
        m_tail = (++m_tail)%m_size;
    };

    Process deQueue(){
        number--;
        if(m_head < m_size-1){
            m_head++;
            return m_process[m_head-1];
        }else{
            m_head = 0;
            return m_process[m_size-1];
        }
    };

    int getNumber(){
        return number;
    }

private:
    int m_head;
    int m_tail;
    int m_size;
    int number;
    Process* m_process;

};

