    bool IsEmpty()
    {
        return head == tail;
    }

    bool IsFull()
    {
        return head == (tail + 1) % 100000;
    }
};

int main()
{
    Queue queue;
    int processNum, roundTime;
    cin >> processNum >> roundTime;
    for (int i = 0; i < processNum; i++)
    {
        Process process;
        cin >> process.name >> process.time;
        queue.Enqueue(process);
    }

    int elapsedTime = 0;

    while (!queue.IsEmpty())
    {
        Process target = queue.Dequeue();

        if (target.time <= roundTime)
        {
            elapsedTime += target.time;
            cout << target.name << " " << elapsedTime << endl;
        }
        else
        {
            elapsedTime += roundTime;
            target.time -= roundTime;
            queue.Enqueue(target);
        }
    }
    return 0;
}

