struct process{
    int time;
    string name;
};

class my_queue{
private:
    int head, tail;
    process queue[MAX];


public:
    my_queue()
    {
        head = 0;
        tail = 0;
    }

    bool isEmpty()
    {
        return head == tail;
    }

    bool isFull()
    {
        return head == (tail + 1) % MAX;
    }

    void enqueue(process n)
    {
        if(isFull())
        {
            cout << "Queue is full." << endl;
            return;
        }
        queue[tail++] = n;

        if(tail == MAX) tail = 0;

        return;
    }

    process dequeue()
    {
        if(isEmpty())
        {
            cout << "Queue is empty." << endl;
            exit(-1);
        }

        process ret = queue[head];

        if(head+1 == MAX) head = 0;
        else head++;

        return ret;
    }
};

