void queue::init()
{
        tail = 0;
        head = 0;
}

void queue::enque(struct proc p)
{
        // tailがheadの直前にあるか、tailが最後でかつheadが先頭の時
        if( (tail+1==head) || ((tail==MAX_NUM_PROCESS-1)&&(head==0)) ){
                cout << "Error:Queue is full.\n";
                exit(1);
        }
        que[tail] = p;
        tail++;
}    

struct proc queue::deque()
{
        if( tail == head ){
                cout << "Error:Queue is empty.\n";
                exit(1);
        }
        return que[head++];
}



