using namespace std;
template <typename T>
class Queue {
	T* q;
	T* guard;
	T* head;
	T* tail;
public:
	Queue() {
		q = new T[100001];
		guard = q + 100000;
		head = q;
		tail = q;
	}
	~Queue() {
		delete[] q;
	}
	bool isFull() {
		if (tail == guard) {
			return head == q;
		} else {
			return (tail + 1) == head;
		}
	}

	bool isEmpty() {
		return head == tail;
	}

	void push(T x) {
		if (!isFull()) {
			if (tail == guard) {
				if (head != q) {
					tail = q;
					*tail = x;
				}
			} else {
				*tail = x;
				tail++;
			}
		}
	}

	T pop() {
		T retValue;
		if (!isEmpty()) {
			retValue = *head;
			head++;
			if (head == guard) {
				head = q;
			}
		}
		return retValue;
	}
};

