		queue.push(p);
	}

	Queue<Process> finished;
	int time = 0;
	while (!queue.isEmpty()) {
		Process p = queue.pop();
		if (p.quantum >= q) {
			p.quantum -= q;
			time += q;
		} else {
			time += p.quantum;
			p.quantum = 0;
		}
		if (p.quantum <= 0) {
			p.quantum = time;
			finished.push(p);
		} else {
			queue.push(p);
		}
	}

	while (!finished.isEmpty()) {
		Process p = finished.pop();
		cout << p.name << ' ' << p.quantum << endl;
	}
	return 0;
}

