Process queue[100000];
int qsize = 0;

static void rotate() {
    Process head = queue[0];
    for (int i = 1; i < qsize; ++i) {
        queue[i - 1] = queue[i];
    }
    queue[qsize - 1] = head;
}

int main(void) {

    int n, q;
    cin >> n >> q;

    for (int i = 0; i < n; ++i) {
        cin >> queue[i].name >> queue[i].time;
    }
    qsize = n;

    int elapsed = 0;
    while (qsize != 0) {
        Process head = queue[0];
        --qsize;
        rotate();
        if (head.time - q <= 0) {
            elapsed += head.time;
            printf("%s %d\n", head.name, elapsed);
        }
        else {
            elapsed += q;
            head.time -= q;
            queue[qsize++] = head;
        }
    }

    return 0;
}

