	for (i = 0; i < n; i++)
	{
		cin >> str >> time;
		now.input(str, time);
		queue.enqueue(now);
	}
	while (!queue.empty())
	{
		now = queue.dequeue();
		if (now.time <= q)
		{
			alltime += now.time;
			now.print();
		}
		else
		{
			alltime += q;
			queue.enqueue(now);
			queue.rein(q);
		}
	}
    return 0;
}

