int main()
{
	int n, q, nowtime, j = 0;
	process p[100000], result[100000], temp;
	queue que;

	que.initialize();

	cin >> n >> q;

	for(int i = 0; i < n; i++)
	{
		cin >> p[i].name >> p[i].time;
		que.enqueue(p[i]);
	}

	while(que.top != 0)
	{
		temp = que.dequeue();

		if (temp.time - q <= 0)
		{
