template<typename T>
class Queue{
 public: 
    Queue(const int capacity){
        data_.resize(capacity);
        head_ = tail_ = 0;
        end_ = capacity;
    }

    void Enqueue(const T &d){
        data_.at(tail_) = d;
        tail_ = (tail_ + 1 >= end_) ? 0 : tail_ + 1;
    }
    T Dequeue(){
        T ret = data_.at(head_);
        head_ = (head_ + 1 >= end_) ? 0 : head_ + 1;
        return ret;
    }
    inline bool IsEmpty(){
        return head_ == tail_;
    }
 protected: 
    std::vector<T> data_;
    int head_, tail_;
    int end_;
};

int main(){
