#include <stdio.h>
#include <stdlib.h>

static const int NMAX = 100000;

typedef struct process 
{
    char name[11];
    int time;
} Process;

typedef struct queue {
    int n = NMAX;
    Process buf[NMAX];
    Process *buf_end = buf + n - 1;
    Process *start = buf;
    Process *end = buf;
    int size = 0;

    void init(void) {
        size = 0;
        start = buf;
        end = buf;
    }
    bool isEmpty() {
        return size == 0;
    }
    bool isFull() {
        return size == n-1;
    }
    void put(Process *a) {
        if (isFull()) {
            printf("Error!! queue is full!!\n");
        }
        *(end++) = *a;
        size++;
        if (end > buf_end) end = buf;
    }
    Process* get() {
        if (isEmpty()) {
            printf("Error!! queue is empty!!\n");
        }
        size--;
        return start++;
    }
} Queue;

int run (Queue *queue, const int q) {
    int time = 0;
    int rest_time;

    while (queue->size > 0) {
        Process *p = queue->get();
        if (p->time > q) {
            p->time -= q;
            queue->put(p);
            time += q;
        }
        else {
            time += p->time;
            printf("%s %d\n", p->name, time);
        }
    }
}


