class Proc{
public:
  string nam;
  int tim;
  Proc(){
    nam="";
    tim=0;
  }
};

Proc Q[100001];

class Queue{
private:
  int fp;
  int rp;
public:
  Queue(){
    fp=0;
    rp=0;
  }
  int next(int p){
    return (p+1)%100001;
  }
  bool isFull(){
    return (next(rp)==fp);
  }
  bool isEmpty(){
    return rp==fp;
  }
  void push(Proc d){
    if(isFull())return;
    Q[rp]=d;
    rp=next(rp);
  }
  Proc front(){
    if(isEmpty()){
      Proc er;
      er.tim=-1;
      return er;
    }
    return Q[fp];
  }
  void pop(){
    if(isEmpty())return;
    fp=next(fp);
  }
};

int main(){
  Queue que;

  int n,q;
  cin >> n >> q;

  for(int i=0; i<n; i++){
    Proc p;
    cin >> p.nam >> p.tim;
    que.push(p);
  }

  int total_tim = 0;

  while(!que.isEmpty()){
    Proc p = que.front();
    que.pop();
    if(p.tim<=q){
      total_tim += p.tim;
      cout << p.nam << ' ' << total_tim << endl;
    }else{
      total_tim += q;
      p.tim -= q;
      que.push(p);
    }
  }

  return 0;
}

