int head, tail, n;

void enqueue(P x){
  Q[tail] = x;
  if ( tail == LEN ) tail = 1;
  else tail++;
}

P dequeue(){
  P x = Q[head];
  if ( head == LEN ) head = 1;
  else head++;
  return x;
}
