template <typename T>
struct Queue {
    T array[200001];

    int tail = 0;
    int head = 0;

    void enqueue(T t) {
        array[tail++] = t;
    }

    T dequeue() {
        return array[head++];
    }

    bool isEmpty() {
        return tail == head;
    }
};

struct Task {
    char name[10];
    int time = 0;
};

int main(int argc, const char * argv[]) {
    int n = 0;
    int q = 0;
    cin >> n >> q;

    Queue <Task> queue;
    int useTime = 0;

    while (n--) {
        Task task;
        cin >> task.name >> task.time;
        queue.enqueue(task);
    }

    while (!queue.isEmpty()) {
        Task task = queue.dequeue();
        int min = q > task.time ? task.time : q;
        useTime += min;
        task.time -= min;
        if (task.time > 0) {
            queue.enqueue(task);
        } else {
            cout << task.name << " " << useTime << "\n";
        }
    }

    return 0;
}

