	int num[100005];

public:
	Q() {
		fast = 0;	//???????????´???
		last = 0;	//???????°??????´???

	}

	void enqueue(int n) {

		if (last >= 100000) {

			last -= fast;
			for (int i = 0; i < last; i++) {
				num[i] = num[fast+1];
			}
			fast = 0;
		}

		num[last] = n;

		last++;
	}

	int dequeue() {
		fast++;
		return num[fast - 1];
	}

	int getlengh() {
		return last - fast;
	}

};


