int main() {
  int n, q, t;
  string name;
  // 標準ライブラリから queue を使用
  queue<pair<string, int> > Q;  // プロセスのキュー

  cin >> n >> q;

  // 全てのプロセスをキューに順番に追加する
  for ( int i = 0; i < n; i++ ) {
    cin >> name >> t;
    Q.push(make_pair(name, t));
  }

  pair<string, int> u;    // ここで、pairは値の組を保持するための構造体テンプレートで、
  int elaps = 0, a;       // < >の中に2つの型を指定して宣言します。make_pairによって
                          // 組を生成し、1つ目の要素はfirst、2つ目の要素はsecondで
  // シミュレーション        // アクセスすることができます
  while ( !Q.empty() ) {
    u = Q.front(); Q.pop();
    a = min(u.second, q);  // q または必要な時間 u.second だけ処理を行う
    u.second -= a;  // 残りの必要時間を計算
    elaps += a;  // 経過時間を加算
    if ( u.second > 0 )
      Q.push(u);  // 処理が完了していなければキューに追加
    else
      cout << u.first << " " << elaps << endl;
  }

  return 0;
}

