using namespace std;

class element{
private:
    string name;
    bool end;
    int time;
public:
    element(){}
    element(string n, int t) {
        name = n;
        time = t;
        end  = false;
    }
    int processing(int q) {
        if (time > q) {
            time -= q;
            return q;
        }
        int ret = time;
        time = 0;
        end = true;
        return ret;
    }
    string get_name() {
        return name;
    }
    int get_time() {
        return time;
    }
    bool get_end() {
        return end;
    }
};

class table{
private:
    element* e;
    int n;
    int process_time;
    int head;
    int top; //??????????????????????????¨
    int total_time;
    void processing() {
        total_time += e[head].processing(process_time);
        if (e[head].get_end() == true) {
            cout << e[head].get_name() << " " << total_time << endl;
        }
    }
    bool next_head() {
        for (int i = 0; i < n; i++) {
            if (head < n - 1) {
                head++;
            } else {
                head = 0;
            }
            if (e[head].get_end() == false) {
                return true;
            }
        }
        return false;
    }
public:
    table(int n_in, int p_in) {
        n = n_in;
        e = new element[n];
        process_time = p_in;
        head = -1;
        top = -1;
        total_time = 0;
    }
    void push(element e_in) {
        top++;
        e[top] = e_in;
    }
    void all_processing() {
        while(next_head()) {
            processing();
        }
    }
};


