  int tim;
};

Q Que[len];
int n;
int head;
int tail;

int initialize(){
  head=tail=0;
}
void enqueue(Q x){
  Que[tail]=x;
  tail=(tail+1)%len;
}
int isEmpty(){
  if(head==tail){
    return 1;
  }
}

Q dequeue(){
  if(isEmpty()==1)fprintf(stderr,"UnderFlow\n");
  Q y=Que[head];
  head=(head+1)%len;
  return y;
}

int isFull(){
  if(head==(tail+1)%len){
    return 1;
  }
}

int main(){
  int c=0,d=0;
  int del=0;
  Q ll;
  if(isFull()!=1)fprintf(stderr,"OverFlow\n");
  cin>>n>>del;
  head=1;
  tail=n+1;
  for(int i=1;i<=n;i++){
    cin>>Que[i].name;
    cin>>Que[i].tim;
  }
  while(1){
    if(isEmpty()==1)break;
    ll=dequeue();
    if(del<ll.tim)c=del;
    else c=ll.tim;
    ll.tim=ll.tim-c;
    d=d+c;
    if(ll.tim>0)enqueue(ll);
    else cout<<ll.name<<" "<<d<<endl;
