        process_que.push_back(p);
    }

    int current_time = 0;

    while( !process_que.empty() ){
        // プロセスの時間が quantum で処理しきれたら，finished_processにpushする
        if ( (process_que.front().time - quantum) <= 0){
            current_time += process_que.front().time;
            finished_process.push_back( process{process_que.front().name, current_time} );
            process_que.pop_front();

        // プロセスの時間が quantum で処理しきれなかったら，process_queの後ろに後ろにpushし，先頭からpopする．
        }else if ((process_que.front().time - quantum) > 0){
            current_time += quantum;
            process_que.front().time = process_que.front().time - quantum;
            process_que.push_back( process_que.front() );
            process_que.pop_front();
        }
    }

    while( !finished_process.empty() ){
        cout << finished_process.front().name << " " << finished_process.front().time << "\n";
        finished_process.pop_front();
    }
    return 0;
}

