struct Process {
    string name;
    int time;
};

void print(const vector<Process> &vec) {
    for (const auto &v : vec) cout << v.name << " " << v.time << endl;
}

vector<Process> simulate(queue<Process> &queue, int q) {
    vector<Process> result;
    int time = 0;

    while (!queue.empty()) {
        Process proc = queue.front();
        queue.pop();
        if (proc.time > q) {
            proc.time -= q;
            queue.push(proc);
            time += q;
        } else {
            int tmpTime = proc.time;
            proc.time += time;
            result.push_back(proc);
            time += tmpTime;
        }
    }

    return result;
}

int main() {
    int n, q;
    cin >> n >> q;

    queue<Process> queue;

    for (int i = 0; i < n; i++) {
        string name;
        int time;
        cin >> name >> time;
        queue.push({name, time});
    }

    vector<Process> result = simulate(queue, q);
    print(result);
}

