template<typename T>
class Queue{
private:
    std::unique_ptr<T[]> arr_;
    size_t length_;
    size_t front_ptr_;
    size_t back_ptr_;
    size_t next_(size_t ptr) const {
        return (ptr + 1) % length_; 
    }
public:
    Queue(size_t length=100){
        length_ = length + 1; // +1 is buffer
        arr_.reset(new T[length_]);
        front_ptr_ = 0;
        back_ptr_ = 0;
    }
    ~Queue(){
        arr_.reset();
    }

    bool empty() const {
        return front_ptr_ == back_ptr_;
    }

    size_t length() const {
        return length_;
    } 

    void push(T element){
        assert(next_(back_ptr_) != front_ptr_);

        arr_[back_ptr_] = element;
        back_ptr_ = next_(back_ptr_);
    }

    void pop(){
        assert(!empty());

        front_ptr_ = next_(front_ptr_);
    }

    T front() const {
        assert(!empty());

        return arr_[front_ptr_];
    }
};

struct Process{
    std::string name;
    size_t neededTime;

    Process(std::string name = "p", size_t neededTime = 0){
        this->name = name;
        this->neededTime = neededTime;
    }
};

int main(){
    size_t N, timeSlice;
    std::cin >> N >> timeSlice;
    Queue<Process> processes(N);
    Queue<Process> finished(N);

    std::string name;
    size_t neededTime;
    for(int i=0;i<N;i++){
        std::cin >> name >> neededTime;
        Process process(name,neededTime);
        processes.push(process);
    }

    size_t cumTime = 0;
    while(!processes.empty()){
        Process process = processes.front();
        processes.pop();

        size_t processTime = std::min(timeSlice, process.neededTime);
        cumTime += processTime;
        process.neededTime -= processTime;

        if(process.neededTime <= 0){
            process.neededTime = cumTime;
            finished.push(process);
        }
        else {
            processes.push(process);
        }
    }

    for(int i=0;i<N;i++){
        Process process = finished.front();
        finished.pop();
        std::cout << process.name << " " << process.neededTime << '\n';
    }
}

