void initializa() { head = tail = 0; }

bool isEmpty() { return head == tail; }

bool isFull() { return head == (tail + 1) % MAX; }

void enqueue(Process p) {
  if (isFull()) {
    fprintf(stderr, "error: full\n");
    exit(1);
  }
  q[tail] = p;
  if (tail + 1 == MAX) tail = 0;
  else tail++;
}

