    for (int i = 0; i < n; i++) {
        string name = "";
        int unit = 0;
        cin >> name;
        cin >> unit;
        enqueue(que, name, unit);
    }

    cout << "hoge " << "hogehoge";

    int time = 0;
    while (!empty_que(que)) {
        node_t* task = dequeue(que);
        if (task->data <= q) {
            time += task->data;
            cout << task->name << " " << time << endl;
            continue;
        }
        int remain = task->data - q;
        time += q;
        enqueue(que, task->name, remain);
        free(task);
    }
    return 0;
}

