#include <cstdio>
#include <iostream>
using namespace std;

static const int MAX_TASKNUM = 100000;

typedef struct tagSTask {
    char name[10];
    int  time;
} STask;


class CRingBuf
{
public :
    CRingBuf(void) : m_iFront(0), m_iRear(0) {};
    bool  Enqueue(STask* pTask);
    STask Dequeue(void);
    int   BufNum(void) {
        int ret;
        if (m_iFront <= m_iRear) {
            ret = m_iRear - m_iFront;
        }
        else {
            ret = (m_iRear + MAX_TASKNUM) - m_iFront;
        }
        return ret;
    };

private :
    int   m_iFront;
    int   m_iRear;
    STask m_sTask[MAX_TASKNUM];
    bool  IsFull(void) {
        return (m_iFront == ((m_iRear + 1) % MAX_TASKNUM)) ? true : false;
    };
    bool  IsEmpty(void) {
        return (m_iFront == m_iRear) ? true : false;
    };
};

bool CRingBuf::Enqueue(STask* pTask)
{
    bool ret;

    if (IsFull() == false) {
        ret = true;
        m_sTask[m_iRear] = *pTask;
        ++m_iRear;
        if (m_iRear >= MAX_TASKNUM) {
            m_iRear = 0;
        }
    }
    else {
        ret = false;
    }

    return ret;
}

STask CRingBuf::Dequeue(void)
{
    STask task;

    if (IsEmpty() == false) {
        task = m_sTask[m_iFront];
        ++m_iFront;
        if (m_iFront >= MAX_TASKNUM) {
            m_iFront = 0;
        }
    }
    else {
        task.time = -1;
    }

    return task;
}

int main(void)
{
    int i;
    int num;
    int utime;
    STask sTask;
    CRingBuf cRingBuf;
    int total = 0;

    cin >> num;
    cin >> utime;

    for (i = 0; i < num; i++) {
        scanf("%s", sTask.name);
        scanf("%d", &(sTask.time));
        cRingBuf.Enqueue(&sTask);
    }

    while (cRingBuf.BufNum() > 0) {
        sTask = cRingBuf.Dequeue();
        if (sTask.time > utime) {
            sTask.time -= utime;
            cRingBuf.Enqueue(&sTask);
            total += utime;
        }
        else {
            total += sTask.time;
            printf("%s %d\n", sTask.name, total);
        }
    }

    return 0;
}

