class Pair
{
public:
	string name;
	int value;
};

template<typename T>
class Queue
{
private:
	T* memory;
	int entrance;
	int exit;
	int count;
	int capacity;
public:
	Queue (int capacity)
	{
		this->memory = new T[capacity];
		this->entrance = 0;
		this->exit = 0;
		this->count = 0;
		this->capacity = capacity;
	}
	~Queue ()
	{
		delete[] this->memory;
	}

	void Enqueue (T item)
	{
		memory[entrance] = item;
		count++;

		entrance++;
		if (capacity <= entrance)
		{
			entrance = 0;
		}
	}

	T Dequeue ()
	{
		T returnItem = memory[exit];
		count--;

		exit++;
		if (capacity <= exit)
		{
			exit = 0;
		}

		return returnItem;
	}

	int GetCount ()
	{
		return count;
	}
};


