#include <iostream>
#include <stdlib.h>
#include <string>

class Process
{
  private:
    int time;
    std::string name;

  public:
    Process(int time = 0, std::string name = "null")
        : time(time),
          name(name)
    {
    }

    ~Process() {}

    std::string getName() const
    {
        return name;
    }

    int execute(int quantum)
    {
        if (time > quantum)
        {
            time -= quantum;
            return quantum;
        }
        else
        {
            int tmp = time;
            time = 0;
            return tmp;
        }
    }

    bool isDone()
    {
        if (time == 0)
        {
            return true;
        }
        else
        {
            return false;
        }
    }
};

class Queue
{

  private:
    int head;
    int tail;
    int element_num;
    int max_size;
    Process *queue;

  public:
    Queue(int n = 100005)
        : max_size(n),
          head(0),
          tail(0),
          element_num(0)
    {
        queue = (Process *)malloc(sizeof(Process) * max_size);
    }

    ~Queue()
    {
        free(queue);
    }

    int elementNum() const
    {
        return element_num;
    }

    int getHead() const
    {
        return head;
    }

    int getTail() const
    {
        return tail;
    }

    bool isEmpty() const
    {
        if (element_num == 0)
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    bool isFull() const
    {
        if (element_num == max_size)
        {
            return true;
        }
        else
        {
            return false;
        }
    }

    Process dequeue()
    {
        if (!this->isEmpty())
        {
            Process out = queue[head];
            head = (head + 1) % max_size;
            element_num--;
            return out;
        }
        else
        {
            std::cout << "No value in queue\n";
        }
    }

    void enqueue(Process in)
    {
        if (!this->isFull())
        {
            queue[tail] = in;
            tail = (tail + 1) % max_size;
            element_num++;
        }
        else
        {
            std::cout << "Queue is full\n";
        }
    }
};

int main()
{

    Queue q;

    int n, quantum;
    std::cin >> n >> quantum;

    int tmp_time;
    std::string tmp_name;

    int elaps = 0;

    for (int i = 0; i < n; i++)
    {
        std::cin >> tmp_name >> tmp_time;
        q.enqueue(Process(tmp_time, tmp_name));
    }

    Process tmp_process;

    while (!q.isEmpty())
    {
        tmp_process = q.dequeue();
        elaps += tmp_process.execute(quantum);
        if (!tmp_process.isDone())
        {
            q.enqueue(tmp_process);
        }
        else
        {
            std::cout << tmp_process.getName() << " " << elaps << "\n";
        }
    }

    return 0;
}

