    if (isFull()) {
      return false;
    }
    queue[head] = process;
    head++;
    if (head == MAX) {
      head = 0;
    }
    return true;
  }

  Process& pop() {
    if (isEmpty()) {
      // TODO: throw exception.
    }
    Process& value = queue[tail];
    tail++;
    if (tail == MAX) {
      tail = 0;
    }
    return value;
  }

  bool isEmpty() {
    return head == tail;
  }

  bool isFull() {
    return (head + tail) == MAX;
  }
private:
  static const int MAX = 100000;
  array<Process, MAX> queue;
  int head;
  int tail;
};

