  //  cout << "CHECK3 " << tail << endl;
  if (tail + 1 == LEN)
    tail = 0; // tail = LEN - 1で末尾のとき
  else
    tail++;
}

P dequeue() {
  // inの最初（head）の値を返す関数
  P x = in[head];
  if (head + 1 == LEN)
    head = 0;
  else
    head++;
  return x;
}

