    int end_p;
    int num;
    Process *q;
}Queue;


Process* pop(Queue *que){

    if(que->num != 0){
        que->num--;
        if(que->start_p + 1 > MAX){
            que->start_p = 0;
        }
        return &(que->q[que->start_p++]);
    }else{
