class Queue {
private:
  int head_;
  int tail_;
  const int length_;
  Process* q_;

public:
  Queue(int len) :
    head_(0), tail_(0), length_(len) {
    q_ = new Process[len];
  }
  ~Queue() {
    delete[] q_;
  }

  bool is_empty() const {
    return head_ == tail_;
  }

  bool is_full() const {
    return head_ == (tail_ + 1) % length_;
  }

  void enqueue(const Process& x) {
    if (is_full()) {
      assert("Queue is full.");
    }
    q_[tail_] = x;
    if (tail_ + 1 == length_) {
      tail_ = 0;
      cout << "enq tail = 0" << endl;
    } else {
      tail_++;
      cout << "enq tail++" << endl;
    }
  }

  Process dequeue() {
    if (is_empty()) {
      assert("Queue is empty.");
    }
    auto x = q_[head_];
    if (head_ + 1 == length_) {
      head_ = 0;
    } else {
      head_++;
    }
    return x;
  }
};

