template <class T> class Queue_Ring {

public:

    Queue_Ring(vector<T> list, int max_count):
    max_count(max_count+1){
        for(int i=0; i<max_count+1; i++){
            if(i<list.size()){
                s.push_back(list[i]);
            }else{
                s.push_back(list[0]);
            }
        }
        head = 0;
        tail = list.size();
    }

    void enqueue(T x){
        if( getDataNum() == max_count-1 ) return;
        s[tail] = x;
        tail = (tail+1)%max_count;
    }

    T dequeue(){
        T a = s[head];
        head = (head+1)%max_count;
        return a;
    }

    bool isEmpty(){
        return getDataNum() == 0;
    }

    int getDataNum(){
        if( tail - head > 0 ){
            return tail - head;
        }else if( tail - head < 0 ){
            return tail - head + max_count;
        }else{
            return 0;
        }
    }

private:
    vector<T> s;
    int head;
    int tail;
    const int max_count;

    static const int MAX = 10000;

    void reset(){
        vector<T> _s;
        for(int i=head; i<s.size(); i++){
            _s.push_back(s[i]);
        }
        s = _s;
        head = 0;
    }

};

class RoundRobinScheduling {

public:

    RoundRobinScheduling(int n, int q, vector<string> name, vector<int> time):
    n(n),
    q(q),
    name(new Queue_Ring<string>(name, n)),
    time(new Queue_Ring<int>(time, n)),
    sum_time(0){}

    ~RoundRobinScheduling(){
        delete name;
        delete time;
    }

    void update(){

        if(name->isEmpty()) return;

        string nm = name->dequeue();
        int t = time->dequeue();
        if(t>q){
            t -= q;
            name->enqueue(nm);
            time->enqueue(t);
            sum_time += q;
        }else{
            sum_time += t;
            cout << nm << " " << sum_time << endl;
        }

    }

    bool isFinished(){
        return name->isEmpty();
    }

private:
    int n;
    int q;
    Queue_Ring<string>* name;
    Queue_Ring<int>* time;

    int sum_time;

};

int main() {

    int n;
    cin >> n;

    int q;
    cin >> q;

    vector<string> name;
    vector<int> time;
    for(int i=0; i<n; i++){
        string s;
        cin >> s;
        name.push_back(s);
        int t;
        cin >> t;
        time.push_back(t);
    }

    RoundRobinScheduling* rrs = new RoundRobinScheduling(n, q, name, time);

    while (!rrs->isFinished()) {
        rrs->update();
    }

    delete rrs;

    return 0;
}

#include <iostream>
#include <deque>
#include <algorithm>
using namespace std;

struct task{
    string name;
    int time;
    int total;
};

bool compare(struct task a, struct task b)
{
    return a.total <= b.total;
}

int total_time = 0, curr = 0;

void round_robin(deque<struct task>& v, int limit)
{
    while(curr < total_time)
    {
        if(v.front().time == 0)
        {
            v.push_back(v.front());
            v.pop_front();
            continue;
        }
        else if(v.front().time <= limit)
        {
            curr += v.front().time;
            v.front().total = curr;
            v.front().time = 0;
            v.push_back(v.front());
            v.pop_front();
        }
        else
        {
            curr += limit;
            v.front().time -= limit;
            v.push_back(v.front());
            v.pop_front();
        }
    } 
}

int main()
{
    deque<struct task> v;
    int n, limit;
    cin>>n;
    cin>>limit;
    for(int i = 0;i < n;i++)
    {
        struct task tmp;
        cin>>tmp.name;
        cin>>tmp.time;
        total_time += tmp.time;
        v.push_back(tmp);
    }

    round_robin(v, limit);

   sort(v.begin(), v.end(), compare); 

    for(deque<struct task>::iterator it = v.begin(); it != v.end(); it++)
    {
        cout<<(*it).name<<" "<<(*it).total<<endl;
    }


}

