#define N 100000
int head = 0, tail = 0;
typedef struct data
{
	char name[100];
	int  time;

}Data;
Data assigment[N];//数组个数特别多要全局定义，原因还没查
int check(int time_each, int as_time)//比较两者数据
{
	return (as_time > time_each ? time_each : as_time);//返回较小的那个数
}
void enqueue(Data x)//插入队列
{
	assigment[tail] = x;//将数据插入到tail的位置
	tail = (tail + 1) % N;//得出的余数为tail的新位置，若余数为0则表示队列满了，tail到队列头第0个位置.犹如一个环形
}
Data dequeue()//将结构数据取出来
{
	Data x = assigment[head];
	head = (head + 1) % N;//同上
	return x;
}
int main()
{
	int total = 0, time_each = 0,count=1,count_time=0,margin=0;
	cin >> total >> time_each;
	Data move;
	while (count <= total)//输入数据,第0个数据不输入
	{
		cin >> assigment[count].name >> assigment[count].time;
		count++;
	}
	head = 1, tail = total + 1;//总数的后一位，空的
	while (head != tail)//当两者相等则没有了
	{
		move = dequeue();//提取数据
		margin = check(time_each, move.time);//得出较少时间的那个
		move.time -= margin;//多于或少于
		count_time += margin;//统计总时间
		if (move.time> 0)//大于时间切片
			enqueue(move);//插入后面
		else
			cout << move.name << " " << count_time << endl;

	}
	return 0;
}

