        v[tail] = p;
        if (tail + 1 == v.size()) {
            tail = 0;
        } else {
            tail++;
        }
    }

    P dequeue() {
        P p = v[head];
        if (head + 1 == v.size()) {
            head = 0;
        } else {
            head++;
        }
        return p;
    }

    bool is_empty() {
        return head == tail;
    }

