class Queue{
private:
	int fp;
	int rp;
	int d_num[100001];
	string d_name[100001];
	public:
		Queue(){
			fp = 0;
			rp = 0;
		}
		int next(int p){
			return (p+1)%100001;
		}
		bool isFull(){
			return (next(rp)==fp);
		}
		bool isEmpty(){
			return (rp==fp);
		}
		void enqueue(int d_i,string d_s){
			if(isFull()){
				return;
			}
			d_num[rp] = d_i;
			d_name[rp] = d_s;
			rp = next(rp);
		}
		int front_num(){
			if(isEmpty()){
				return -1;
			}
			return d_num[fp];
		}
		string front_name(){
			if(isEmpty()){
				return "-1";
			}
			return d_name[fp];
		}
		void dequeue(){
			if(isEmpty()){
				return;
			}
			fp = next(fp);
		}
};

