template <typename T>
class Queue {
    struct node {
        node* next;
        node* prev;
        T value;
    };
    node* head_;
    node* tail_;
    int size_;

    public:
        Queue () : size_(0) {
            node* n = new node();
            n->next = nullptr;
            n->prev = nullptr;

            head_ = n;
            tail_ = n;
        };
        ~Queue () {
            node* next = tail_;
            REP(i, size_){
                node* tmp = next->next;
                free(next);
                next = tmp;
            }
        };

        void push(T v) {
            tail_->prev = new node();
            tail_->prev->next = tail_;
            tail_ = tail_->prev;
            tail_->value = v;
            ++size_;
        }

        T pop() {
            if (!head_->prev) {
                throw;
            }

            T v = head_->prev->value;
            head_ = head_->prev;
            free(head_->next);
            --size_;
            return v;
        }

        int get_size() {return size_;}
};


