#define NUM_SIZE 100000

struct Q{
    string qname;
    int t;
};

class Queue
{
private:
    Q q[NUM_SIZE];

public:
    int head, tail = 0;

    Queue(){
        head = tail = 0;
    }
    bool isEmpty(){
        return head == tail;
    }
    bool isFull(){
        return head == (tail+1) % NUM_SIZE;
    }
    void enqueue(Q q_new){
        if (isFull()){
            runtime_error("buffer is full");
        }else{
            q[tail] = q_new;
            tail = (tail+1) % NUM_SIZE;
        }
    }

    Q dequeue(){
        if (isEmpty()){
            runtime_error("buffer is empty");
        }else{
            Q q_old = q[head];
            head = (head+1) % NUM_SIZE;
            return q_old;
        }
    }
};

