	string name[100];

	void initialize(){
		head = 0; tail = 0;
	}
	int isEmpty(){
		return head == tail;
	}
	int isFull(){
		return head == (tail + 1) % 100;
	}
	void enqueue(int x, string c){
		if (isFull()) cout << "Error" << endl;
		Q[tail] = x ;
		name[tail] = c ;
		if (tail + 1 == 100) tail = 0;
		else tail++;
	}
	int dequeue(){
		if (isEmpty()) cout << "Error" << endl;
		int x = Q[head];
		if(head + 1 == 100) head = 0;
		else head++;
		return x;
	}	
	string outname(){
		return name[head-1];
	}
};

int main(){
