using namespace std;

template<class T> class myQueue {
    list<string> name;
    list<T> que;
public:
    myQueue() {name.resize(0); que.resize(0);}

    void push(const string& n, const T& x) {
        name.push_front(n);
        que.push_front(x);
        }
    void push(const pair<string, T>& x) {
        name.push_front(x.first);
        que.push_front(x.second);
        }
    pair<string, T> get() {
        return pair<string, T>(name.back(), que.back());
        }
    void pop() {name.pop_back(); que.pop_back();}
    pair<string, T> get_pop() {
        pair<string, T> tmp =  get();
        pop();
        return tmp;
        }
    bool empty() {return name.empty();}
};

int main() {
    ll n, q;
    cin >> n >> q;
    myQueue<ll> que;

    rep(i, n) {
        string s;
        ll x;
        cin >> s >> x;
        que.push(s, x);
    }

    ll cnt = 0;
    while(!que.empty()) {
        pair<string, ll> tmp = que.get_pop();
        if (tmp.second <= q) {
            cnt += tmp.second;
            cout << tmp.first << ' ' << cnt << '\n';
        }
        else {
            cnt += q;
            tmp.second -= q;
            que.push(tmp);
        }
    }
}

