class Roundrobin{
private:
	int count, r;
	int num[10] = {};
	char rabel[10][3] = {};

public:
	Roundrobin(){
		count = 0;
		r = 0;
	}
	void setround(int ro){
		r = ro;
	}
	void add(char* name, int n){
		num[count] = n;
		strcpy(rabel[count], name);
		count++;
	}
	int pick(char* name){
		int ret = num[0];
		strcpy(name, rabel[0]);
		for (int i = 1; count > i; i++){
			num[i - 1] = num[i];
			strcpy(rabel[i - 1], rabel[i]);
		}
		count--;
		return ret;
	}
	void dow(){
		char name[3];
		int n, time = 0;
		while (count){
			n = pick(name);
			n = n-r;
			if (n > 0){
				add(name, n);
				time += r;
			}
			else{
				time += r + n;
				printf("%s %d\n", name, time);
			}
		}
	}
};

int main() {
	int n, q, i, num;
	char rabel[3];
	Roundrobin robin;
	scanf("%d %d", &n, &q);
	robin.setround(q);
	for (i = 0; n > i; i++){
		scanf("%s %d", &rabel, &num);
		robin.add(rabel, num);
	}
	robin.dow();
	return 0;
}

