template<class T>
class Queue{
private:
  T* data;
  int size;
  int rp=0;//次に入れる
  int fp=0;//次に出す
public:
  Queue(int x){data=new T[x+1];size=x+1;}
  void enqueue(T x){
    data[rp]=x;
    rp++;
    if(rp==size)rp=0;
  }
  T front(){return data[fp];}
  void dequeue(){
    fp++;
    if(fp==size)fp=0;
  }
  bool isFull(){
    if(fp==0)return rp==size-1;
    else return fp-1==rp;
  }
  bool isEmpty(){
    return rp==fp;
  }
};

