class Queue {
public:
	pair<string, int> data[100001];
	int dp, ep;

	Queue(){
		dp = 0;
		ep = 0;
	}

	void enqueue(pair<string, int> proc){
		data[ep]=proc;
		ep = ep != 100000 ? ep+1 : 0;
	}
	pair<string, int> dequeue(){
		pair<string, int> tmp = data[dp];
		dp = dp != 100000 ? dp+1 : 0;
		return tmp;
	}

	int isSize(){
		return ep-dp;
	}
};

int main(){
	int n, q, time=0;
	cin >> n >> q;
	pair<string, int> proc;
	Queue queue;
	while(cin >> proc.first >> proc.second){
		queue.enqueue(proc);
	}
	while(queue.isSize()>1){
		proc = queue.dequeue();
		if(proc.second-q> 0){
			time+=q;
			proc.second -= q;
			queue.enqueue(proc);
		}else{
			time+=proc.second;
			cout << proc.first << ' ' << time << endl;
		}
	}
