using namespace std;

class Proc{
public:
  string nam;
  int tim;
  Proc(){
    nam = "";
    tim = 0;
  }
};

Proc Q[100001];
class Queue{
private:
  int f;
  int r;
public:
  Queue(){
    f = 0;
    r = 0;
  }
  int next(int p) const{
    return (p+1)%100001;
  }
  bool isFull() const{
    return (next(r) == f);
  }
  bool isEmpty() const{
    return (r == f);
  }
  void push(Proc d){
    if(isFull()){
      return;
    }
    Q[r] = d;
    r = next(r);
  }
  Proc front(){
    if(isEmpty()){
      Proc e;
      e.tim = -1;
      return e;
    }
    return Q[f];
  }
  void pop(){
    if(isEmpty()){
      return;
    }
    f = next(f);
  }
};

int main(){
  Queue qu;
  int n,q;
  cin >> n >> q;
  for(int i=0;i<n;i++){
    Proc p;
    cin >> p.nam >> p.tim;
    qu.push(p);
  }
  int total_tim = 0;
  while(!qu.isEmpty()){
    Proc p = qu.front();
    qu.pop();
    if(p.tim <= q){
      total_tim += p.tim;
      cout << p.nam << ' ' << total_tim << endl;
    }else{
      total_tim += q;
      p.tim -=q;
      qu.push(p);
    }
  }
  return 0;
}

