class Queue{
    vector<pair<string, int> > q;
    int head = 0;
    int tail = 0;
public:
    Queue(){
        q.resize(MAX);
    }
    bool is_empty(){
        if (head == tail) return true;
        return false;
    }
    void enqueue(pair<string, int> num){
        q[tail] = num;
        tail = (tail + 1) % MAX;
    }
    pair<string, int> dequeue(){
        pair<string, int> ret = q[head];
        head = (head + 1) % MAX;
        return ret;
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    Queue que1;
    for (int i = 0; i < n; i++) {
        string p;
        int num;
