        que1.enqueue(make_pair(p, num));
    }
    Queue que2;
    int time_ = 0;
    while(!que1.is_empty()) {
        pair<string, int> front = que1.dequeue();
        if (front.second <= q) {
            time_ += front.second;
            front.second = time_;
            que2.enqueue(front);
        } else {
            front.second -= q;
            time_ += q;
            que1.enqueue(front);
        }
    }
    while (!que2.is_empty()) {
        pair<string, int> front = que2.dequeue();
        cout << front.first << " " << front.second << endl;
