#include<bits/stdc++.h>
using namespace std;

const int MARGIN = 5;

struct{
	string name;
	int time;
}typedef Process;


class ProcessQueue{
private:
	Process* queueArr;
	int currTop;
	int currLimit;
	int MAX;

public:
	ProcessQueue(int n);
	Process pop();
	void enQueue(Process p);
	int getSize();

private:
	int toI(int i,bool isPositive);
};

ProcessQueue::ProcessQueue(int n){
	currTop = 0;
	currLimit = 0;
	MAX = n;
	queueArr = new Process[n + MARGIN];
}

Process ProcessQueue::pop(){
	if(currTop == currLimit){
		Process error;
		error.name = "error";
		error.time = 0;
		return error;
	}
	Process curr = queueArr[currTop];
	currTop = toI(currTop,true);
	return curr;
}

void ProcessQueue::enQueue(Process p){
	if(currTop == toI(currLimit,true))
		return;
	queueArr[currLimit] = p;
	currLimit = toI(currLimit,true);
}

int ProcessQueue::getSize(){
	return (currLimit >= currTop) ? currLimit - currTop : MAX - (currTop - currLimit);
}

int ProcessQueue::toI(int i,bool isPositive){
	if(i == MAX && isPositive)
		return 0;
	if(i == 0 && !isPositive)
		return MAX;
	return (isPositive) ? i + 1 : i - 1;
}

void simurateRoundRobin(ProcessQueue* quu,int q){
	int total = 0;
	while(quu->getSize() > 0){
		Process p = quu->pop();
		p.time -= q;
		if(p.time > 0){
			quu->enQueue(p);
			total += q;
		}else{
			int resultTime = p.time + q;
			total += resultTime;
			cout << p.name << " " << total << endl;
		}
	}
}

int main(){
	int n,q;
	cin >> n;
	cin >> q;
	ProcessQueue queueArr(n);
	for(int i = 0; i < n;i++){
		Process p;
		cin >> p.name;
		cin >> p.time;
		queueArr.enQueue(p);
	}
	simurateRoundRobin(&queueArr,q);
	return 0;
}

