};

void print(const vector<Process> &vec) {
    for (const auto &v : vec) cout << v.name << " " << v.time << endl;
}

vector<Process> simulate(vector<Process> &vec, int q) {
    vector<Process> result;
    int time = 0;

    while (!vec.empty()) {
        Process proc = vec.at(0);
        vec.erase(vec.begin());
        if (proc.time > q) {
            proc.time -= q;
            vec.push_back(proc);
            time += q;
        } else {
            int tmpTime = proc.time;
            proc.time += time;
            result.push_back(proc);
            time += tmpTime;
        }
    }

    return result;
}

