class queue{
    int *time;
    char (*name)[11];
    int head, tail, size;
public:
    queue(int n){
        size = n;
        time = new int [size];
        name = new char [size][11];
        head = 0;
        tail = 0;
    };
    bool isEmpty(){
        return head==tail;
    };
    bool isFull(){
        return tail==head+size;
    };
    int &enqueue(char *s);
    int dequque(char *s);
};

int &queue::enqueue(char *s){
    if(isFull()){
        printf("queue is full.\n");
        exit(1);
    }
    strcpy(name[(tail)%size],s);
    tail = (tail+1) % (2*size);
    return time[(tail-1)%size];
}

int queue::dequque(char *s){
    if(isEmpty()){
        printf("queue is empty.\n");
        exit(1);
    }
    strcpy(s,name[(head)%size]);
    head = (head+1) % (2*size);
    return time[(head-1)%size];
}

