class job{
public:
	job(){}
	job(string n, int t){
		name = n;
		time = t;
	}
	job(const job& a){
		name = a.name;
		time = a.time;
	}
	void operator=(const job& a){
		name = a.name;
		time = a.time;
	}
	string name;
	int  time;
};

class queue{
public:
	queue(int q, int n):_head(0),_tail(0){
		_num = n+1;
		_queue = new job[_num];
	}
	~queue(){delete[] _queue;}
	job deq(){
		int head = _head;
		_head = ++_head >= _num ? 0:_head;
		return _queue[head];
	}
	void enq(job a){
		_queue[_tail++] = a;
		_tail = _tail >= _num ? 0: _tail;
	}
	bool check(){
		return _tail == _head;
	}

private:
	job* _queue;
	int _head;
	int _tail;
	int _num;
};

