pair<string, int> queue_shift(vector<pair<string, int>> &v, int &fronti) {
  pair<string, int> tmp;
  tmp.first  = v[fronti].first;
  tmp.second = v[fronti].second;
  fronti = (fronti + 1) % v.size();
  return tmp;
}

void queue_push(vector<pair<string, int>> &v, int &backi, pair<string, int> &tmp) {
  v[backi].first  = tmp.first;
  v[backi].second = tmp.second;
  backi = (backi + 1) % v.size();
}

