    void Enqueue(Proc& proc);
    Proc Dequeue();
    bool IsEmpty();

private:
    vector<Proc> m_queue;
    int m_head;
    int m_tail;
};

void Queue::Enqueue(Proc& proc)
{
    m_queue[m_tail] = proc;
    m_tail++;
    m_tail %= m_queue.size();
}

Proc Queue::Dequeue()
{
    Proc ret = m_queue[m_head];
    m_head++;
    m_head %= m_queue.size();

    return ret;
}

bool Queue::IsEmpty()
{
    return m_head == m_tail;
}

