using namespace std;

class Stack{
private:
	int sp;
	int S[100];
public:
	Stack(){
		sp=0;
	}
	bool isFull()const {
		return(sp==100);
	}
	bool isEmpty()const {
		return(sp==0);
	}
	void push(int d){
		if(isFull()) 
			return;
		S[sp++]=d;
	}
	int top(){
		if(isEmpty())
			return -1;
		return S[sp-1];
	}
	void pop(){
		if(isEmpty())
			return;
		sp--;
	}
};

int main(){
	Stack s;
	string expr;
	getline(cin,expr);
	istringstream is(expr);

	while(!is.eof()){
		string op;
		is>>op;
		int tmp1,tmp2;
		switch(op[0]){
		case '+':
			tmp1=s.top(); s.pop();
			tmp2=s.top(); s.pop();
			s.push(tmp1+tmp2);
			break;
		case '-':
			tmp1=s.top(); s.pop();
			tmp2=s.top(); s.pop();
			s.push(tmp2-tmp1);
			break;
		case '*':
			tmp1=s.top(); s.pop();
			tmp2=s.top(); s.pop();
			s.push(tmp1*tmp2);
			break;
		default:
			istringstream is2(op);
			is2>>tmp1;
			s.push(tmp1);
			break;
		}
	}
	cout<<s.top()<<endl;
	return 0;
}

