#define MAX_STACKS 102
#define MAX_DEQUE 100001

struct Data{
  int time;
  char name[16];
};

class Deque{
  Data* addrs[MAX_DEQUE] = { 0 };

  int head = 0;
  int tail = 0;
public:
  void printDeque(){
    int idx = head;
    for( idx; idx >tail; idx-- ){
      std::cout << idx << ": " << addrs[idx]->time << "    " << addrs[idx]->name << std::endl;
    }
  }

  void enque( Data& d ){
    if( head >= MAX_DEQUE-1 ){
      head = 0;
    } else {
      head++;
    }
    addrs[head] = new Data;
    *addrs[head] = d;
    return;
  }

  Data deque(){
    tail++;
    if( tail >= MAX_DEQUE ) tail = 0;
    Data ret = *addrs[tail];
    delete addrs[tail];
    return ret;
  }

  bool isEmpty(){
    return head == tail;
  }

};

class Stack{
  int* addrs[MAX_STACKS];
  unsigned int top = 0;
public:
  int pop(){
    if( top <= 0 ){
      std::cerr << "No stacks" << std::endl;
      exit(0);
    }

    int n = *(addrs[top]);
    delete addrs[top];
    top--;
    return n;
  }
  void push( int num ){
    if( top >= MAX_STACKS - 1 ){
      std::cerr << "Stacks max" << std::endl;
      exit( 0 );
    }
    top++;
    addrs[top] = new int;
    *(addrs[top]) = num;
    return;
  }
};

int main(){
  Deque que;
  int N, Q;
  int time = 0;
  std::cin >> N >> Q;
  for( int i = 0; i < N; i++ ){
    Data d;
    std::cin >> d.name >> d.time;
    que.enque( d );
  }

  while( !que.isEmpty() ){
    Data d = que.deque();
    time += std::min( d.time, Q );
    d.time -= Q;
    if( d.time <= 0 ){
      std::cout << d.name << " " << time << std::endl;
    } else {
      que.enque( d );
    }
  }
}

