Queue<T>::~Queue()
{
  Node<T>* current = head_;
  while (current != nullptr) {
    Node<T>* next = current->next_;
    delete current;
    current = next;
  }
}

template <class T>
void Queue<T>::push(T d)
{
  Node<T>* tail = new Node<T>;
  tail->d_ = d;
  tail->next_ = nullptr;

  if (head_ == nullptr) {
    head_ = tail;
    return ;
  }

  Node<T>* node = head_;
  while (node->next_ != nullptr)
    node = node->next_;
  node->next_ = tail;
}

template <class T>
void Queue<T>::pop()
{
  Node<T>* t = head_;
  head_ = head_->next_;
  delete t;
}

template <class T>
T Queue<T>::front()
{
  return head_->d_;
}

template <class T>
bool Queue<T>::empty()
{
  return (head_ == nullptr);
}


