	int n, q, i, num;
	char rabel[3];
	Roundrobin robin;
	scanf("%d %d", &n, &q);
	robin.setround(q);
	for (i = 0; n > i; i++){
		scanf("%s %d", &rabel, &num);
		robin.add(rabel, num);
	}
	robin.dow();
	return 0;
}

