        int EndTime;
        int Q;

};

class QueueClass
{
    private:
      int Head, Tail;
      ProcessClass *Array;
    public :
        QueueClass(){}
        QueueClass(int NSIZE)
        { Array = new ProcessClass[NSIZE]; Head = Tail = 0;  }
        ~QueueClass()
        { delete [] Array; }

        ProcessClass Front()
        { return Array[Head]; }
        void Pop()
        { ++Head; }
        void Push(ProcessClass value)
        { Array[Tail++] = value; }

        bool IsEmpty()
        { return Head == Tail; }


};

