using namespace std ;

template<class T> class myQueue{
  vector<T> v;
  public:
  myQueue(){};
  void push(T n_){
    v.push_back(n_) ;
  }
  void pop(){
    v.erase(v.begin()) ;
  }
  bool empty(){
    return v.empty() ;
  }
  T front(){
    return v[0] ;
  }
  T back(){
    return v[v.size()-1] ;
  }
  size_t size(){
    return v.size() ;
  }
};

int main(){
  myQueue<pair<string,int>> mq;
  int n,q,n2,time = 0,suf = 0 ;
  string s;
  pair<string,int> psi;
