void initialize(){
    head=tail=0;
}

int isEmpty(){
    return head==tail;
}

int isFull(){
    return head==(tail+1)%MAX;
}

void enqueue(BOX *x){
    if(isFull())return;
    Q[tail]=*x;
    if(tail+1==MAX)tail=0;
    else tail++;
}

BOX dequeue(){
    BOX x;
    x=Q[head];
    if(head+1==MAX)head=0;
    else head++;
    return x;
}

