    string name;
    int time;
};

class Que{
    public:
    int Max;
Que(int n){
    Max=n+1;//nが容量数。1っこ多めに。
    array=new pp[Max];
    head=0;tail=0;
}
bool isEmpty(){
    return head==tail;
}
bool isFull(){
    return head==(tail+1)%Max;
}
void enqueue(pp x){
    array[tail]=x;
    if(tail+1==Max)tail=0;
    else{tail++;}
}
pp dequeue(){
    pp x=array[head];
    if(head+1==Max)head=0;
    else{head++;}
    return x;
}
    private:
    int head,tail;
    pp* array;
};

int main(){
    int n,p;
    cin>>n>>p;
    Que q(n);pp p_p[n];
    for(int i=0;i<n;i++){
        cin>>p_p[i].name>>p_p[i].time;
        q.enqueue(p_p[i]);
    }
    pp ans[n];
    int ans_time=0,now=0;
    while(! q.isEmpty()){
        pp tmp=q.dequeue();
        if(tmp.time<=p){
            ans_time+=tmp.time;
            ans[now].name=tmp.name;
            ans[now].time=ans_time;
            now++;
        }
        else{
            ans_time+=p;
            tmp.time-=p;
            q.enqueue(tmp);
        }
    }
    for(int j=0;j<n;j++){
        cout<<ans[j].name<<' '<<ans[j].time<<endl;
    }
    return 0;
}

