struct finished
{
	string name;
	int    time;
};

queue<finished> RoundRobin(queue<process> X, int q)
{
	queue<finished> Y;
	int totaltime = 0;
	while(X.size() > 0){
		if(X.front().time <= q){
			totaltime += X.front().time;
			finished output;
			output.name = X.front().name;
			output.time = totaltime;
			X.pop();
			Y.push(output);
		}else{
			totaltime += q;
			X.front().time -= q;
			X.push(X.front());
			X.pop();
		}
	}
	return Y;
}

