// Ring-buffer based queue. Enqueue and dequeue run in O(1).
template <typename T, int N>
class Queue {
 public:
  // Note: leave one element empty so that we can distinguish
  // that the ring buffer is empty or full.
  Queue()
      : size_(N + 1),
        begin_((T*)data_),
        end_((T*)data_ + N + 1),
        head_((T*)data_),
        tail_((T*)data_) {}

  void Enqueue(T p) {
    assert(!IsFull());
    *tail_ = p;
    tail_ = next(tail_);
  }

  T Dequeue() {
    assert(!Empty());
    auto p = head_;
    head_ = next(head_);
    return *p;
  }

  bool IsFull() const { return head_ == next(tail_); }

  bool Empty() const { return head_ == tail_; }

 private:
  T* next(T* p) const { return p + 1 == end_ ? begin_ : p + 1; }

  char data_[sizeof(T) * (N + 1)];
  const int size_;
  T* const begin_;
  T* const end_;
  T* head_;
  T* tail_;
};

}  // namespace

int main() {
  int n;
  int q;
  cin >> n >> q;

  Queue<Process, 100000> queue;
  for (int i = 0; i < n; ++i) {
    Process p;
    scanf("%s %d", p.name, &p.time);
    queue.Enqueue(p);
  }

  int current_time = 0;
  while (!queue.Empty()) {
    auto p = queue.Dequeue();
    const int used = min(p.time, q);
    p.time -= used;
    current_time += used;

    if (p.time <= 0) {
      printf("%s %d\n", p.name, current_time);
      continue;
    }
    queue.Enqueue(p);
  }
  return 0;
}

