template <typename T>
struct queue{
  std::unique_ptr<T[]> c;
  size_t head;
  size_t tail;
  const size_t max;
public:
  queue(size_t n):c(new T[n]),head(0),tail(0),max(n){}
  bool empty(){return head == tail;}
  void push(T& v){
    c[tail++] = v;
    if(tail == max) tail = 0;
  }
  T&& pop(){
    auto r = c[head++];
    if(head == max) head = 0;
    return std::move(r);
  }
};

void execute(queue<process>& l,const unsigned long q, unsigned long time_now){
  if(l.empty()){return;}
  process buf = l.pop();

  if(buf.time <= q){
    time_now += buf.time;
    cout << buf.name << ' ' << time_now << '\n';
  }
  else{
    buf.time -= q;
    time_now += q;
    l.push(buf);
  }

  execute(l,q,time_now);
}

