bool isFull(){
    return head==(tail+1)%(n+1);
}
bool isEmpty(){
    return head==tail;
}

void enqueue(int *time,std::string *queue,int t,std::string str){
    if(isFull()){
        std::cerr << "Size over!!\n";
        exit(1);
    }
    time[tail] = t;
    queue[tail] = str;
    if(tail==n){
        tail = 0;
    }else{
        tail++;
    }
}

int dequeue(int *time){
    if(isEmpty()){
        std::cerr << "Empty!!\n";
        exit(1);
    }
    int x = time[head];
    time[head] = -1;
    if(head==n){
        head = 0;
    }else{
        head++;
    }
    return x;
}

void initialize(int* sum1,std::string *queue,int *time){
    head = 0;
    tail = 0;
    std::string str;
    int t;
    for(int i=0;i<n;i++){
        std::cin >> str >> t;
        enqueue(time,queue,t,str);
        *sum1+=t;
    }
}

