const int MAX = 100000;

struct Proc
{
    std::string name;
    int time;
};

class Queue
{
    private:
        Proc procs[MAX];
        int head;
        int tail;

    public:
        Queue()
        {
            head = 0;
            tail = 0;
        }
        void enqueue(Proc p)
        {
            procs[tail] = p;
            if (tail + 1 == MAX)
                tail = 0;
            else
                ++tail;
        }

        Proc dequeue()
        {
            Proc p = procs[head];
            if (head + 1 == MAX)
                head = 0;
            else
                ++head;
            return p;
        }

        bool isfull()
        {
            return head == (tail + 1) % MAX;
        }

        bool isempty()
        {
            return head == tail;
        }
};

int main()
{
    std::ios::sync_with_stdio(false);
    std::cin.tie(0);

    Queue queue;
    int n, q;
    std::cin >> n >> q;
    while (n--) {
        std::string name;
        int time;
        std::cin>> name >> time;
        Proc p;
        p.name = name;
        p.time = time;
        queue.enqueue(p);
    }
    int time = 0;
    while (!queue.isempty()) {
        Proc p = queue.dequeue();
        if (p.time <= q) {
            time += p.time;
            p.time = 0;
            std::cout << p.name << " " << time << std::endl;
            continue;
        }
        p.time -= q;
        queue.enqueue(p);
        time += q;
    }
}

