constexpr int kQueueMax = 100'000;
struct Process{
	string name;
	int time;
};
class Queue {
public:
	Queue():m_Head(0), m_Tail(0), m_Queue() {
	}
	void Enqueue(const Process &p) {
		if (isFull()) return;
		m_Queue[m_Tail] = p;
		m_Tail = (m_Tail + 1 == kQueueMax ? 0 : m_Tail + 1);
	}
	Process Dequeue(void) {
		if (isEmpty()) return Process();
		Process& p = m_Queue[m_Head];
		m_Head = (m_Head + 1 == kQueueMax ? 0 : m_Head + 1);
		return p;
	}
	bool isEmpty() const {
		return  m_Head == m_Tail;
	}
	bool isFull() const {
		// Head と Tail の間は1つ空ける
		return (m_Tail + 1) % kQueueMax == m_Head;
	}
private:
	int m_Head;
	int m_Tail;
	Process m_Queue[kQueueMax];
};

void ProcessScheduler(int size, int quantum) {
	unique_ptr<Queue> queue = make_unique<Queue>();
	for(auto s = readString(); !readEof(); s = readString()) {
		auto time = read();
		queue->Enqueue({s, time});
	}

	int total_time = 0;
	while(!queue->isEmpty()) {
		Process p(queue->Dequeue());
		if (p.time <= quantum) { // 終了処理
			total_time += p.time;
			print(p.name);
			print(" ");
			println(total_time);
		} else { // ラウンドロビン
			p.time -= quantum;
			total_time += quantum;
			queue->Enqueue(p);
		}
	}
	return;
}

signed main(void){
	cin.tie(0);
	ios::sync_with_stdio(false);

	int size = read();
	int quantum = read();
	ProcessScheduler(size, quantum);

	return 0;
}

