void round_robin_scheduling(queue<pair<string, int> > q, int quantum){
  int cur_time = 0;
  pair<string, int> p_i;

  while(!q.empty()){
    p_i = q.front(); q.pop();

    int timediff = p_i.second - quantum;    
    if(timediff > 0){
      p_i.second -= quantum;
      q.push(p_i);
      cur_time += quantum;
    }
    else{
      cur_time += p_i.second;
      cout << p_i.first << " " << cur_time << endl;
    }

  }
}

