	ProcessQueue queueArr(n);
	for(int i = 0; i < n;i++){
		Process p;
		cin >> p.name;
		cin >> p.time;
		queueArr.enQueue(p);
	}
	simurateRoundRobin(&queueArr,q);
	return 0;
}

