void remove(Process *process,int pronum){
  for ( int i = 0 ; i < pronum - 2; i++){
    process[i] = process[i+1];
  }
}

void move(Process *process,int pronum){
  Process temp;
  temp = process[0];
  for ( int i = 0 ; i < pronum - 2 ; i++){
    process[i] = process[i+1];
  }
  process[pronum - 1] = temp;
}

