  struct node *next;
  long key;
};
typedef struct node * NP;
NP MN(long);
void IN(NP);
void DN(NP);
void FI(long);
NP dummy;

int main(){
  long n,val;
  string op;

  scanf("%ld",&n);
  dummy = MN(0);

  while(n-- >0){
    cin >> op;
    if(op == "insert"){
      scanf("%ld",&val);
      IN(MN(val));
    }
    else if(op == "delete"){
      scanf("%ld",&val);
      FI(val);
    }
    else if(op == "deleteFirst"){
      FI(dummy->next->key);
    }
    else if(op == "deleteLast"){
      FI(dummy->prev->key);
    }
  }

  for(NP n=dummy->next;n!=dummy;n = n->next){
    cout << n->key;
    if(n->next != dummy)printf(" ");
  }  
  printf("\n");

  return 0;
}


void FI(long value){
  NP n;
  dummy->key = value;
  for(n = dummy->next;;n=n->next){
    if(n->key == value)break;
  }
  if(n != dummy)DN(n);


}


void DN(NP th){
  th->prev->next = th->next;
  th->next->prev = th->prev;
  th->prev = th->next = th;
  free(th);
}


void IN(NP newn){
  newn->next = dummy->next;
  newn->next->prev = newn;
  dummy->next = newn;
  newn->prev = dummy;
}

NP MN(long key){
  NP n = (NP)malloc(sizeof(struct node));
  n->prev = n;
  n->next = n;
  n->key = key;
  return n;
}

