void solve() {
  int n, q; cin >> n >> q;
  queue<pair<string, int>> que;
  rep(_, n) {
    string s;
    int t;
    cin >> s >> t;
    que.push({s, t});
  }
  int sum = 0;
  vector<pair<string, int>> ans;
  while (!que.empty()) {
    string s;
    int t;
    tie(s, t) = que.front(), que.pop();
    if (t > q) t -= q, sum += q, que.push({s, t});
    else {
      ans.push_back({s, sum + t});
      sum += t;
    }
  }
  rep(i, n) {
    cout << ans[i].first << " " << ans[i].second << '\n';
  }
}

