// プロセスを表す構造体
struct P {
    string name;
    int t;
};

// グローバル変数
static const int len = 100005;

void enqueue(P Q[], P x, int& tail) {
    if (tail == len) {
        tail = 0;
    }

    Q[tail++] = x;
}

P dequeue(P Q[], int& head) {
    if (head == len) {
        head = 0;
    }
    return Q[head++];
}

int main() {
    int n, q;
    cin >> n >> q;

    P Q[len];
    // 全プロセスを順にqueueに追加（準備）
    for (int i = 1; i <= n; ++i) {
        cin >> Q[i].name >> Q[i].t;
    }
    int head = 1;
    int tail = n + 1;

    // シミュレーション開始
    int elaps = 0;  // 経過時刻
    while (head != tail) {
        P target_process = dequeue(Q, head);
        if (target_process.t <= q) {
            elaps += target_process.t;
            cout << target_process.name << " " << elaps << endl;
            continue;
        }

        target_process.t -= q;
        elaps += q;
        enqueue(Q, target_process, tail);
    }
    return 0;
}

#include <iostream>
