struct node{
	string name;
	long number;
	node *next;
};

class myQueue{
private:
	node *head;
	node *tail;
public:
	myQueue(string name,long number);
	void pushBack(string name,long number);
	void pop();
	node *top();
	void printQueue();
	bool isEmpty();
};

myQueue::myQueue(string name,long number){
	node *newNode = new node;
	newNode->name = name;
	newNode->number = number;
	newNode->next = NULL;
	head = newNode;
	tail = newNode;
}

void myQueue::pushBack(string name,long number){
	node *newNode = new node;
	newNode->name = name;
	newNode->number = number;
	newNode->next = NULL;
	tail->next = newNode;
	tail = newNode;
}



void myQueue::pop(){
	node *targetNode;
	targetNode = head;
	head = targetNode->next;
	delete targetNode;
}

node* myQueue::top(){
	return head;
}

void myQueue::printQueue(){
	node *node;
	node = head;
	while(node != NULL){
		cout <<node->name <<" "<< node->number << endl;
		node = node->next;
	}
}

bool myQueue::isEmpty(){
	if(head == NULL) return true;
	return false;
}

int main()
{
	int n;
	long q;
	cin >> n >> q;
	string name;
	long num;
	cin >> name >> num;
	myQueue myQ = myQueue(name,num);
	for(int i = 1; i < n; i++){
		cin >> name >> num;
		myQ.pushBack(name,num);
	}
	long time = 0;
	while( !myQ.isEmpty()){
		if( myQ.top()->number <= q){
			time += myQ.top()->number;
			cout<< myQ.top()->name<<" "<<time<<endl;
			myQ.pop();
		}else{
			time += q;
			myQ.pushBack(myQ.top()->name,myQ.top()->number - q);
			myQ.pop();
		}
	}
	return 0;
}

