    if (getline(ss, s, ' '))
        n = std::stoi(s);
    if (getline(ss, s, ' '))
        quantum = std::stoi(s);

    std::queue<std::pair<std::string, int>> qpairProcess;

    for (int i = 0; i < n; i++) qpairProcess.push(GetProc());

    ExecRoundRobinScheduling(qpairProcess, quantum);

    return 0;
}

