template <typename T>
class Queue {
private:
    static const int max = 100005;
    T q[max];
    int head = 0;
    int tail = 0;
public:
    void initialie() {
        head = tail = 0;
    }
    bool is_full() {
        return head == (tail+1)%max;
    }
    bool is_empty() {
        return head == tail;
    }
    void push(T x) {
        if (!is_full()) {
            q[tail] = x;
            if(tail+1 == max) tail=0;
            else ++tail;
        }
        else cout << "queue is full!" << endl;
    }
    T pop() {
        if (!is_empty()) {
            T x = q[head];
            if(head+1 == max) head =0;
            else ++head;
            return x;
        }
        else cout << "queue is empty!" << endl;
    }
};

