using namespace std;

class Data
{
private:
    string name;
    int value;

public:
    Data() : name(""), value(0) {}
    Data(const string& s, int n) : name(s), value(n) {}
public:
    string GetName() const { return name; }
    int GetValue() const { return value; }
    void SetName(const string& _name) { name = _name; }
    void SetValue(int _value) { value = _value; }
};

class MyQueue
{
private:
    Data* list;
    int size;
    int topIdx;
    int lastIdx;

public:
    MyQueue();

    ~MyQueue();

public:
    void enqueue(Data& _data);
    Data dequeue();

    bool isEnd();
};

MyQueue::MyQueue()
    : topIdx(0)
    , lastIdx(0)
{
    list = new Data[200000];
}

MyQueue::~MyQueue()
{
    delete[] list;
}

void MyQueue::enqueue(Data& _data)
{
    list[lastIdx++] = _data;
}

Data MyQueue::dequeue()
{
    return list[topIdx++];
}

bool MyQueue::isEnd()
{
    if (topIdx == lastIdx)
        return true;

    return false;
}

int main()
{
    int size, q, val;
    string key;
    int quon = 0;

    cin >> size >> q;
    MyQueue myqueue;
    for (int i = 0; i < size; i++) {
        cin >> key >> val;
        Data t(key, val);
        myqueue.enqueue(t);
    }

    while (!myqueue.isEnd()) {
        Data t = myqueue.dequeue();
        int tval = t.GetValue();
        if (tval <= q) {
            quon += tval;
            cout << t.GetName() << " " << quon << "\n";
        }
        else {
            quon += q;
            tval -= q;
            t.SetValue(tval);
            myqueue.enqueue(t);
        }
    }

    return 0;
}

