    }
    bool is_empty(){
        return head == tail;
    }
    void enqueue(pair<string, int> num){
        q[tail] = num;
        tail = (tail + 1) % MAX;
    }
    pair<string, int> dequeue(){
        pair<string, int> ret = q[head];
        head = (head + 1) % MAX;
        return ret;
    }
};

int main(){
