#define LEN 100005
#define rep(i,n) for(int i = 0; i < n; i++)

struct process {
    char name[100];
    int time;
};

process Q[LEN];
int head, tail;

void initialze(int n) {
    head = 0;
    tail = n;
}

bool isEmpty() {
    return head == tail;
}

bool isFull() {
    return head == (tail + 1) % LEN;
}

void enqueue(process x) {
    if (isFull()) {
        fprintf(stderr, "Fullなのでenqueueできない\n");
        exit(1);
    }
    Q[tail] = x;

    if(tail == LEN -1) {
        tail = 0;
    }
    else {
        tail++;
    }
}

process dequeue() {
    if(isEmpty()) {
        fprintf(stderr, "Emptyなのでdequeueできない\n");
        exit(1);
    }
    if(head == LEN -1) {
        head = 0;
        return Q[LEN-1];
    }
    else {
        head++;
        return Q[head-1];
    }
}

int min(int a, int b) {
    return a > b ? b : a ; 
}


