    int  q;
    int elaps = 0; // 経過時間を計測するための変数
    int c,n;
    process x;

    scanf("%d %d", &n,&q);

    // 全てのプロセスをキューに順番に追加
    rep(i,n) {
        scanf("%s%d", Q[i].name, &Q[i].time);
    }
    initialze(n);

    while(!isEmpty()) {

        x = dequeue();
        c = min(q,x.time);
        x.time -= c;
        elaps += c;
        // 処理が完了していなければ、キューに再び追加する
        if(x.time > 0) {
            enqueue(x);
        }
        else {
