class Que {
 public:
  string name;
  int time;
};

int main() {
  int num;
  int quantum;
  cin >> num >> quantum;
  deque<Que*> dq;
  for (int i = 0; i < num; i++) {
    Que* que = new Que();
    cin >> que->name >> que->time;
    dq.push_back(que);
  }
  int progress;
  while (dq.size() > 0) {
    Que* que = dq.front();
    dq.pop_front();
    if (que->time <= quantum) {
      progress += que->time;
      cout << que->name << " " << progress << endl;
      delete que;
    } else {
      progress += quantum;
      que->time -= quantum;
      dq.push_back(que);
    }
  }
  return 0;
}

