struct process_t {
  string name;
  uint32_t time;
  bool operator==(const process_t &p1) const
  {
    return (p1.name == this->name) && (p1.time == this->time);
  }
};

using namespace std;

#define ARRAY_SIZE 100000
process_t processes[ARRAY_SIZE];
uint32_t head, tail;

bool queue_dequeue(process_t &process)
{
  if (head == tail) return false;
  process = processes[head];
  head++;
  head %= ARRAY_SIZE;
  return true;
}

void queue_enqueue(process_t process)
{
  processes[tail] = process;
  tail++;
  tail %= ARRAY_SIZE;
}

bool queue_empty()
{
  if (head == tail)
    return true;
  else
    return false;
}

