using namespace std;
class queue{
  public:
    queue(const int n, const int q);
    void enqueue(const pair<int,char*>& data);
    void dequeue();
    void operation ();
    int calculate (int time);

  private:
    vector< pair< int, char*> > mData;
    int mOperationTime;
    int mHead;
    int mTail;
    int mBufferSize;
    int mDone;
    int mTimeFromStart;
};

queue::queue(const int n ,const int q){
  mHead = 0; mTail = 0;
  mData.reserve(n);
  mBufferSize = n;
  mDone = 0;
  mTimeFromStart = 0;
  mOperationTime = q;
}

void queue::enqueue(const pair<int,char*>& data){
    mData.push_back(data);
    mTail++;
    if(mTail==mBufferSize) 
        mTail=0;
};

void queue::dequeue(){
    //cout << mData[mHead].second << " " << mTimeFromStart << "\n";
    printf("%s %d\n", mData[mHead].second, mTimeFromStart);
    mData.erase(mData.begin() + mHead);
    mHead--;
    mDone++;
};

int queue::calculate(int time){
    //if(mData[mHead].first != 0) {
        if(mData[mHead].first - time <= 0) {                     
            mTimeFromStart += mData[mHead].first;                
            mData[mHead].first = 0;
            dequeue();
            return 0;
        }
        else {
            mData[mHead].first -= time; 
            mTimeFromStart += time;
            return 0;
        }
    //}
    //else {
    //    return time;
    //}
};

void queue::operation (){
    int operation_time = mOperationTime;
    while(1){
        operation_time = calculate(operation_time);
        if(operation_time==0) {
            operation_time = mOperationTime;
        }
        mHead++;
        if(mHead == mData.size()) {
            mHead = 0;
        }
        if(mDone == mBufferSize) {
            break;
        }
    }
    return;
}

