#define LM 100000

struct process{
    string name;
    int qms;
};

struct queue{
    static const int QM=LM;
    process *q;
    //process q[QM];
    process *qend;

    process *head,*tail;
    queue(){
        q=new process[QM];
        if(q==NULL)err("q is NULL");
        qend=q+QM-1;

        head=q;
        tail=q;
    }
    ~queue(){
        delete[] q;
    }
    bool isEmpty(){return head==tail;}
    bool isFull(){return (head-1)==tail;}
    void err(const char *s){cerr<<s<<endl;exit(1);}
    void inc(process* &p){
        if(p==qend){
            p=q;
        }else{
            p++;
        }
    }
    void enqueue(process x){
        if(isFull())err("enqueue:full");
        *tail=x;
        inc(tail);
    }
    void enqueue(string name,int qms){
        const process tmp={name,qms};
        enqueue(tmp);
    }
    process dequeue(){
        if(isEmpty())err("dequeue:empty");
        const process ans=*head;
        inc(head);
        return ans;
    }
};

