using namespace std ;

template<class T> class myQueue{
  deque<T> v;
  public:
  myQueue(){};
  void push(const T & n_){
    v.push_back(n_) ;
  }
  void pop(){
    v.erase(v.begin()) ;
  }
  bool empty(){
    return v.empty() ;
  }
  T front(){
    return v[0] ;
  }
  T back(){
    return v[v.size()-1] ;
  }
  size_t size(){
    return v.size() ;
  }
};

template<class T> class myQueueC{
  int size;
  T *v ;
  public:
  myQueueC(){
    size = 0 ;
  }
  myQueueC(const int& s_){
    size = s_ * 3 ;
    v = new T[size] ;
  }
  myQueueC(const int& s_, T init){
    size = s_ * 3;
    v = new T[size] ;
    for(int i = 0; i < size; ++i){
      v[i] = init ;
    }
  }
  T front(){
    return v[0] ;
  }
  void push(const T& n_){
    T *tmp;
    int _size = size ;
    ++size ;
    tmp = new T[size] ;
    for(int i = 0;i < _size; ++i){
      tmp[i] = v[i] ;
    }
    tmp[_size] = n_ ;
    v = new T[size] ;
    for(int i = 0;i < size; ++i){
      v[i] = tmp[i] ;
    }
  }
  void pop(){
    T *tmp;
    int _size = size-1 ;
    tmp = new T[_size];
    for(int i= 1; i < size;++i){
      tmp[i-1] = v[i] ;
    }
    delete[] v ;
    v = new T[_size] ;
    for(int i =0; i < _size;++i){
      v[i] = tmp[i] ;
    }
    --size;
  }
  void out(){
    for(int i = 0; i < size;++i){
      cout << v[i].fi << " \n";
    }
    cout << endl ;
  }
  bool empty(){
    return size == 0 ;
  }
  int Size(){
    return size;
  }
  ~myQueueC(){
    delete[] v ;
  }
};

int main(){
  myQueueC<pair<string,int>> mqc;
  int n,q,n2,time = 0,m = 0 ;
  string s;
  pair<string,int> psi;
  vector<pair<string,int>> vsi;
  cin >> n >> q ;
  for(int i = 0; i < n; ++i){
    cin >> s >> n2 ;
    mqc.push(make_pair(s,n2)) ;
  }
  while(!mqc.empty()){
    psi = mqc.front() ;
    n2 = psi.se - q ;
    if(n2 <= 0){
      time += psi.se ;
      vsi.push_back(make_pair(psi.fi,time)) ;
    }
    else{
      time += q ;
      psi.se = n2 ;
      mqc.push(psi) ;
    }
    mqc.pop() ;
  }
  for(auto n3: vsi){
    cout << n3.fi << " " << n3.se << endl;
  }

  return 0 ;
}

