  cin >>n >> q;
  first = 0;
  last = n-1;
  for(int i=0; i<n; i++){
    cin >> queue[i].name >> queue[i].time;
  }
  point = first;
  now_time = 0;
  while(flag_first_last&&(first <= last) || !flag_first_last&&(first >= last) ){
    if(queue[point].time > q){
      now_time+=q;
      queue[point].time -= q;
      last++;
      if(last >= 100000){
        last = 0;
        flag_first_last = !flag_first_last;
      }
      queue[last].name = queue[point].name;
      queue[last].time = queue[point].time;
    }else{
      now_time+=queue[point].time;
      cout << queue[point].name << " " << now_time << endl;
    }
    first++;
    if(first >= 100000){
      first = 0;
      flag_first_last = !flag_first_last;
    }
    point++;
    if(point >= 100000){
      point = 0;
    }
  }
  return 0;
