using namespace std;

template <typename T>
class MyQueue
{
private:
    const static size_t kMax = 1000000;
    T buff_[kMax]{};
    int top_;
    int size_;

    // 空き位置を返す
    int getSpacePos(void)
    {
        if (size_ == kMax) {
            return -1;
        }

        int pos = top_ + size_;

        if (pos >= kMax) {
            pos = kMax - pos;
        }
        return pos;
    }


public:
    MyQueue(void) :
        top_(0),
        size_(0)
    {};

    void enque(const T& item) {
        if (size_ == kMax) {
            return;
        }
        int pos = getSpacePos();

        buff_[pos] = item;
        size_++;
        return;
    }

    T deque(void) {
        if (size_ == 0) {
            return T();
        }
        T item = buff_[top_];
        size_--;
        top_++;
        if (top_ == kMax) { top_ = 0; }
        return item;
    }

    bool isEmpty(void) {
        return (size_ == 0) ? true : false;
    }
};

typedef struct _Scheduler
{
    char name_[14];
    unsigned short time_;
}Scheduler;


int main(void)
{
    static MyQueue<Scheduler> roundRobin;
    string str;

    int procNum = 0;
    unsigned short qtime = 0;

    std::cin >> procNum >> qtime;

    for (int i = 0; i < procNum; i++) {
        Scheduler sch;
        std::cin >> sch.name_ >> sch.time_;
        roundRobin.enque(sch);
    }

    unsigned int allTime = 0;

    while (!roundRobin.isEmpty()) {
        Scheduler sch = roundRobin.deque();

        unsigned short workTime = qtime;

        if (sch.time_ <= qtime) {
            workTime = sch.time_;
            std::cout << sch.name_ << ' ' << allTime + workTime << "\n";
        } else {
            sch.time_ = sch.time_ - qtime;
            roundRobin.enque(sch);
        }

        // 積算時間加算
        allTime += workTime;

    }

    return 0;
}

