// Ring-buffer based queue. Enqueue and dequeue run in O(1).
template <int N>
class Queue {
 public:
  // Note: leave one element empty so that we can distinguish
  // that the ring buffer is empty or full.
  Queue() : size_(N + 1), head_(0), tail_(0) {}

  void Enqueue(Process p) {
    assert(!IsFull());
    data_[tail_] = p;
    tail_ = next(tail_);
  }

  Process Dequeue() {
    assert(!Empty());
    auto p = data_[head_];
    head_ = next(head_);
    return p;
  }

  bool IsFull() const { return head_ == next(tail_); }

  bool Empty() const { return head_ == tail_; }

 private:
  int next(int a) const { return (a + 1) % size_; }

  Process data_[N + 1];
  const int size_;
  int head_;
  int tail_;
};

}  // namespace

int main() {
  int n;
  int q;
  cin >> n >> q;

  Queue<100000> queue;
  for (int i = 0; i < n; ++i) {
    Process p;
    scanf("%s %d", p.name, &p.time);
    queue.Enqueue(p);
  }

  int current_time = 0;
  while (!queue.Empty()) {
    auto p = queue.Dequeue();
    const int used = min(p.time, q);
    p.time -= used;
    current_time += used;

    if (p.time <= 0) {
      printf("%s %d\n", p.name, current_time);
      continue;
    }
    queue.Enqueue(p);
  }
  return 0;
}

