struct queue{
  std::unique_ptr<T[]> c;
  size_t head;
  size_t tail;
  const size_t max;
public:
  queue(size_t n):c(new T[n]),head(0),tail(0),max(n){}
  bool empty(){return head == tail;}
  void push(T& v){
    c[tail++] = v;
    if(tail == max) tail = 0;
  }
  T&& pop(){
    auto r = c[head++];
    if(head == max) head = 0;
    return std::move(r);
  }
};

