using namespace std;

struct Task
{
	Task() {}
	Task(string& name, int time) : name(name), time(time) {}

	string name;
	int time;
};

class Queue
{
private:
	struct Data
	{
		Task data;
		Data* pNext;
		Data* pPrev;
	};

public:
	Queue()
	{
		m_size = 0;
		m_pHead = new Data();
		m_pHead->pPrev = 0;
		m_pTail = new Data();
		m_pTail->pNext = 0;

		m_pHead->pNext = m_pTail;
		m_pTail->pPrev = m_pHead;
	}

	~Queue()
	{
		Data* pCurrent = m_pHead;
		while (pCurrent)
		{
			Data* pTemp = pCurrent;
			pCurrent = pCurrent->pNext;
			delete pTemp;
		}
		m_pHead = 0;
		m_pTail = 0;
	}

	void Push(const Task& value)
	{
		Data* pTemp = new Data();
		pTemp->data = value;

		m_pTail->pPrev->pNext = pTemp;
		pTemp->pPrev = m_pTail->pPrev;
		pTemp->pNext = m_pTail;
		m_pTail->pPrev = pTemp;

		++m_size;
	}

	void Pop()
	{
		if (!m_pHead || !m_pHead->pNext) return;

		Data* pTop = m_pHead->pNext;
		Data* pNext = pTop->pNext;
		delete pTop;
		m_pHead->pNext = pNext;
		pNext->pPrev = m_pHead;

		--m_size;
	}

	Task& Top()
	{
		return m_pHead->pNext->data;
	}

	bool IsEmpty()
	{
		return m_size == 0;
	}

private:
	Data* m_pHead;
	Data* m_pTail;
	int m_size;
};

int main()
{
	Queue tasks;

	int n, q;
	cin >> n >> q;
	string name;
	int time;
	for (int i = 0; i < n; ++i)
	{
		cin >> name;
		cin >> time;
		tasks.Push(Task(name, time));
	}

	int overtime = 0;
	while (!tasks.IsEmpty())
	{
		if (tasks.Top().time <= q)//执行时间小于等于规定时间
		{
			overtime += tasks.Top().time;
			cout << tasks.Top().name << " " << overtime << endl;
			tasks.Pop();
		}
		else
		{
			overtime += q;
			tasks.Top().time -= q;
			Task t = tasks.Top();
			tasks.Pop();
			tasks.Push(t);
		}
	}

	return 0;
}

