class RR
{
private:
    queue<pair<string, int>> process;
    queue<pair<string, int>> done_process;

public:
    void push(string name, int time); //引数からpairを作ってprocessにpushする関数。mainから呼び出す。
    void execute(int quantum);        //ラウンドロビンスケジューリングの処理を行う関数
    pair<string, int> answer(void);
};

void RR::execute(int quantum)
{
    int total = 0;
    while (!process.empty())
    {
        if (process.front().second <= quantum)
        {
            total += process.front().second;
            done_process.push(make_pair(process.front().first, total));
        }
        else
        {
            int undone_time = process.front().second - quantum;
            push(process.front().first, undone_time);
            total += quantum;
        }
        process.pop();
    }
}

void RR::push(string name, int time)
{
    process.push(make_pair(name, time));
}

pair<string, int> RR::answer()
{
    pair<string, int> temp;
    temp = done_process.front();
    done_process.pop();

    return temp;
}

