vector<struct wait_que> completeProcess(struct wait_que *wqs, int size,  int q) {
	vector<struct wait_que> rtn_vec;
	int total_time = 0;
	int cnt = 0;
	while (cnt < size) {
		// check the first element.
		struct wait_que tmp = wqs[0];

		for (int i = 1; i < size - cnt ; i++) {
			wqs[i - 1] = wqs[i];
		}

		if (tmp.time - q > 0) {
			tmp.time -= q;
			wqs[size - cnt - 1] = tmp;
			total_time += q;
		} else {
			total_time += tmp.time;
			tmp.time = total_time;
			rtn_vec.push_back(tmp);
			cnt++;
		}
	}
	return rtn_vec;
}

