class Proc{
public:
    Proc *prev;
    Proc *next;
    string name;
    int remaining_time;
    Proc(char* n, int t) {
        prev = NULL;
        next = NULL;
        name = n;
        remaining_time = t;
    };
    int subtract_time(int t) {
        remaining_time -= t;
        return remaining_time;
    };
};

class Queue{
    Proc *head;
    Proc *tail;
public:
    Queue(){head = NULL; tail = NULL;};
    void enqueue(Proc* Proc) {
        if(head != NULL) {  // if Queue is not empty
            tail->next = Proc;
            Proc->prev = tail;
        } else {
            head = Proc;
        }
        tail = Proc;
    };
    Proc *dequeue(void) {
        Proc *ret = head;
        if(head != NULL) {
            head = head->next;
            if(head != NULL) head->prev = NULL;
            ret->prev = NULL;
            ret->next = NULL;
        }
        return ret;
    };
};


int main(void) {
    int n, q;

    char name[10];
    int remaining_time;

    int i;

    scanf("%d %d", &n, &q);

    Queue *queue = new Queue();
    for(i = 0; i < n; i++){
        scanf("%s %d", name, &remaining_time);
        Proc *p = new Proc(name, remaining_time);
        queue->enqueue(p);
    }

    int count = 0;
    while(true) {
        Proc *p = queue->dequeue();
        if(p == NULL) break;
        if(p->remaining_time > q) {
            p->subtract_time(q);
            queue->enqueue(p);
            count += q;
        } else {
            count += p->remaining_time;
            printf("%s %d\n", p->name.c_str(), count);
            delete p;
        }
    }
    return 0;
}

