bool queue_dequeue(process_t &process)
{
  if (head == tail) return false;
  process = processes[head];
  head++;
  head %= ARRAY_SIZE;
  return true;
}

void queue_enqueue(process_t process)
{
  processes[tail] = process;
  tail++;
  tail %= ARRAY_SIZE;
}

