typedef struct node
{
	int a;
	char b[200000];
	struct node *prev,*next;	
}node;

node *head=NULL, *tail=NULL;

node *newNode(int a,char *b)
{
	node *tmp = (node *)malloc(sizeof(node));
	tmp->prev=NULL;
	tmp->next=NULL;
	tmp->a=a;
	strcpy(tmp->b,b);

	return tmp;
}

void push(int a, char *b)
{
	node *poi = newNode(a,b);
	if(head==NULL && tail==NULL)
	{
		head=tail=poi;
		return;
	}
	tail->next=poi;
	poi->prev=tail;
	tail=poi;
	tail->next=NULL;
}

void pop()
{
	if(head==NULL && tail==NULL)
	return;

	if(head==tail)
	{
		free(head);
		head=tail=NULL;
		return;
	}

	head=head->next;
	free(head->prev);
