	void initialize();
	process front();
	void pop();
	void push(process p);
	bool empty();

};
void queue::initialize() {
	head = 0;
	tail = 0;
}
process queue::front() {
	return q[head];
}
void queue::pop() {
	if(head >= MAX) {
		head = 0;
	} else {
		head++;
	}
}
void queue::push(process p) {
	q[tail] = p;
	if(tail >= MAX) {
		tail = 0;
	} else {
		tail++;
	}
}
bool queue::empty() {
	if (head == tail) {
		return true;
	}
	return false;
}


