	int t;
} P;

class Queue
{
private:
	P Q[LEN + 1];
	int head, tail, n;

public:
	Queue()
	: head(0)
	, tail(0)
	, n(0) {}

	void enqueue(P x) {
		Q[tail++] = x;
		if(sizeof(Q) / sizeof(Q[0]) == tail) {
			tail = 0;
		}
		if(sizeof(Q)/sizeof(Q[0]) > n) {
			n++;
		}
		else{
			head = head < sizeof(Q) / sizeof(Q[0]) - 1 ? head + 1 : 0;
		}
	}

	P dequeue() {
		P front = {"", 0};
		if(0 < n) {
			n--;
			front = Q[head++];
			if(sizeof(Q) / sizeof(Q[0]) == head) {
				head = 0;
			}
		}
		return front;
	}

	bool isEmpty() {
		return 0 == n;
	}
};

