#define SIZE (20000)

typedef struct{
    char name[20];
    int time;
}Process;


typedef struct{
    int start_p;
    int end_p;
    Process *q;
}Queue;


Process* pop(Queue *que){

    if(que->start_p == que->end_p) return NULL;

    if(que->start_p + 1 >= SIZE){
        que->start_p = 0;
    }
    return &(que->q[que->start_p++]);

}

void push(Queue *que, Process *p){

    if(que->end_p + 1 >= SIZE){
        que->end_p = 0;
    }
    que->q[que->end_p] = *p;
    que->end_p = (que->end_p + 1) % SIZE;
}



