template<typename T>
class queue {
private:
	static const int MAX_N = 200000;
	T Q[MAX_N];
	int head, tail;
public:
	void initialize() {
		head = tail = 0;
	}
	queue() {
		initialize();
	}
	bool isEmpty() {
		return head == tail;
	}
	bool isFull() {
		return head == (tail + 1) % MAX_N;
	}
	void enqueue(T x) {
		if (isFull()) {
			printf("Queue is full: (head, tail) = (%d, %d)\n", head, tail);
			return;
		}
		Q[tail] = x;
		tail = (tail + 1) % MAX_N;
	}
	T dequeue() {
		if (isEmpty()) {
			printf("Queue is empty: (head, tail) = (%d, %d)\n", head, tail);
			return Q[head];
		}
		T ret = Q[head];
		head = (head + 1) % MAX_N;
		return ret;
	}
};

