template <class T>
class Queue
{
private:
    static const int LEN = 100005;
    T a[100005];
    int head, tail;

public:
    Queue(): head(0), tail(0) {};

    const bool empty() const {
        return( head == tail );
    }

    void enque(const T &x){
        a[ tail ] = x;
        tail = (tail+1) % LEN;
    }

    const T& front() const {
        return( a[head] );
    }

    const T& deque() {
        const T &ret = a[head];
        return( head = (head+1) % LEN, ret );
    }
};

