};

class Queue {
public:
    Process* data;
    int head = 0;
    int tail;
    int max;

    Queue(int max) : tail(max), max(max) {
        data = new Process[max];
    }

    void enqueue(Process p) {
        data[tail] = p;

        if (tail + 1 >= max) {
            tail = 0;
        } else {
            tail++;
        }
    }

    Process dequeue() {
        Process p = data[head];

        if (head + 1 >= max) {
            head = 0;
        } else {
            head++;
        }

        return p;
    }
};

int main() {
    int n;
