        scanf("%d", &time);

        strcpy(p.name, name);
        p.time = time;

        queue.enqueue(p);
    }

    while (queue.head != queue.tail) {
        if (queue.data[queue.head].time > q) {
            t += q;
            queue.data[queue.head].time -= q;
            Process p = queue.dequeue();
            queue.enqueue(p);
