void roundRobinScheduling(int q, queue<string> name, queue<int> time){
	int timeSpend = 0;
	while (name.size() > 0) {
		if (q - time.front() >= 0) {
			timeSpend += time.front();
			cout << name.front() << " " << timeSpend << endl;
		} else {
			name.push(name.front());
			time.push(time.front() - q);
			timeSpend += q;
		}
		name.pop();
		time.pop();
	}
}

