	Queue(int n);
	void enqueue(P p);
	void dequeue();
	bool isEmpty();
	P get();
	void clear();
};

Queue::Queue(int n)
{
	size = n;
	queue = new P[n];
}

void Queue::enqueue(P p)
{
	queue[tail] = p;
	tail = (tail + 1) % size;
}

void Queue::dequeue()
{
	head = (head + 1) % size;
}

bool Queue::isEmpty()
{
	return head == tail;
}

P Queue::get()
{
	return queue[head];
}

void Queue::clear()
{
	delete[] queue;
}

