Process Q[SIZE];

class Queue
{
	int putloc;
	int getloc;
public:	
	Queue() { putloc = getloc = 0; }
	bool isEnpty();
	void push(Process p);
	Process pop();
};

void Queue::push(Process p)
{
	if (putloc + 1 == getloc || (putloc == (SIZE - 1) && getloc == 0)) exit(1);
	putloc++;
	if (putloc == SIZE) putloc = 0;
	Q[putloc] = p;
}

Process Queue::pop()
{
	getloc++;
	if (getloc == SIZE) getloc = 0;
	return Q[getloc];
}

bool Queue::isEnpty()
{
	return getloc == putloc;
}

