#define MAX 10001
using namespace std;

class Queue{
    pair<string, int> q[MAX];
    int head = 0;
    int tail = MAX - 1;
public:
    bool is_empty(){
        int diff = tail - head;
        if (diff == -1 || diff == MAX) return true;
        return false;
    }
    void enqueue(pair<string, int> num){
        tail = (tail + 1) % MAX;
        q[tail] = num;
    }
    pair<string, int> dequeue(){
        pair<string, int> ret = q[head];
        head = (head + 1) % MAX;
        return ret;
    }
};

int main(){
    int n, q;
    cin >> n >> q;
    Queue que1;
    for (int i = 0; i < n; i++) {
        string p;
        int num;
        cin >> p >> num;
        que1.enqueue(make_pair(p, num));
    }
    Queue que2;
    int time_ = 0;
    while(!que1.is_empty()) {
        pair<string, int> front = que1.dequeue();
        if (front.second <= q) {
            time_ += front.second;
            front.second = time_;
            que2.enqueue(front);
        } else {
            front.second -= q;
            time_ += q;
            que1.enqueue(front);
        }
    }
    while (!que2.is_empty()) {
        pair<string, int> front = que2.dequeue();
        cout << front.first << " " << front.second << endl;
    }
    return 0;
}

