// Queue キューの実装
// 配列を%剰余でリングバッファーとして使う。
// enqueue,dequeueともにO(1)で処理できる。

const int MAX = 100000;

typedef struct Process {
    string name;
    int time;
} Process;

class Queue
{
public:
    Queue() : head(0), tail(0), Q()
    {
    }
    void enqueue(Process x)
    {
        if (isFull())
        {
            cerr << "overflow" << endl;
            return;
        }
        Q[tail] = x;
        // MAXが100の場合、
        // tail=99なら、Q[99]で最後の要素を指している。そのためQ[99+1]は、エラーとなる。
        // エラーにしないため、99+1がMAXなら、tailを0にする。
        if (tail + 1 == MAX)
            tail = 0;
        else
            tail++;
    }
    // 先頭からデータを取り出す。
    Process dequeue()
    {
        if (isEmpty())
        {
            cerr << "underflow" << endl;
            Process x;
            return x;
        }
        Process x = Q[head];
        if (head + 1 == MAX)
            head = 0;
        else
            head++;
        return x;
    }
    bool isEmpty()
    {
        return head == tail;
    }
    bool isFull()
    {
        return head == (tail + 1) % MAX;
    }


private:
    Process Q[MAX];
    int head;
    // 最後の要素の１つ後ろを指す。新しい要素が追加される場所
    int tail;
};


