const int MAX_N=100000;

struct Process{
	string name;
	int time;
};

struct Queue{
	Process p[MAX_N];
	int f=0,b=0;

	void emplace(Process x){
		p[b++]=x;
		b%=MAX_N;
	}

	Process front(){
		if(empty()) abort();
		return p[f];
	}

	void pop(){
		if(empty()) abort();
		p[f++]=Process();
		f%=MAX_N;
	}

	bool empty(){
		return f==b;
	}
};

