}Process;

class ProcessQueue{
	public:
		ProcessQueue(int size){
			m_size = size;
			m_process = new Process[m_size];
			m_head = 0;
			m_tail = 0;
			number = 0;
		}
		~ProcessQueue() {
			delete m_process;
		}
		void enQueue(Process process){
			number++;
			if (m_tail < m_size-1) {
				m_process[m_tail++] = process;
			} else {
				m_process[m_size-1] = process;
				m_tail = 0;
			}
		}
		Process deQueue() {
			number--;
			if (m_head < m_size-1) {
				return m_process[m_head++];
			} else {
				m_head=0;
				return m_process[m_size-1];
			}
		}
		int getNumber () {
			return number;
		}
	private:
		int m_size;
		int number;
		int m_head;
		int m_tail;
		Process* m_process;
};
