    for(int i=0; i<num; i++){
        string str;
        cin >> str;
        for(int j=0; j<str.size(); j++){
            name[i][j] = str[j];
        }
        cin >> t;
        q_name.enqueue(i);
        q_time.enqueue(t);
    }

    calc(q_name, name, q_time, quantum);

    return 0;
}

