  rep(i, N) q.push(process[i]);

  while (q.size() != 0) {
    P tmp = q.front();
    q.pop();

    if (tmp.second - u > 0) {
      tmp.second -= u;
      now += u;
      q.push(tmp);
    }
    else if (tmp.second - u <= 0) {
      now += tmp.second;
      answers.push_back(P(tmp.first, now));
    }
  }

  rep(i, N) cout << answers[i].first << " " << answers[i].second << endl;
  return 0;
}

void vprint(vector<P> x) {
  rep(i, x.size()) {
    cout << x[i].first << " " << x[i].second << " || ";
  }
  cout << endl;
}

#include <bits/stdc++.h>
