struct Process {
    string name;
    int time;
};

class Queue {
  private:
    Process queue[MAX];
    int head;
    int tail;

  public:
    Queue() {
        head = 0;
        tail = 0;
    }

    void enqueue(Process p) {
        queue[tail] = p;
        if (tail + 1 == MAX)
            tail = 0;
        else
            tail++;
    }

    Process dequeue() {
        Process x = queue[head];
        if (head + 1 == MAX)
            head = 0;
        else
            head++;
        return x;
    }

    bool is_empty() {
        return tail == head;
    }
};

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    Queue *queue = new Queue();
    int n, time;
    cin >> n >> time;
    for (int i = 0; i < n; i++) {
        string name;
        int rest;
        cin >> name >> rest;
        Process p = Process();
        p.name = name;
        p.time = rest;
        queue->enqueue(p);
    }

    int elaps = 0;
    int diff = 0;
    while (!queue->is_empty()) {
        Process proc = queue->dequeue();
        diff = min(time, proc.time);
        proc.time -= diff;
        elaps += diff;
        if (proc.time > 0)
            queue->enqueue(proc);
        else
            cout << proc.name << " " << elaps << endl;
    }

    delete queue;
}

