Item Queueget (void) {
    Item item = head->item;
    link t = head->next;
    free(head);
    head = t;
    return item;
}
link NEW(Item item, link next) {
    link x = malloc(sizeof * x);
    x->item = item;
    x->next = next;
    return x;
}
void Queueput (Item item) {
    if (head == NULL) {
        head = (tail = NEW(item, head));
        return;
    }
    tail->next = NEW(item, tail->next);
    tail = tail->next;
}

