// define the structure
typedef struct Process {
  char name[10];
  int time;
} Processor;

int main() {
  int i, n, q;
  int cnt = 0;
  int qhead = 0, qtail;
  Processor pr[N];

  // input each process
  scanf("%d %d", &n, &q);
  for(i = 0; i < n; i++) {
    if(scanf("%s %d", pr[i].name, &pr[i].time) == EOF) break;
  }

  qtail = i;
  // simulate
  while(1) {
    if (pr[qhead].time <= q) {
      // complete the process
      cnt += pr[qhead].time;
      printf("%s %d\n", pr[qhead].name, cnt);
      // dequeue
      qhead++;
    }
    else {
      pr[qhead].time -= q;
      cnt += q;   
      // engueue
      pr[qtail++] = pr[qhead];
      // dequeue
      qhead++;
    }
    // all complete
    if(qhead == qtail) break;
  }

  return 0;
}

#include <stdio.h>

#define MAX 100

void push(int);
long pop();

int S[MAX];
int top=0;

int main()
{
  int c;
  long x, a, b;

  while ((c=getchar())!=EOF){
    if (isdigit(c)){
      ungetc(c, stdin);
      scanf("%d", &x);
      push(x);
    }
    else {
      switch(c) {
      case '+':
	b=pop();
	a=pop();
	push(a+b);
	break;
      case '-':
	b=pop();
	a=pop();
	push(a-b);
	break;
      case '*':
	b=pop();
	a=pop();
	push(a*b);
	break;
      case '\n':
	if (top==1){
	  printf("%d\n", pop());
	}
	else {
	  printf("Invalid expression.\n");
	  top=0;
	}
      case ' ':
	break;
      default:
	printf("Invalid input.\n");
	top=0;
	break;
      }
    }
  }
return 0;
}

void push(int x)
{
        if ( top >= MAX){
                fprintf(stderr, "stack overflow\n");
                top=0;
        }
        top++;
        S[top]=x;
}
long pop()
{
	top--;
	return S[top+1];

}

