#define N 1000000

struct queue {
	int data[N];
	char name[N][11];
	int head;
	int tail;
	int max;
};

void initialize( struct queue *q, int max ) {
	int i = 0;
	int j = 0;

	q -> head = 0;
	q -> tail = 0;
	q -> max = max;
	for( i = 0; i < max; i++ ) {
		q -> data[i] = 0;
		for ( j = 0; j < 11; j++ ) {
			q -> name[i][j] = '\0';
		}
	}
}

void enqueue( struct queue *q, int item, char* name ) {
	int i = 0;

	if ( q -> tail >= q -> max ) {
		q -> tail = 0;
	}

	q -> data [ q -> tail ] = item;
	for ( i = 0; name[i] != '\0'; i++ ) {
		q -> name [ q -> tail ][i] = name[i];
	}
	q -> name[ q -> tail ][i] = '\0';
	q -> tail++;

}

int dequeue( struct queue *q , char* name ) {
	int tmp = 0;
	int i = 0;

	if ( q -> head >= q -> max ) {
		q -> head = 0;
	}


		tmp = q -> data[ q -> head ];
		for ( i = 0; q -> name [ q -> head ][i] != '\0'; i++ ) {
			name[i] = q -> name [ q -> head ][i];
		}
		name[i] = '\0';
		q -> head++;
		return tmp;
}

