	scanf("%d", &n);
	scanf("%d", &qtm);
	for (i = 0; i < n; i++) {
		struct q *a = (struct q *)malloc(sizeof(struct q));
		if (a == NULL)
			return 1;
		scanf("%s", a->name);
		scanf("%d", &a->time);
		a->next = NULL;
