  for(i=0;i<n;i++){
    scanf("%s%d",pro[i].name,&pro[i].time);
  }

  while(1){                            /* enqueue: This while loop enqueue pro[i] when pro[i].time is not less thanzero.*/
    for(i=0;i<n;i++){
      pro[i].time=pro[i].time-q;
      if(pro[i].time<=0){
        counter=counter+(pro[i].time+q);
        printf("%s %d\n",pro[i].name,counter);
        for(j=i;j<n-1;j++){
          pro[j]=pro[j+1]; /* overwrite */
        }
        n--;                        /* dequeue: this and upper overwite */
        i--;
      } else counter=counter+q;
    }
    if(n==0)break;                /* This if sentens break while loop when queue is empty.*/
  }
  return 0;
}

