struct node{
	char name[11];
	int time;
	struct node *next;
	struct node *prev;
};

typedef struct node *NodePointer;

NodePointer nil;

void init(){
	nil = malloc(sizeof(struct node));
	nil->next = nil;
	nil->prev = nil;
}

void deleteNode(NodePointer t){
	t->prev->next = t->next;
	t->next->prev = t->prev;
	free(t);
}

void backInsert(char name[],int time){
	NodePointer x;
	x = malloc(sizeof(struct node));
	strcpy(x->name,name);
	x->time = time;
	x->next = nil;
	x->prev = nil->prev;
	x->prev->next = x;
	nil->prev = x;
}

void deleteFirst(){
	NodePointer t = nil->next;
	if(t == nil){
		return;
	}
	deleteNode(t);
}

