{
	NODE *tmp = (NODE *)malloc(sizeof(NODE));
	memcpy(tmp->name, name, sizeof(tmp->name));
	tmp->time = time;
	tmp->next = NULL;

	if (front == NULL) {
		front = rear = tmp;
	}
	else {
		rear->next = tmp;
		rear = tmp;
	}
}

int dequeue(NODE *node)
{
	if (front != NULL) {
		memcpy(node, front, sizeof(NODE));
		free(front);
		front = node->next;
		return 1;
	}
	else {
		return 0;
	}
}

