#define QUESIZE 1001

typedef struct{
	char name[10];
	int time;
} process;

void que_enqueue(process);
process que_dequeue(void);
int que_size(void);
int que_free(void);
int que_empty(void);
void que_clear(void);

process que[QUESIZE];
int head=0, tail=0;

void que_enqueue(process n)
{
  tail=(tail+1)%QUESIZE;
  que[tail]=n;
}

process que_dequeue(void)
{
  head=(head+1)%QUESIZE;
  return que[head];
}

int que_size(void)
{
  if(head < tail) return tail-head;
  else return tail-head+QUESIZE;
}

int que_free(void)
{
  return QUESIZE-1-que_size();
}

int que_empty(void)
{
  return head==tail;
}

void que_clear(void)
{
  head = tail = 0;
}

