  for(;c != '\n';){
    c = getchar();

    if(c >= '1' && c <= '9'){
      push(dtoi(c));
    }

    if(c == '+'){
     push(pop() + pop());
    }
   else if(c == '-'){
     push(pop() - pop());
    }
