    }
  while (qsize > 0)
    totalTime = runProcess(q, totalTime);
  return 0;
}

void printProcess(process input)
{
  printf("%s %d\n", input.name, input.time);
}

void removeProcess()
{
  previous->next = current->next;
  free(current);
  current = previous->next;
  qsize--;
}

int runProcess(int q, int totalTime)
{
  if (current->value.time <= q)
    {
      totalTime += current->value.time;
      printf("%s %d\n", current->value.name, totalTime);
      removeProcess();
    }
  else
    {
      totalTime += q;
      current->value.time -= q;
      previous = current;
      current = current->next;
    }
  return totalTime;
}

