	while(scanf("%s %d", (name_buff[data_num]), &(time_buff[data_num])) != EOF)
	{
		data_num++;
	}

	/* get Data Num equal process num */
	if( data_num == pn )
	{
		while(pn > 0)
		{
			/* remain process time */
			if(time_buff[bp] > 0)
			{
				if( time_buff[bp] > pt )
				{
					time_buff[bp] -= pt;
				}
				else
				{
					printf("%s %d\n", name_buff[bp], time_buff[bp]); /* output finished process */
					time_buff[bp] = 0;
					pn--;
				}
			}
			else
			{
				/* Already Finish */
			}

			bp++;
		}
	}
	else
	{
		/* error input */
	}

	return 0;
}

