typedef struct pp{
    char name[100];
    int t;
}P;

P Q[LEN+1];
int head = 0, tail, n, empty = 0;

void push(P x){
    empty++;
    Q[tail] = x;
    if(tail+1 == LEN) tail = 0;
    else tail++;
}

P pop(){
    P res;
    empty--;
    res = Q[head];
    if(head+1 == LEN) head = 0;
    else head++;
    return res;
}


int main(){
    int time = 0, count = 0;
