int sort(int *A,int n){
  int i,j,min,ans=0,t;

  for(i=0;i<n-1;i++){
    min=i;
    for(j=i;j<n;j++){
      if(A[j]<A[min])min=j;
    }
    t=A[i];
    A[i]=A[min];
    A[min]=t;
    if(i!=min)ans++;
  }
  return ans;
}

