	quantum		= atoi(&str[i+1]);


	fgets( str, 256, stdin );

	for ( j = 0; j < max_order; j++ ) {
		for ( i = 0; str[i] != ' '; i++ ) {
			p[j][i] = str[i];
		}
		p[j][i] = '\0';
