	total_time = 0;
	j = 0;
	i = 0;


	while ( flag < max_order ) {
		if ( time[i] == 0 ) {
			i++;
			if ( i >= max_order ) {
			    i = 0;
			}
			continue;
		}

		if ( time[i] <= quantum ) {
			total_time += time[i];
			result[0][j]	= i;
