  }

  return 0;
}

void Initialize(int *head,int *tail,int i){
  *head = 0;
  *tail = i;
}

int IsEmpty(int head,int tail){
  if (head == tail)
    return 1;

  return 0;
}

int IsFull(int head,int tail){
  if (head == (tail + 1) % LEN)
    return 1;

  return 0;
}

void Enqueue(P Q[],int *head,int *tail,P x){
  if (IsFull(*head,*tail)){
    fprintf(stderr,"Over flow\n");
    exit(1);
  }

  Q[*tail] = x;

  if (*tail + 1 == LEN)
    *tail = 0;

  else
    (*tail)++;
}

P Dequeue(P Q[],int *head,int *tail){
  P x;

  if (IsEmpty(*head,*tail)){
    fprintf(stderr,"Under flow\n");
    exit(2);
  }

  x = Q[*head];

  if (*head + 1 == LEN)
    *head = 0;

  else
    (*head)++;

  return x;
}

