		s = &strings[ix];
		strcpy(s, name);
		ix += strlen(name) + 1;

		que.name = s;
		que.time = t;
		que_push(&que);
	}

	time = 0;
	while (que_size() > 0)
	{
		que_front(&que); que_pop();
		if (que.time <= q)
		{
			time += que.time;
			printf("%s %d\n", que.name, time);
		}
		else
		{
			que.time -= q;
			time += q;
			que_push(&que);
		}
	}

	return 0;
}

