#define failure 0


typedef struct{
  int size;
  int head;
  int tail;
  data *data;
}queue;

queue *make_queue(int queue_size){
  queue *p;
  p=malloc(sizeof(queue));
  p->data=malloc((queue_size+1)*sizeof(data));
  p->size=queue_size;
  p->head=0;
  p->tail=0;
  return p;
}

int enque(queue *Q,data x){
  if((Q->tail+1)%(Q->size +1) ==Q->head) return failure;
  else{
    Q->data[Q->tail]=x;
    Q->tail=(Q->tail+1)%(Q->size +1);
    return success;
  }
}

int deque(queue *Q,data *x){
  if(Q->head==Q->tail) return failure;
  else{
    *x=Q->data[Q->head];
    Q->head=(Q->head+1)%(Q->size+1);
    return success;
  }
}




