  scanf("%d%d", &n, &q);
  for(int i = 0; i < n; ++i){
    scanf("%s%d", name, &time);
    push_back(&head, &tail, time, name);
  }
  //print_list(head);

  Node tmp;
  int t = 0;
  while(!is_empty(head)){
    tmp = pop_front(&head);
    if(tmp.data <= q){
      t += tmp.data;
      printf("%s %d\n", tmp.name, t);
    }
    else{
      tmp.data -= q;
      push_back(&head, &tail, tmp.data, tmp.name);
      t += q;
    }
  }



  clear_list(head) ;
  return 0 ;
}

