        scanf("%s %d ", process.name, &(process.timeInfo));
        enqueue(&queue, process);
    }

    // -------------------------------------------------------------------------

    // initalizeProcessQueue
    ProcessQueue completeProcess;
    initalizeProcessQueue(&completeProcess, nProcesses + 1);

    // do the magic
    for (;;) {
//        printf("timestamp: %d\n", timestamp);
//        printProcessQueue(queue);

        dequeue(&process, &queue);

        if (process.timeInfo > quantum) {
            timestamp += quantum;

            // throw to the end of queue
            process.timeInfo -= quantum;
            enqueue(&queue, process);
        }
        else {
            timestamp += process.timeInfo;

            // completing timestamp: current time
            process.timeInfo = timestamp; 
            enqueue(&completeProcess, process);
            if (isEmpty(queue))
                break;
        }

    }
    printProcessQueueNewline(completeProcess);

    return (EXIT_SUCCESS);
}

