  queue.head = 0;
  queue.tail = 0;
  for(i = 0; i < n; i++){
    queue.data[i].name[0] = ' ';
  }

  for(i = 0; i < n; i++){
    scanf("%s%s", name, time);
    in(&n, &queue, &name[0], atoi(time));
  }

  for(tmp = out(&n, &queue); tmp.name[0] != ' '; tmp = out(&n, &queue)){

    if(tmp.time - q > 0){
      in(&n, &queue, &tmp.name[0], tmp.time - q);
      time_sum += q;
    }
    else {
      time_sum += tmp.time;
      printf("%s %d\n", tmp.name, time_sum);
    }    

  }

  return 0;
}

void in(int *n, Pro *queue, char *name, int time){

  strcpy(queue->data[queue->tail].name, name);
  queue->data[queue->tail].time = time;

  if(queue->tail < *n - 1) queue->tail++;
  else queue->tail = 0;

}

Data out(int *n, Pro *queue){

  Data tmp;

  tmp = queue->data[queue->head];
  queue->data[queue->head].name[0] = ' ';

  if(queue->head < *n - 1) queue->head++;
  else queue->head = 0;

  return tmp;
}

