void BubbleSort(int n,que B[]){
	int i,j;
	que tmp;
	for(i=0;i<n-1;i++){
		for(j=n-1;j>i;j--){	
			if(B[j].num < B[j-1].num){
				tmp = B[j-1];
				B[j-1] = B[j];
				B[j] = tmp;
			}
		}
	}	
}

