int main(void){
	int n;	// number of processes
	int q;	// quantum
	int i;
	int passed_time=0;
	char tmp1[11];
	int tmp2;
	int finished_processes=0;
	process* processes;

	scanf("%d %d", &n, &q);

	processes = (process*)malloc(sizeof(process) * n);

	for(i=0; i<n; i++){
		scanf("%s %d", tmp1, &tmp2);
		strcpy(processes[i].name, tmp1);
		processes[i].remain_time = tmp2;
		processes[i].finished = 0;
	}

