void InitQueue(queue *q, int ps){
    q->front = 0;
    q->rear = 0;
    q->queue_size = ps;
    return;
}

void Putq(queue *q, process_t p){
    q->elements[q->rear] = p;
    if(q->rear == q->queue_size){
        q->rear = 0;
    } else{
        q->rear += 1;
    }
    return;
}

process_t Getq(queue *q){
    process_t p;
    p = q->elements[q->front];
    if(q->front == q->queue_size){
        q->front = 0;
    } else{
        q->front += 1;
    }
return p;
}

int QueueEmpty(queue *q){
return (q->front == q->rear);
}

