//プロセスを表す構造体
typedef struct pp{
    char name[100];
    int t;
} P;//Pという名前で扱う(C++でいうクラス定義みたいなもの)

P Q[LEN];
int head, tail, n;

void enqueue(P x){//要素の追加
    Q[tail] = x;
    tail = (tail + 1)%LEN; //ただ単にtailをインクリメントしたら困るので、LENの値まで増えたら0になるようにする
}

P dequeue(){//中身を取り出す//Pは構造体の名前
    P x = Q[head];
    head = (head + 1) % LEN;
    return x;
}

int min(int a, int b){ return a < b? a : b;} //最小値を返す

int main(){
    int elaps = 0, c;
    int i, q;
    P u;
    scanf("%d %d", &n, &q); //プロセス数を表すn, クオンタムを表す整数q

    //全てのプロセスをキューに順番に追加する
    for(i = 1; i <= n; i++){
        scanf("%s", Q[i].name);
        scanf("%d", &Q[i].t);
    }

    head = 1; tail = n + 1;

    //シミュレーション
    while(head != tail){
        u = dequeue();//先頭の要素（headが指している要素）を取り出してuに代入

        c = min(q, u.t); //qまたはプロセスに必要な時間u.tだけ処理を行う

        u.t -= c; //経過時間を計算（プロセスに必要時間がクオンタムより小さいならばu.tは0になる（処理が完了する））

        elaps += c; //経過時間を加算

        if(u.t > 0)
            enqueue(u);//処理が完了していなけらばキューに追加
        else{
            printf("%s %d\n", u.name, elaps);//処理が終わったプロセスから表示していく
        }
    }
    return 0;
}

