int pop();
void push(int);
int stack[1000];
int ppp=0;
void push(int o){
  stack[ppp++]=o;
}
int pop(){
  if(ppp<=0)return 0;
  return stack[--ppp];
}

int main(){
  int o,k=0,Ans,a,b;
  char t[100];
  while(scanf("%s",t)!=EOF){
    if(t[0]=='+'){
      a=pop();
      b=pop();
      Ans=a+b;
      push(Ans);
    }
    else if(t[0]=='-'){
      a=pop();
      b=pop();
      Ans=b-a;
      push(Ans);
    }
    else if(t[0]=='*'){
      a=pop();
      b=pop();
      Ans=a*b;
      push(Ans);
    }
    else{
      o=atoi(t);
      push(o);
    }
  }
  Ans=pop();
  printf("%d\n",Ans);
  return 0;
}

