{
    Task temp;
    int toltime = 0;
    while(queue->head != queue->tail){  
        if(queue->tail < 0 || queue->tail > queue->maxSize - 1)
        {
            queue->tail = queue->head;
        }
        temp = p[queue->head];
        queue->head = (queue->head + 1) % queue->maxSize;
        queue->acSize--;   
        if(temp.quantum <= interval)
        {
            toltime += temp.quantum;
            printf("%s %d\n",temp.name, toltime);
        }
        else 
        {
            toltime += interval;
            temp.quantum -= interval;
           if(ifIsFull(queue)==0)
        {
            p[queue->tail] = temp;
            queue->tail = (queue->tail+1) % queue->maxSize;
            queue->acSize++;
        }
        if(queue->acSize == queue->maxSize)
        {
            queue->tail = -1;
        }
        }
    }
}
