int binarySearch(int *A,int key){
  int left=0;
  int right=0;
  int mid=0;
  right=length;
  while(left<right){
    mid=(left+right)/2;
    if(key==A[mid])
      return 1;

    if(key>A[mid])
      left=mid+1;
    else if(key<A[mid])
      right=mid;
  }
  return 0;
}

