	scanf("%d %d", &pn, &pt);

	/* get Name & time */
	while(scanf("%s %d", name_buff[data_num], &(time_buff[data_num])) != EOF)
	{
		data_num++;
	}

	/* get Data Num equal process num */
	if( data_num == pn )
	{
		while(pn > 0)
		{
			/* remain process time */
			if(time_buff[bp] > 0)
			{
				if( time_buff[bp] > pt )
				{
					time_buff[bp] -= pt;
					elapsed_time += pt;
				}
				else
				{
					elapsed_time += time_buff[bp];
					printf("%s %d\n", name_buff[bp], elapsed_time); /* output finished process */
					time_buff[bp] = 0;
					pn--;
				}
			}
			else
			{
				/* Already Finish */
			}

			/* Next buffer position */
			if(bp == data_num)
			{
				bp = 0;
			}
			else
			{
				bp++;
			}
		}
	}
	else
	{
		/* error input */
	}

	return 0;
}

