void swap(int* x, int* y)
{
	int t;

	t = *x;
	*x = *y;
	*y = t;
}

int binary_search(int p[], int n, int key)
{
	int left, right, middle;

	left = 0;
	right = n - 1;


	while (left <= right)
	{
		middle = (left + right) / 2;

		if (p[middle] == key)
			return middle;
		else if (p[middle] > key)
		{
			right = middle - 1;
		}
		else if (p[middle] < key)
		{
			left = middle + 1;
		}
	}

	return -1;

}

void bubble_sort(int p[], int n)
{
	int i, j;

	for (i = 0; i < n - 1; i++)
	{
		for (j = 0; j < n - i - 1; j++)
		{
			if (p[j] > p[j + 1])
				swap(&p[i], &p[i + 1]);
		}
	}
}

void insertion_sort(int* p, int N)
{
	int i, j;

	for (i = 1; i < N; i++)
	{
		j = i;

		while (j >= 0 && p[j] < p[j - 1])
		{
			swap(&p[j], &p[j - 1]);
			j--;
		}
	}
}

static int cnt = 0;

void insertion_sort2(int p[], int N, int g)
{
	int i, j;

	for (i = g; i < N; i++)
	{
		j = i;

		while (p[j] < p[j - g] && j - g >= 0)
		{
			swap(&p[j], &p[j - g]);
			j -= g;
			cnt++;
		}
	}
}

