#define LEN 100005

typedef struct pp{
  char name[100];
  int time;
}P;

P Q[LEN+1];
int head=0, tail=0;

void enqueue(P x){/* Q[tail] に x を代入し、tail を１つ増やします。 */
  int next = (tail+1)%LEN;

  if (next == head) {
    /* キューがいっぱいの場合のエラー処理 */
    printf("Queue overflow!\n");
    exit (2);
  }

  Q[tail] = x;
  tail = next;
}

P dequeue(){/* Q[head] の値を返し、head を１つ増やします。  */
  P t;

  if (head == tail) {/* キューが空の場合のエラー処理 */
    t.time = -1;
    return t;
  }

  t = Q[head];
  head = (head+1)%LEN;
  return t;
}


