  scanf("%d %d", &n, &q);/* プロセス数を表す整数 n とクオンタムを表す整数 q */
/* 続く n 行で、各プロセスの情報が順番に与えられます */                    
  for ( i = 1; i <= n; i++){
    scanf("%s", Q[i].name);
    scanf("%d", &Q[i].time);
    enqueue(Q[i]);/*キューに追加 */ 
  }

/* 以下実行部分 */
  while(1){
    u = dequeue();
    if(u.time == -1)break;
    if(u.time > q){/* 時間内に終了しない場合時間を減らし末尾に追加 */
      u.time -= q;
      total += q;
      enqueue(u);
    }
    else if(u.time <=  q){/* データ名とかかった総時間の表示 */
      total += u.time;
      printf("%s %d\n",u.name,total);
    }
  }

  return 0;
}

