				}else{
					Q[i].t -= q;
					EndTime += q;
				}
			}
		}
		if(EndProcess > n)break;
	}



	//Selection Sort
	for(i = 0;i < n;i++){
		k = i;
		for(j = i;j < n;j++){
			if(Q[k].End > Q[j].End){
				k = j;
			}
		}	
		key = Q[i];
		Q[i] = Q[k];
		Q[k] = key;
	}

	//Display Result
