#include <string.h>

int main(void)
{
	int  pn;					/* process num */
	int  pt;					/* process time */
	char name_buff[100000][10];	/* Name Buffer */
	int  time_buff[100000];		/* Time Buffer */
	int  remain_num[100000];	/* remain num */
	int  data_num = 0;
	int  elapsed_time = 0;
	int  bp = 0;				/* Buffer Position */
	int  loop;
	/* get "process num" & "process time" */
	scanf("%d %d", &pn, &pt);

	/* get Name & time */
	while(scanf("%s %d", name_buff[data_num], &(time_buff[data_num])) != EOF)
	{
		data_num++;
		remain_num[data_num] = data_num;
	}

	/* get Data Num equal process num */
	if( data_num == pn )
	{
		while(pn > 0)
		{
			/* remain process time */
			if(time_buff[remain_num[bp]] > 0)
			{
				if( time_buff[remain_num[bp]] > pt )
				{
					time_buff[remain_num[bp]] -= pt;
					elapsed_time += pt;
				}
				else
				{
					elapsed_time += time_buff[remain_num[bp]];
					printf("%s %d\n", name_buff[remain_num[bp]], elapsed_time); /* output finished process */
					time_buff[remain_num[bp]] = 0;
					pn--;

					for(loop=bp; loop<(pn-bp-1); loop++)
					{
						remain_num[loop] = remain_num[loop+1];
					}
				}
			}
			else
			{
				/* Already Finish */
			}

			/* Next buffer position */
			if(bp == (pn - 1))
			{
				bp = 0;
			}
			else
			{
				bp++;
			}
		}
	}
	else
	{
		/* error input */
	}

	return 0;
}

