int main(int argc, char **argv) {
    struct list_head head;
    INIT_LIST_HEAD(&head);

    int n = get_uint();
    int q = get_uint();
    for(int i = 0; i < n; ++i) {
        struct my_node *data = malloc(sizeof(struct my_node));
        get_str(data->str);
        data->num = get_uint();
        list_add_tail(&data->list, &head);
    }

    int cnt = 0;
    while(!list_empty(&head)) {
        struct my_node *data = list_first_entry(&head, struct my_node, list);
        if(data->num > q) {
            cnt += q;
            data->num -= q;
            list_move_tail(&data->list, &head);
        } else {
            cnt += data->num;
            put_str(data->str);
            putchar_unlocked(' ');
            put_uint(cnt);
            putchar_unlocked('\n');
            list_del(&data->list);
            free(data);
        }
    }
    return 0;
}

