#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct process{
  char *name;
  long time;
  struct process *next;
  struct process *before;
}Process;

Process *push_back(Process *begin, long time, char *name) {
  Process *p = (Process*)malloc(sizeof(Process));
  p->name = (char*)malloc(sizeof(char)*(strlen(name)+1));
  strcpy(p->name,name);
  p->time = time;
  p->before = NULL;
  p->next = NULL;
  if(begin == NULL) return p;
  Process *p_before = begin;
  while(p_before->next != NULL) p_before = p_before->next;
  p_before->next = p;
  p->before = p_before;
  return begin;
}

Process *remove_process(Process *begin, Process *p){
  if(p->before == NULL && p->next == NULL) {
    free(p->name);
    free(p);
    return NULL;
  }
  if(p->before == NULL) {
    p = begin->next;
    begin->next->before = NULL;
    free(begin->name);
    free(begin);
    return p;
  }
  if(p->next == NULL) {
    p->before->next = NULL;
    free(p->name);
    free(p);
    return begin;
  }
  p->next->before = p->before;
  p->before->next = p->next;
  free(p->name);
  free(p);
  return begin;
}

int main() {
  long n,i,time;
  int q;
  char name[11];
  scanf("%ld %d", &n, &q);
  Process *begin = NULL;
  Process *p,*temp;
  Process *finished = NULL;

  for(i = 0; i < n; i++) {
    scanf("%s %ld", name, &time);
    begin = push_back(begin, time, name);
  }

  p = begin;
  time = 0;
  while(begin != NULL) {
    time += q;
    p->time -= q;
    if(p->time <= 0) {
      time += p->time;
      finished = push_back(finished, time, p->name);
      if(p->next == NULL) {
	temp = begin;
      }else{
	temp = p->next;
      }
      begin = remove_process(begin, p);
      p = temp;
    }else{
      if(p->next == NULL) {
	p = begin;
      }else{
	p = p->next;
      }
    }
  }

  p = finished;
  while(p != NULL) {
    printf("%s %ld\n", p->name, p->time);
    p = p->next;
  }


  return 0;
}

