P Q[LEN];
int head, tail, n;

// 引数がPとxであり，xをQの末尾につけ，末尾を指すインデックスの数字を一つ増やし，あまりを取る
void enqueue(P x){
    Q[tail] = x;
    tail = (tail + 1) % LEN;
}

// Pの構造体でxを参照し，Qの先頭をPのxに加え，先頭の大きさを一つt増やす
P dequeue() {
    P x = Q[head];
    head = (head + 1) % LEN;
    return x;
}

