void initialize(void)
{
  head = 0;
  tail = 0;
  return ;
}

process pop(void)
{
  process p;
  p = Queue[head++];
  return p;
}

void append(process p)
{
  memcpy((void *)Queue[tail].name, (void *)p.name, NAME_LEN);
  Queue[tail].time = p.time;

  tail++;
  return;
}

int is_empty(void)
{
  return (head == tail);
}

