void schedule(int q)
{
    PROCESS tmp;
    int time_sum = 0;

    while(1)
	{
	    if(dequeue(&tmp) == -1)
	    {
	        break;
	    }

	    if(tmp.t - q > 0)
	    {
	        tmp.t -= q;
	        time_sum += q;
	        enqueue(tmp);
	    }
	    else
	    {
	        time_sum += tmp.t;
	        printf("%s %d\n", tmp.name, time_sum);
	    }
	}

	return;
}

void init_queue(void)
{
    g_que.head = 0;
    g_que.tail = 0;

    return;
}

int is_empty(void)
{
    if(g_que.head == g_que.tail)
    {
        return 1;
    }

    return 0;
}

int is_full(void)
{
    if(g_que.head == (g_que.tail + 1) % PROCESS_CNT_MAX)
    {
        return 1;
    }

    return 0;
}

int enqueue(PROCESS p)
{
    if(is_full())
    {
        return -1;;
    }

    g_que.pro[g_que.tail] = p;

    if(g_que.tail + 1 == PROCESS_CNT_MAX)
    {
        g_que.tail = 0;
    }
    else
    {
        g_que.tail++;
    }

    return 0;
}
int dequeue(PROCESS *p_p)
{
    if(is_empty())
    {
        return -1;
    }

    if(g_que.head + 1 == PROCESS_CNT_MAX)
    {
        g_que.head = 0;
        *p_p = g_que.pro[PROCESS_CNT_MAX - 1];
    }
    else
    {
        g_que.head++;
        *p_p = g_que.pro[g_que.head - 1];
    }

    return 0;
}

int get_str(char *p_str, int min, int max)
{
    int cnt = 0;
    int ch;

    while((ch = getchar()) != -1)
    {

        if(ch == ' ' || ch == '\n')
        {
            p_str[cnt] = '\0';
            return ch;
        }

        p_str[cnt] = ch;
        cnt++;

        if(judge_constraint(cnt, min, max) == -1)
        {
            return -1;
        }
    }

    return -1;
}


int get_int(int *p_num, int min, int max)
{
	scanf("%d%*c", p_num);

	if(judge_constraint(*p_num, min, max) == -1)
    {
        return -1;
    }

	return 0;
}
int judge_constraint(int test_num, int min, int max)
{
    if(test_num < min || test_num > max)
    {
        return -1;
    }

    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct process{
  char *name;
  long time;
  struct process *next;
}Process;

Process *push_back(Process *begin, long time, char *name) {
  Process *p = (Process*)malloc(sizeof(Process));
  p->name = (char*)malloc(sizeof(char)*(strlen(name)+1));
  strcpy(p->name,name);
  p->time = time;
  p->next = NULL;
  if(begin == NULL) return p;
  Process *p_before = begin;
  while(p_before->next != NULL) p_before = p_before->next;
  p_before->next = p;
  return begin;
}

Process *remove_process(Process *begin, char *name){
  Process *p,*temp;
  if(strcmp(begin->name,name) == 0) {
    p = begin->next;
    free(begin);
    return p;
  }
  p = begin;
  while(strcmp(p->next->name,name) != 0) p = p->next;
  temp = p->next;
  p->next = p->next->next;
  free(temp);
  return begin;
}

int main() {
  long n,i,time;
  int q;
  char name[11];
  scanf("%ld %d", &n, &q);
  Process *begin = NULL;
  Process *p;
  Process *finished = NULL;

  for(i = 0; i < n; i++) {
    scanf("%s %ld", name, &time);
    begin = push_back(begin, time, name);
  }
  p = begin;
  time = 0;
  push_back(finished, time + p->time, p->name);



  while(begin != NULL) {
    time += q;
    p->time -= q;
    if(p->time <= 0) {
      time += p->time;
      finished = push_back(finished, time, p->name);
      strcpy(name, p->name);
      if(p->next == NULL) {
	p = begin;
      }else{
	p = p->next;
      }
      begin = remove_process(begin, name);
    }else{
      if(p->next == NULL) {
	p = begin;
      }else{
	p = p->next;
      }
    }
  }

  p = finished;
  while(p != NULL) {
    printf("%s %ld\n", p->name, p->time);
    p = p->next;
  }


  return 0;
}

