typedef struct obj{
	struct obj *prev;
	struct obj *next;
	char *name;
	int time;
}obj;

typedef struct{
	struct obj *root;
	struct obj *last;
}queue;

obj *createObj(char *name, int time){
	obj *ob;
	mymalloc(ob,1);
	ob->prev=NULL;
	ob->next=NULL;
	ob->name=name;
	ob->time=time;
	return ob;
}

queue *createQueue(){
	queue *Q;
	mymalloc(Q,1);
	Q->root=NULL;
	Q->last=NULL;
}

void enqueue(queue *Q,obj *input){
	if(Q->root==NULL){
		Q->root=input;
		Q->last=input;
	}
	else{
		Q->root->prev=input;
		input->next=Q->root;
		Q->root=input;
	}
}

obj *dequeue(queue *Q){
	obj *output;
	if(Q->last==NULL){
		return NULL;
	}
	else{
		output=Q->last;
		if(Q->last->prev==NULL){
			Q->last=NULL;
			Q->root=NULL;
		}
		else{
			Q->last=Q->last->prev;
		}
		return output;
	}
}

