Queue create(void)
{
	Queue q;

	q = malloc(sizeof(struct Queue_type));
	if ( q == NULL )
		terminate("Error in create: queue could not be created.");

	q->front = malloc(sizeof(struct Node));
	if ( q->front == NULL ) {
		free(q);
		terminate("Error in create: fail to allocate space for the header.");
	}

	q->front->next = NULL;

	q->rear = q->front;

	return q;
}

void destroy(Queue q)
{
	make_empty(q);

	free(q->front);
	free(q);
}

void make_empty(Queue q)
{
	while ( !is_empty(q) )
		dequeue(q);
}

bool is_empty(Queue q)
{
	return q->front->next == NULL;
}

void enqueue(Queue q, Item i)
{
	Position tmp = malloc(sizeof(struct Node));

	if ( tmp == NULL ) {
		destroy(q);
		terminate("Error in enqueue: fail to allocate space for new node.");
	}

	tmp->data = i;
	tmp->next = NULL;

	q->rear->next = tmp;
	q->rear = tmp;
}

Item front(Queue q)
{
	if ( is_empty(q) ) {
		destroy(q);
		terminate("Error in front: queue is empty.");
	}

	return q->front->next->data;
}

Item dequeue(Queue q)
{
	Item item;
	Position tmp;

	if ( is_empty(q) ) {
		destroy(q);
		terminate("Error in dequeue: queue is empty.");
	}

	tmp = q->front->next;
	item = tmp->data;
	q->front->next = tmp->next;

	if ( q->rear == tmp )
		q->rear = q->front;

	free(tmp);

	return item;
}

