typedef struct {
	char name[NAME_LEN];
	int time;
} Process;

Process a[MAX];
int top;

void push(Process p)
{
	top = (top + 1) % MAX;
    a[top] = p;
}

Process pop(void)
{
	int i;
	Process tmp = a[0];
	for(i = 0; i < top; i++)
		a[i] = a[i + 1];
	top = (top - 1) % MAX;
	return tmp;
}

int main(void)
{
	int n, q, i;
	int timer = 0;
	scanf("%d %d", &n, &q);
	for (i = 0; i < n; i++) {
