	}

	top = n - 1;
	while (top >= 0) {
		Process pro;
		pro = pop();
		if (pro.time <= q) {
			timer += pro.time;
			printf("%s %d\n", pro.name, timer);
		}
		else {
			timer += q;
			pro.time -= q;
			push(pro);
		}
	}

	return 0;
}

