fun run(queue: Queue<Process>, q: Int) {
    var time = 0
    while (queue.size > 0) {
        val process = queue.poll()
        if (process.time > q) {
            process.time -= q
            time += q
            queue.add(process)
        } else {
            time += process.time
            println("${process.name} ${time}")
        }
    }
}

