class Queue {
    private val a = Array<Pair<String, Int>?>(100001) { null }

    private var head = 0

    private var tail = 0

    fun enqueue(v: Pair<String, Int>?) {
        a[tail] = v
        if (tail + 1 == a.size) {
            tail = 0
        } else {
            tail++
        }
    }

    fun dequeue(): Pair<String, Int>? {
        val r = a[head]
        a[head] = null
        if (head + 1 == a.size) {
            head = 0
        } else {
            head++
        }
        return r
    }

    fun isEmpty() = head == tail
}

