data class Process(val id: String, val time: Int)

class Queue<T>(private val maxSize: Int) {

    private val elements = arrayListOf<T>()

    fun isEmpty() = elements.size == 0

    fun isFull() = elements.size == maxSize

    fun enqueue(element: T) {
        if (isFull()) throw Exception("error")
        elements.add(element)
    }

    fun dequeue(): T {
        if (isEmpty()) throw Exception("error")
        return elements.removeAt(0)
    }
}

