        queue.enqueue(Process(id, t.toInt()))
    }

    var count = 0
    while (!queue.isEmpty()) {
        val process = queue.dequeue()
        if (process.time <= q) {
            count += process.time
            val id = process.id
            println("$id $count")
        } else {
            queue.enqueue(Process(process.id, process.time - q))
            count += q
        }
    }
}

