        return head == tail;
    }
    boolean isFull() {
        return head == (tail + 1) % MAX;
    }
    void enqueue(P x) {
        if(isFull()) return;
        Q[tail] = x;
        if(tail + 1 == MAX) tail = 0;
        else tail++;
    }
    P dequeue() {
        if(isEmpty()) return (new P("error", -1));
        P x = Q[head];
        if(head + 1 == MAX) head = 0;
        else head++;
