class Queue{
  Process[] a = new Process[100000];
  int head;
  int tail;

  Queue(){
    head = 0;
    tail = 0;
  }

  void enqueue(Process p){
    if(tail+1 == a.length)
      tail = 0;
    else
      tail++;

    a[tail] = p;
  }

  Process dequeue(){
    if(head+1 == a.length)
      head = 0;
    else
      head++;
    return a[head];
  }

  boolean isFull(){
    if(head == (tail+1) % a.length)
      return true;
    else
      return false;
  }

  boolean isEmpty(){
    if(head == tail)
      return true;
    else
      return false;
  }

}

