	static void Queue (String[] str, int[] data, int q) {
		int count = 0;
		int quantum = 0;
		int head = 0;
		int top = data.length;

		while (true) {
			if ( data[head] != 0) {
				//data[head] = Quantum(data[head], q);
				if ( data[head] < q) {
					quantum += 0;
					data[head] = 0;
					count++;
