	}

	public static void Queue (String[] str, int[] data, int n, int q) {
		int count = n;
		int head = 0;
		int top = n - 1;

		while (true) {
			if ( data[head] == 0) {
			} else {
				data[head] = Quantum(data[head], q);
				if (data[head] == 0) {
					count--;
					System.out.println(str[head] + " " + quantum);	
				} 
			}
			if (count == 0) break;
			else {
				head = head + 1;
				if (head > top) head = 0;
			}	
		}
	}

	public static int Quantum(int x, int q) {

		if ( x < q) {
			quantum += x % q;
			return 0;
		} else if (x == q) {
			quantum += q;
			return 0;
		} else {
			x -= q;
			quantum += q;
		}

		return x;

	}
}

