    public boolean isFull(){return (head+1)%CAPACITY == tail;}

    public int remove() {
    	if(isEmpty()) throw new IllegalStateException();
    	return queue[tail++];
    }

    public int add(int value) {
    	if(isFull()) throw new IllegalStateException();
    	return queue[head++] = value;
    }
}

