class Process {
    String name;
    int time;
    int completedTime;

    public Process(String name, int time) {
        this.name = name;
        this.time = time;
    }

    void execute(int q) {
        this.time = this.time - q;
    }

    void setCompletedTime(int completedTime) {
        this.completedTime = completedTime;
    }

    @Override
    public String toString() {
        return this.name + " " + this.completedTime;
    }
}

class ProcessQueue {

    int head, tail, MAX;
    Process[] arr;

    public ProcessQueue(int max) {
        this.MAX = max;
        arr = new Process[MAX];
    }

    void initialize() {
        head = 0;
        tail = 0;
    }

    boolean isEmpty() {
        return head ==tail;
    }

    boolean isFull() {
        return head == (tail + 1) % MAX;
    }

    void enqueue(Process x) {
        if (isFull()) {
            throw new RuntimeException("オーバーフロー");
        }
        arr[tail] = x;
        if (tail + 1 == MAX) {
            tail = 0;
        } else {
            tail++;
        }
    }

    Process dequeue() {
        if (isEmpty()) {
            throw new RuntimeException("アンダーフロー");
        }
        Process x = arr[head];
        if (head + 1 == MAX) {
            head = 0;
        } else {
            head++;
        }
        return x;
    }
}

