class Queue{

	private int head = 0;
	private int tail = 0;
	private int len = 100;
	private int[] data = new int[len];

	public void enqueue(int x){

		data[tail] = x;

		if(tail == len){
			tail = 0;
		}else{
			tail++;
		}

	}

	public int dequeue(){

		if(head == len){
			head = 0;
		}else{
			head++;
		}

		return data[head - 1];

	}

	public boolean isEmpty(){

		if(head == tail){
			return true;
		}else{
			return false;
		}

	}

}

