class Queue{
	private Process[] table;
	private int head, tail, size;

	Queue(int arg_size) {
		size = arg_size;
		table = new Process[size];
		head = 0;
		tail = 0;
	}

	boolean isEmpty() {
		return head == tail;
	}

	void push(Process process) {
		table[tail] = process;
		tail = (tail+1)%size;
	}

	public Process pop() {
		head = (head+1)%size;
		return table[(head-1+size)%size];
	}
}

