class Main {
	//グローバル変数
	static int N;
	static int time;
	static int donetime;

	public static void main(String[] args) throws IOException {
		//固定値の読み取り
		BufferedReader br= new BufferedReader(new InputStreamReader(System.in));
		String string = br.readLine();
		StringTokenizer st=new StringTokenizer(string, " ");
		N=Integer.parseInt(st.nextToken());
		time=Integer.parseInt(st.nextToken());
		String[] name = new String[N];
		int[] times = new int[N];

		//nameとtimesの読み取り
		for(int i=0;i<N;i++){
			string=br.readLine();
			st=new StringTokenizer(string, " ");
			name[i]=st.nextToken();
			times[i]=Integer.parseInt(st.nextToken());
		}
		doRound(name,times);	
	}

	public static void doRound(String[] name,int[] times){
		while(N>0){
			//the process was finished
			String answer = name[0];
			if(times[0]<=time){
				donetime += times[0];
				for(int i=0;i<N-1;i++){
					times[i]=times[i+1];
					String y = name[i+1];
					name[i]=y;
				}
				System.out.println(answer+" "+donetime);
				N --;
			}else{
				times[0]-=time;
				donetime+=time;

				//timeの入れ替え
				int time_zero = times[0];
				String name_zero = name[0];
				for(int i=0;i<N-1;i++){
					int temporary = times[i+1];
					times[i]=temporary;
					String temporary_name = name[i+1];
					name[i]=temporary_name;
				}
				times[N-1]=time_zero;
				name[N-1]=name_zero;
			}
		}	
	}
}

