		public int end{ get; set;}
		public Process(string n, int t){
			name=n;
			time=t;
			end=0;
		}
		public void finish(int current){
			end = current;
			time = -1;
		}
	}
	class ProcessQue{
		int current;
		List<Process> process;
		int quantum;
		public ProcessQue(int q){
			current=0;
			process = new List<Process>();
			quantum=q;
		}

		public void Load(string line){
			string[] tmp=line.Split(' ');
			process.Add(new Process(tmp[0],int.Parse(tmp[1])));
		}
		bool complete(){
			foreach(Process p in process)
				if(p.end==0)
					return false;
			return true;
		}
		public void exe(){
			while(!complete())
				foreach(Process p in process)
					for(int i=0;i<quantum;i++){
						if(p.time<0)
							break;
							current++;
						if(--p.time==0){
							p.finish(current);
							break;
						}

					}
		}

