    {
        public string name;
        public int time;
        public Process(string name, int time)
        {
            this.name = name;
            this.time = time;
        }
    }

    class Queue<T>
    {
        private T[] _buf;
        private int _head;
        private int _tail;

        public Queue(int num)
        {
            _buf = new T[num + 1];
            _head = 0;
            _tail = 0;
        }

        public void enqueue(T data)
        {
            if(isFull()){
                throw new IndexOutOfRangeException();
            }
            _buf[_head++] = data;
            if(_head >= _buf.Length){
                _head = 0;
            }
        }

        public T dequeue()
        {
            if(isEmpty()){
                throw new IndexOutOfRangeException();
            }
            var result = _buf[_tail++];
            if(_tail >= _buf.Length){
                _tail = 0;
            }

            return result;
        }

        public bool isEmpty()
        {
            return _head == _tail;
        }

        public bool isFull()
        {
            var head = _head + 1;
            if(head >= _buf.Length){
                head = 0;
            }

            return head == _tail;
        }
    }
}

