public class QUEUE<T>
{
    private int m, s, e, c;
    private T[] q;
    public QUEUE(int max) { m = max; q = new T[m]; CLEAR(); }
    public void CLEAR() { e = 0; s = 0; c = 0; }
    public int COUNT() { return c; }
    public void ENQUEUE(T v) { q[e] = v; e++; e %= m; c++; }
    public T DEQUEUE() { T r = PEEK(); s++; s %= m; c--; return r; }
    public T PEEK() { return q[s]; }
}

