class Program
{
	class Tuple<T, U>
	{
		public T Item1;
		public U Item2;

		public static void Create(T item1, U item2)
		{
			Item1 = item1;
			Item2 = item2;
		}
	}

	static void Main(string[] args)
	{
		string[] firstLine = Console.ReadLine().Split(new char[] {' '});
		int n = int.Parse(firstLine[0]);
		int q = int.Parse(firstLine[1]);

		// 入力の取得
		Queue<Tuple<string, int>> queue = new Queue<Tuple<string, int>>();
		for (int i = 0; i < n; i++)
		{
			string[] line = Console.ReadLine().Split(new char[] {' '});
			queue.Enqueue(Tuple<string, int>.Create(line[0], int.Parse(line[1])));
		}

		int time = 0;
		string result = "";

		while (queue.Count > 0)
		{
			Tuple<string, int> tuple = queue.Dequeue();
			tuple = Tuple<string, int>.Create(tuple.Item1, tuple.Item2 - q);
			time  = time + q - tuple.Item2;
