        private int s, e, c;
        private T[] q;
        public QUEUE(int max) { m = max; q = new T[m]; CLEAR(); }
        public void CLEAR() { e = 0; s = 0; c = 0; }
        public void ENQUEUE(T v) { q[EINC()] = v; }
        public T DEQUEUE() { return q[SINC()]; }
        public int COUNT() { return c; }
        private int EINC() { int r = e; e++; e %= m; c++; return r; }
        private int SINC() { int r = s; s++; s %= m; c--; return r; }
    }
}
