        var prs = new proc[n];
        proc.q = q;
        for (int i = 0; i < n; i++)
        {
            prs[i] = new proc(i);
            sc.Multi(out prs[i].name, out prs[i].time);
        }
        Array.Sort(prs);
        long sum = 0;
        var bit = new BIT(n);
        for (int i = 0; i < n; ++i)
        {
            sw.Write("{0} {1}", prs[i].name, prs[i].time + (prs[i].time - 1) / q * q * (n - i - 1) + (prs[i].ind - bit.sum(prs[i].ind)) * q + sum);
            sum += prs[i].time;
            bit.add(prs[i].ind, 1);
        }
        sw.Flush();
    }
    class proc : IComparable<proc>
    {
        public static int q;
        public string name;
        public long time;
        public int ind;
        public proc(int i)
        {
            ind = i;
        }
        public int CompareTo(proc p)
        {
            if (time / q == p.time / q)
                return ind.CompareTo(p.ind);

            return (time / q).CompareTo(p.time / q);
        }
