    class Queue<T>
    {
        private T[] array;
        private int top = 0;
        private int back = 0;

        public Queue(int capacity)
        {
            array = new T[capacity+1];
        }
        public void Enqueue(T item)
        {
            array[top++] = item;
            if (top == array.Length)
            {
                top = 0;
            }
        }
        public T Dequeue()
        {
            var temp = array[back++];
            if (back == array.Length) back = 0;
            return temp;
        }
        public bool IsEmpty()
        {
            return top == back;
        }
        public bool IsFull()
        {
            return (top + 1) % array.Length == back;
        }

    }

}

