public class Process :Queue
{
	private List<string> result;
	long totalTime;
	private static StringBuilder sb;

	public Process()
	{
		result = new List<string>();
		totalTime = 0;
		sb = new StringBuilder();
	}

	public void Execute(int q)
	{
		while(this.LongCount() != 0) {
			this.exe(q);
		}
	}

	public void Display()
	{
		sb.Length = 0;

		foreach(var s in result.ToArray())
		{
			sb.AppendLine(s);
		}

		Console.Write(sb);
	}

	private bool exe(int q)
	{
		var task = this.Dequeue();

		var time = this.GetTime(task);
		var name = this.GetName(task);
		bool ret = (q >= time);

		if(ret) {
			this.totalTime += time;
			this.result.Add(this.Join(name, this.totalTime));
		} else {
			this.totalTime += q;
			time -= q;
			this.Enqueue(this.Join(name, time));	//If task is not finished,add to task queue.
		}

		return ret;
	}

	private string Join(string n, long t)
	{
		sb.Length = 0;
		sb.Append(n);
		sb.Append(" ");
		sb.Append(t.ToString());
		return sb.ToString();
	}

	private int GetTime(string task)
	{
		return int.Parse(task.Split(' ')[1]);
	}

	private string GetName(string task)
	{
		return task.Split(' ')[0];
	}
}

