    class ElementaryDataStructuresB
    {
        static void Main(string[] args)
        {
            //読み込み
            var x = Console.ReadLine().Split().Select(int.Parse).ToArray();
            var n = x[0];
            var q = x[1];

            var Q = new Queue<Tuple<string, int>>();

            for (int i = 0; i < n; i++)
            {
                var xx = Console.ReadLine().Split().ToArray();
                var t = new Tuple<string, int>(xx[0], int.Parse(xx[1]));
                Q.Enqueue(t);
            }

            //計算
            var Ans = new List<Tuple<string, int>>();
            var Now = 0;

            while (Q.Count > 0)
            {
                var item = Q.Dequeue();

                if (q < item.Item2) //終了しない場合。
                {
                    Now += q;
                    Q.Enqueue(new Tuple<string, int>(item.Item1, item.Item2 - q));
                }
                else //終了する場合！
                {
                    Now += item.Item2;
                    Ans.Add(new Tuple<string, int>(item.Item1,Now));
                }
            }

            //出力
            foreach (var item in Ans)
            {
                Console.WriteLine(item.Item1 + " " + item.Item2);
            }

            //Enterを押して終了
            Console.ReadLine();
        }


    }
