	class Queue
	{
		private Process[] ringBuffer;
		private int head, tail;

		public Queue(int bufferSize) {
			ringBuffer = new Process[bufferSize];
			head = 0;
			tail = 0;
		}

		public void Enqueue(Process p) {
			ringBuffer[tail] = p;
			++tail;
			if (tail == ringBuffer.Length)
				tail = 0;
		}

		public Process Dequeue() {
			Process headProcess = ringBuffer[head];
			++head;
			if (head == ringBuffer.Length)
				head = 0;
			return headProcess;
		}

		public bool isEmpty() {
			return tail == head;
		}
	}

