        static void RoundRobin(Queue<Proc> queue, int quantum)
        {
            int timestamp = 0;
            while (queue.Count > 0)
            {
                var top = queue.Dequeue();
                timestamp += top.time < quantum ? top.time : quantum;
                if (top.time <= quantum) Console.WriteLine("{0} {1}",top.name,timestamp);
                else
                {
                    top.time -= quantum;
                    queue.Enqueue(top);
                }
            }
        }
    }
