        //static StreamReader Console = new StreamReader("input.txt");

        static int insertionSort(int[] A, int n, int g, int cnt)
        {
            for (int i = g; i < n; i++)
            {
                var v = A[i];
                var j = i - g;
                while (j >= 0 && A[j] > v)
                {
                    A[j + g] = A[j];
                    j = j - g;
                    cnt++;
                }
                A[j + g] = v;
            }
            return cnt;
        }

        static int shellSort(int[] A, int n, int[] m)
        {
            var cnt = 0;
            for (int i = 0; i < m.Length; i++)
            {
                cnt = insertionSort(A, n, m[i], cnt);
            }
            return cnt;
        }

