namespace ALDS1_3_B {
    class Program {
        static void Main(string[] args) {
            string[] input1 = Console.ReadLine().Split(' ');
            int n = int.Parse(input1[0]);
            int q = int.Parse(input1[1]);

            Queue<KeyValuePair<string, int>> que = new Queue<KeyValuePair<string, int>>();
            for(int i = 0; i < n; i++) {
                string[] input2 = Console.ReadLine().Split(' ');
                que.Enqueue(new KeyValuePair<string, int>(input2[0], int.Parse(input2[1])));
            }

            StringBuilder sb = new StringBuilder();
            int time = 0;
            while (que.Count>0) {
                KeyValuePair<string, int> cur = que.Dequeue();
                if (cur.Value > q) {
                    que.Enqueue(new KeyValuePair<string, int>(cur.Key, cur.Value - q));
                    time += q;
                    continue;
                }
                time += cur.Value;
                sb.AppendFormat("{0} {1}\n", cur.Key, time);
            }
            Console.Write(sb);
        }
    }
}

