class Program
{
	class MyTuple<T, U>
	{
		public T Item1;
		public U Item2;

		public MyTuple(T item1, U item2)
		{
			Item1 = item1;
			Item2 = item2;
		}
	}

	static void Main()
	{
		string[] firstLine = Console.ReadLine().Split(new char[] {' '});
		int n = int.Parse(firstLine[0]);
		int q = int.Parse(firstLine[1]);

		// 入力の取得
		Queue<MyTuple<string, int>> queue = new Queue<MyTuple<string, int>>();
		for (int i = 0; i < n; i++)
		{
			string[] line = Console.ReadLine().Split(new char[] {' '});
			queue.Enqueue(new MyTuple<string, int>(line[0], int.Parse(line[1])));
		}

		int time = 0;
		string result = "";

		while (queue.Count > 0)
		{
			MyTuple<string, int> tuple = queue.Dequeue();
			tuple.Item2 -= q;
			time  = time + q;
			if (tuple.Item2 > 0)
			{
				queue.Enqueue(tuple);
			}
			else
			{
				time += tuple.Item2;
				result += tuple.Item1 + " " + time;
				if (queue.Count > 0)
				{
					result += "\n";
				}
			}
		}

		System.Console.WriteLine(result);
	}
}

