class BIT
{
    int n;
    long[] bit;
    public BIT(int n) { this.n = n; bit = new long[n]; }
    public void add(int j, long w) { for (int i = j; i < n; i |= i + 1) bit[i] += w; }
    // [0, j)
    public long sum(int j)
    {
        long ret = 0;
        for (int i = j - 1; i >= 0; i = (i & (i + 1)) - 1) ret += bit[i];
        return ret;
    }
    // [j, k)
    public long sum(int j, int k) { return sum(k) - sum(j); }
}

using System;

namespace myApp
{
    class Program
    {
        static readonly int PROCESS_MAX = 100005; 
        struct Process {
            public string name;
            public int time;
        }
        static Process[] processes = new Process[PROCESS_MAX];
        static int head, tail;

        static void Enqueue(Process process) {
            processes[tail] = process;
            if ((tail + 1) == PROCESS_MAX) {
                tail = 0;
            } else {
                tail++;
            }
        }
        static Process Dequeue() {
            var result = processes[head];
            if (head + 1 == PROCESS_MAX) {
                head = 0;
            } else {
                head++;
            }
            return result;
        }
        static bool IsEmpty() {
            return head == tail;
        }

        static void Main(string[] args)
        {
            var line = Console.ReadLine().Split(' ');
            var n = int.Parse(line[0]);
            var quantum = int.Parse(line[1]);
            for (int i = 0; i < n; i++) {
                var name_time = Console.ReadLine().Split(' ');
                var p = new Process();
                p.name = name_time[0];
                p.time = int.Parse(name_time[1]);
                Enqueue(p);
            }

            int elapsedTime = 0;
            // processesが空になるまで処理をする
            while (!IsEmpty()) {
                // quantumだけ処理をして、終わらなければキューに入れる
                var p = Dequeue();
                if (p.time > quantum) {
                    elapsedTime += quantum;
                    p.time -= quantum;
                    Enqueue(p);
                } else {
                    // プロセスが完了したら、名前と終了時刻を出力する
                    elapsedTime += p.time;
                    Console.WriteLine(p.name + " " + elapsedTime);
                }
            }
        }
    }
}

