class Program
{
	class MyTuple<T, U>
	{
		public T Item1;
		public U Item2;

		public MyTuple(T item1, U item2)
		{
			Item1 = item1;
			Item2 = item2;
		}
	}

	class MyQueue<T>
	{
		Stack<T> _stack1 = new Stack<T>();
		Stack<T> _stack2 = new Stack<T>();

		public int Count
		{
			get { return _stack1.Count;}
		}

		public void Enqueue(T item)
		{
			_stack1.Push(item);
		}

		public T Dequeue()
		{
			T output;

			_stack2.Clear();
			while(_stack1.Count > 0)
			{
				_stack2.Push(_stack1.Pop());
			}
			output = _stack2.Pop();
			while(_stack2.Count > 0)
			{
				_stack1.Push(_stack2.Pop());
			}

			return output;
		}
	}

	static void Main()
	{
		string[] firstLine = Console.ReadLine().Split(new char[] {' '});
		int n = int.Parse(firstLine[0]);
		int q = int.Parse(firstLine[1]);

