		{
			string[] line = Console.ReadLine().Split(new char[] {' '});
			queue.Enqueue(new MyTuple<string, int>(line[0], int.Parse(line[1])));
		}

		int time = 0;

		while (queue.Count > 0)
		{
			MyTuple<string, int> tuple = queue.Dequeue();
			tuple.Item2 -= q;
			time  = time + q;
			if (tuple.Item2 > 0)
