        int tail { get; set; }
        int max { get; set; }
        Process[] queue { get; set; }

        public Queue()
        {
            head = 0;
            tail = 0;
            max = 100000;
            queue = new Process[max];
        }

        private bool isEmpty()
        {
            return head == tail;
        }

        private bool isFull()
        {
            return head == (tail + 1) % max;
        }

        public void enqueue(Process x)
        {
            if (isFull())
            {
                Console.WriteLine("オーバーフロー");
            }
            queue[tail] = x;
            if (tail + 1 == max)
            {
                tail = 0;
            }
            else
            {
                tail++;
            }

        }

        public Process dequeque()
        {
            if (isEmpty())
            {
                Console.WriteLine("アンダーフロー");
            }
            Process x = queue[head];
            if (head + 1 == max)
            {
                head = 0;
            }
            else
            {
                head++;
            }
            return x;
        }

