	class Prog {
		static void Main() {
			string[] a = Console.In.ReadLine().Split();
			int n = Int32.Parse(a[0]);
			int q = Int32.Parse(a[1]);

			const int maxsize = 500000;
			int size = (n < maxsize) ? n : maxsize;
			string[] text = Console.In.ReadToEnd().Split();
			var queue = new Queue<Process>(size);
			Process p;
			for (int i = 0; i < text.Length; ) {
				p.name = text[i++];
				p.time = Int32.Parse(text[i++]);
				if (i < text.Length && text[i] == "") i++;
				queue.Enqueue(p);
			}

			int elapsed = 0;
			var b = new StringBuilder(size * 20);
			while (queue.Count != 0) {
				do {
					var proc = queue.Dequeue();
					if (proc.time <= q) {
						elapsed += proc.time;
						b.Append(proc.name);
						b.Append(' ');
						b.Append(elapsed);
						b.AppendLine();
					} else {
						elapsed += q;
						proc.time -= q;
						queue.Enqueue(proc);
					}
				} while (queue.Count % maxsize != 0);
				Console.Out.Write(b.ToString());
				b.Length = 0;
			}
		}
	}
