namespace ConsoleApplication2
{
    class Program
    {
        static void Main(string[] args)
        {
            var input = Console.ReadLine().Split();
            var n = int.Parse(input[0]);
            var q = int.Parse(input[1]);
            var processeQueue = new Queue<Tuple<string, int>>();
            var endProcessList = new List<Tuple<string, int>>();
            var cpuTime = 0;

            for (var i = 0; i < n; i++)
            {
                var comingProcess = Console.ReadLine().Split();
                var name = comingProcess[0];
                var time = int.Parse(comingProcess[1]);

                processeQueue.Enqueue(Tuple.Create<string, int>(name, time));
            }

            while (processeQueue.Count != 0)
            {
                var process = processeQueue.Dequeue();
                var name = process.Item1;
                var time = process.Item2;

                if (q < time)
                {
                    cpuTime += q;
                    processeQueue.Enqueue(Tuple.Create(name, time - q));
                }
                else
                {
                    cpuTime += time;
                    endProcessList.Add(Tuple.Create(name, cpuTime));
                }
            }

            foreach (var t in endProcessList)
            {
                var name = t.Item1;
                var time = t.Item2;
                Console.WriteLine("{0} {1}", name, time);
            }
        }
    }
}

