class Data
{
    public string Str { get; set; }
    public int Num { get; set; }
}

class Program
{       

    static void RoundRobin(Queue<Data> que, int q, List<Data> result)
    {
        int time = 0;
        while(que.Count > 0)
        {
            if(que.Peek().Num <= q)
            {
                time += que.Peek().Num;
                Data a = new Data();
                a.Str = que.Peek().Str;
                a.Num = time;
                result.Add(a);
                que.Dequeue();           
            }
            else if(que.Peek().Num > q)
            {
                time += q;
                Data a = new Data();
                a.Str = que.Peek().Str;
                a.Num = que.Peek().Num - q;
                que.Dequeue();
                que.Enqueue(a);
            }
        }        
    }

    static void Main(string[] args)
    {
        string[] s = Console.ReadLine().Split(' ');
        int n = int.Parse(s[0]);
        int q = int.Parse(s[1]);

        var que = new Queue<Data>();
        var result = new List<Data>();

        //データの格納
        for(int i = 0; i < n; i++)
        {
            string[] ss = Console.ReadLine().Split(' ');
            var data = new Data();
            data.Str = ss[0];
            data.Num = int.Parse(ss[1]);
            que.Enqueue(data);
        }

        //データの処理
        RoundRobin(que, q, result);
        　
        foreach(var p in result)
        {
            Console.WriteLine($"{p.Str} {p.Num}");
        }

    }
}

