        }
    }
    class Queue<T>
    {
        private T[] array;
        private int top = 0;
        private int back = 0;
        private bool isFull = false;

        public Queue(int capacity)
        {
            array = new T[capacity];
        }
        public void Enqueue(T item)
        {
            array[top++] = item;
            if (top == array.Length)
            {
                top = 0;
            }
            if (top == back)
            {
                isFull = true;
            }
        }
        public T Dequeue()
        {
            isFull = false;
            var temp = array[back++];
            if (back == array.Length) back = 0;
            return temp;
        }
        public bool IsEmpty()
        {
            if (isFull == true) return false;
            return top == back;
        }
        public bool IsFull()
        {
            return isFull;
        }

    }

}

using System;
using System.IO;
using System.Collections.Generic;

namespace Prog {
	public struct Process {
		public int start;
		public int end;
		public int time;
	}

	enum NewLine { CRLF, LF, CR };

	public class Prog {

		static NewLine newline;
		static byte[] text = null;
		static byte[] res = null;

		public static int ReadInteger(Stream s) {
			byte c = (byte)s.ReadByte();
			while (c < 0x30) c = (byte)s.ReadByte();
			int sum = 0;
			do {
				sum *= 10;
				sum += (byte)(c - 0x30);
				c = (byte)s.ReadByte();
			} while (c >= 0x30);
			return sum;
		}

		public static int ReadInteger(ref int idx) {
			while (text[idx] < 0x30) idx++;
			int sum = 0;
			do {
				sum *= 10;
				sum += text[idx] - 0x30;
				idx++;
			} while (text[idx] >= 0x30);
			return sum;
		}

		public static void Print(ref int pos, int num) {
			int n = num;
			int digit = 10000000;
			bool isPrinting = false;
			while (digit != 0) {
				int div = n / digit;
				if (div != 0 || isPrinting) {
					isPrinting = true;
					res[pos++] = (byte)(0x30 + div);
				}
				n %= digit;
				digit /= 10;
			}
			if (!isPrinting)
				res[pos++] = 0x30;
		}

		public static void Main() {
			Console.In.Close();
			Console.Out.Close();
			if (System.Environment.NewLine == "\r\n") newline = NewLine.CRLF;
			else if (System.Environment.NewLine == "\n") newline = NewLine.LF;
			else newline = NewLine.CR;

			Stream si = Console.OpenStandardInput();
			int n = ReadInteger(si);
			int q = ReadInteger(si);

			int maxTextLen = n * 21;
			text = new byte[maxTextLen];
			int textlen = si.Read(text, 0, maxTextLen - 1);
			text[textlen] = 0x00; // ??????
			si.Close();

			Process[] procs = new Process[n];
			{
				int idx = 0;
				for (int i = 0; i < n; i++) {
					while (text[idx] < 0x30) idx++;
					procs[i].start = idx;
					while (text[idx] >= 0x30) idx++;
					procs[i].end = idx;
					procs[i].time = ReadInteger(ref idx);
				}
			}

			var queue = new Queue<int>(n);
			for (int i = 0; i < n; i++) queue.Enqueue(i);

			res = new byte[maxTextLen];
			int pos = 0;
			int elapsed = 0;
			while (queue.Count != 0) {
				int idx = queue.Dequeue();
				if (procs[idx].time <= q) {
					Array.Copy(text, procs[idx].start,
					           res, pos,
					           procs[idx].end - procs[idx].start);
					pos += procs[idx].end - procs[idx].start;
					res[pos++] = 0x20;
					elapsed += procs[idx].time;
					Print(ref pos, elapsed);
					if (newline == NewLine.CRLF) {
						res[pos++] = 0x0d;
						res[pos++] = 0x0a;
					} else if (newline == NewLine.LF) {
						res[pos++] = 0x0a;
					} else {
						res[pos++] = 0x0d;
					}
				} else {
					procs[idx].time -= q;
					elapsed += q;
					queue.Enqueue(idx);
				}
			}

			return;

			Stream so = Console.OpenStandardOutput();
			so.Write(res, 0, pos);
			so.Close();
		}
	}
}

