using System;

class Queue
{
    private string name;
    private int time;
    private int max = 100005;
    public Queue() {
        name = "null";
        time = 0;
    }
    public string nameop
    {
        get {
            return name;
        }
        set {
            name = value;
        }
    }
    public int timeop
    {
        get {
            return time;
        }
        set {
            time = value;
        }
    }
    public void enqueue(ref Queue[] queue, Queue data, ref int head, ref int tail) {

        queue[tail] = data;
        tail = (tail + 1) % max;
    }
    public Queue dequeue(ref Queue[] queue, ref int head, ref int tail) {
        Queue x = queue[head];
        head = (head + 1) % max;
        return x;
    }

}
