class Magatro
{
    private int N, Q;
    Queue<P> Que = new Queue<P>();
    private void Scan()
    {
        var line = Console.ReadLine().Split(' ');
        N = int.Parse(line[0]);
        Q = int.Parse(line[1]);
        for (int i = 0; i < N; i++)
        {
            line = Console.ReadLine().Split(' ');
            Que.Enqueue(new P(line[0], int.Parse(line[1])));
        }
    }

    public void Solve()
    {
        Scan();
        int t = 0;
        while (Que.Count > 0)
        {
            var p = Que.Dequeue();
            if (p.Time > Q)
            {
                t += Q;
                p.Time -= Q;
                Que.Enqueue(p);
            }
            else
            {
                t += p.Time;
                Console.WriteLine("{0} {1}", p.Name, t);
            }
        }
    }
}

