namespace Queue
{
    class Program
    {
        static void Main(string[] args)
        {
            var queue = new Queue<string>();
            var line = Console.ReadLine();
            var n = int.Parse(line.Split(' ')[0]);
            var q = int.Parse(line.Split(' ')[1]);
            var endTime = 0;

            //initialization
            for(var i = 0; i < n; i++)
            {
                queue.Enqueue(Console.ReadLine());
            }

            while(queue.Count > 0)
            {
                var process = queue.Dequeue();
                var time = int.Parse(process.Split(' ')[1]);
                if(time <= q)
                {
                    endTime += time;
                    Console.WriteLine(process.Split(' ')[0] + " " + endTime.ToString());                    
                }
                else
                {
                    endTime += q;
                    time -= q;
                    queue.Enqueue(process.Split(' ')[0] + " " + time.ToString());
                }
            }
        }
    }
}

