namespace ALDS1_3_B
{
    class Program
    {
        static void Main(string[] args)
        {
            string input = Console.ReadLine();
            string[] initial = input.Split(' ');
            int N = int.Parse(initial[0]);
            int quantum = int.Parse(initial[1]);
            string[] name_in = new string[N];
            int[] time_in = new int[N];

            string[] name_out = new string[N];
            int[] time_out = new int[N];
            int finish = 0;
            int count = 0;
            int current = 0;

            for (int i = 0; i < N; i++)
            {
                input = Console.ReadLine();
                string[] tmp = input.Split(' ');
                name_in[i] = tmp[0];
                time_in[i] = int.Parse(tmp[1]);
                finish += time_in[i];
            }

            while (current < finish)
            {
                for (int i = 0; i < N; i++)
                {
                    if (time_in[i] == 0) continue;
                    if (time_in[i] > quantum)
                    {
                        time_in[i] -= quantum;
                        current += quantum;
                    } else
                    {
                        current += time_in[i];
                        time_in[i] = 0;
                        name_out[count] = name_in[i];
                        time_out[count] = current;
                        count++;
                    }
                }
            }

            for (int i = 0; i < N; i++)
            {
                Console.WriteLine("{0} {1}", name_out[i], time_out[i]);
            }
        }
    }
