public class MyQueue
{
    private const int QMaxSize = 100_000;
    private int _head;
    private int _tail;
    private object[] _Q;

    // init
    public MyQueue() {
        _Q = new Object[QMaxSize];
        _head = 0;
        _tail = 0;
    }

    public void Enqueue(object obj)
    {
        if (IsFull())
        {
            throw new OverflowException();
        }

        _Q[_tail] = obj;

        _tail = (_tail + 1 == QMaxSize) ? _tail = 0 : _tail += 1;
    }

    public object Dequeue()
    {
        if (IsEmpty())
        {
            //TODO UNDERFLAW EXCEPTION
        }

        object deq = _Q[_head];
        _head++;
        return deq;
    }

    public bool IsFull()
    {
        return _head == (_tail + 1) % QMaxSize;
    }

    public bool IsEmpty()
    {
        return _head == _tail;
    }
}

