namespace aoj
{
    class Program
    {
        class MyQueue<T>
        {
            private readonly int unitLength;

            public int Count;

            private T[] array;
            private int head;
            private int tail;

            private bool isEmpty { get { return (this.Count <= 0); } }
            private bool isFull { get { return (unitLength <= this.Count); } }

            public MyQueue(int _length)
            {
                this.Count = 0;

                unitLength = _length;
                this.array = new T[unitLength];

                this.head = 0;
                this.tail = 0;
            }

            public T Pop()
            {
                if (isEmpty) { return default(T); }

                var result = this.array[this.head];
                this.array[this.head] = default(T);
                --this.Count;

                this.head = (this.head + 1) % unitLength;
                return result;
            }

            public bool Push(T _value)
            {
                if (isFull) { return false; }

                this.array[this.tail] = _value;
                this.tail = (this.tail + 1) % unitLength;
                ++this.Count;

                return true;
            }
        }

        public struct MyTask
        {
            public MyTask(string _name, int _time)
            {
                this.name = _name;
                this.time = _time;
            }

            public string name;
            public int time;
        }

        static void Main(string[] args)
        {
            string[] tmp = Console.ReadLine().Split(' ');
            var length = int.Parse(tmp[0]);
            var quantum = int.Parse(tmp[1]);

            MyQueue<MyTask> taskQueue = new MyQueue<MyTask>(length);
            for (var i = 0; i < length; ++i)
            {
                var input = Console.ReadLine().Split(' ');
                var name = input[0];
                var time = int.Parse(input[1]);
                var task = new MyTask(name, time);
                taskQueue.Push(task);
            }

            int elapsedTime = 0;
            while (0 < taskQueue.Count)
            {
                var task = taskQueue.Pop();
                task.time -= quantum;

                if (0 < task.time)
                {
                    elapsedTime += quantum;
                    taskQueue.Push(task);
                }
                else
                {
                    elapsedTime += quantum + task.time;
                    Console.Write(task.name + " ");
                    Console.WriteLine(elapsedTime);
                }
            }
        }
    }
}

