    public class Queue<T>
    {
        private readonly T[] process;
        private int head, tail;

        public Queue(int max)
        {
            process = new T[max+1];
            head = tail = 0;
        }

        public void Enqueue(T val)
        {
            process[tail] = val;
            if (tail + 1 >= process.Length)
                tail = 0;
            else
                tail++;
        }

        public T Dequeue()
        {
            var x = process[head];
            if (head + 1 == process.Length)
                head = 0;
            else
                head++;
            return x;
        }

        public bool IsEmpty()
        {
            return head == tail;
        }

    }
}

