public static class Program
{
	public class MyQueue<T>
	{
		private Stack<T> _stack1;
		private Stack<T> _stack2;

		public MyQueue()
		{
			_stack1 = new Stack<T>();
			_stack2 = new Stack<T>();
		}

		public void Enqueue(T x)
		{
			_stack1.Push(x);
		}

		public T Dequeue()
		{
			if (_stack2.Count > 0)
			{
				return _stack2.Pop();
			}
			while (_stack1.Count > 0)
			{
				_stack2.Push(_stack1.Pop());
			}
			return _stack2.Pop();
		}

		public int Count
		{
			get { return _stack1.Count + _stack2.Count; }
		}
	}


