class RoundRobbinQueue
  @quantum = 100
  @processes = [] #[[name, time]]
  @completed_processes = [] #[[name, elapsed]]
  @elapsed = 0

  def initialize(quantum, processes)
    @quantum = quantum
    @processes = processes
    @elapsed = 0
    @completed_processes = []
  end

  def execute_process
    length = @processes.length
    until @processes == []
      length = @processes.length
        if @processes[0][1] <= @quantum
          @elapsed += @processes[0][1]
          @completed_processes.push([@processes[0][0], @elapsed])
          @processes.delete_at(0)
        else
          @processes[0][1] -= @quantum
          @processes.push(@processes[0])
          @processes.delete_at(0)
          @elapsed += @quantum
        end
      end
      return @completed_processes
  end
end

