}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	q, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	processes := make([]process, n)
	for i, _ := range processes {
		name := nextStr(sc)
		remain, err := nextInt(sc)
		if err != nil {
			panic(err)
		}
		processes[i] = process{name, remain}
	}
	handle(processes, q)
}

func handle(processes []process, q int) {
	time := 0
	for len(processes) > 0 {
		process := &processes[0]
		if process.remains <= q {
			time += process.remains
			fmt.Printf("%s %d\n", process.name, time)
			processes = processes[1:]
		} else {
			process.remains = process.remains - q
			time += q
			processes = append(processes[1:], *process)
		}
	}
}

