package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"log"
	"os"
	"strconv"
	"strings"
)

// Item i
type Item interface {
	String() string
}

// Queue キュー
type Queue struct {
	data []Item
	head int
	tail int
}

// NewQueue キュー作成
func NewQueue(maxLength int) *Queue {
	return &Queue{make([]Item, maxLength+1), 0, 0}
}
func progCur(idx, maxLen int) int {
	return (idx + 1) % maxLen
}
func (q *Queue) isFull() bool {
	// tail と headには一つ間をおく.
	return progCur(q.tail, len(q.data)) == q.head
}
func (q *Queue) isEmpty() bool {
	return q.head == q.tail
}
func (q *Queue) enqueue(e Item) {
	if q.isFull() {
		panic("queue is full.")
	}
	q.data[q.tail] = e
	q.tail = progCur(q.tail, len(q.data))
}
func (q *Queue) dequeue() Item {
	if q.isEmpty() {
		panic("queue is empty.")
	}
	e := q.data[q.head]
	q.head = progCur(q.head, len(q.data))
	return e
}
func (q *Queue) String() string {
	var buf bytes.Buffer
	sep := ""
	for i := q.head; i != q.tail; i = progCur(i, len(q.data)) {
		buf.WriteString(fmt.Sprintf("%s%s", sep, q.data[i]))
		sep = " "
	}
	return fmt.Sprintf("head[%d] tail[%d] elem[%s]", q.head, q.tail, buf.String())
}

// Process プロセス
type Process struct {
	Name string
	Time int
}

func (p Process) String() string {
	return fmt.Sprintf("{%s %d}", p.Name, p.Time)
}

func schedule(quant int, queue *Queue) string {
	var output bytes.Buffer
	total := 0
	for !queue.isEmpty() {
		p := queue.dequeue()
		q, ok := p.(*Process)
		if !ok {
			panic("")
		}
		if q.Time <= quant {
			// プロセス終了
			output.WriteString(fmt.Sprintf("%s %d\n", q.Name, total+q.Time))
			total += q.Time
		} else {
			q.Time -= quant
			queue.enqueue(q)
			total += quant
		}
	}
	return output.String()
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	nq := eGetInts(reader)
	n, q := nq[0], nq[1]
	queue := NewQueue(n)
	for i := 0; i < n; i++ {
		pInfo := eGetFields(reader)
		queue.enqueue(&Process{pInfo[0], eAtoi(pInfo[1])})
	}
	fmt.Print(schedule(q, queue))
}
func eGetLine(r *bufio.Reader) string {
	s, err := r.ReadString(byte('\n'))
	if err != nil {
		if err != io.EOF {
			log.Fatal(err.Error())
		}
		return s
	}
	return strings.TrimRight(s, "\r\n")
}
func eGetInt(r *bufio.Reader) int {
	line := eGetLine(r)
	return eAtoi(line)
}
func eGetFields(r *bufio.Reader) []string {
	line := eGetLine(r)
	fields := strings.Split(line, " ")
	return fields
}
func eGetInts(r *bufio.Reader) []int {
	line := eGetLine(r)
	fields := strings.Split(line, " ")
	var ints []int
	for _, f := range fields {
		ints = append(ints, eAtoi(f))
	}
	return ints
}
func eAtoi(s string) int {
	n, err := strconv.Atoi(s)
	if err != nil {
		log.Fatal(err)
	}
	return n
}

type ints []int

func (s ints) String() string {
	var buf bytes.Buffer
	sep := ""
	for _, v := range s {
		buf.WriteString(fmt.Sprintf("%s%d", sep, v))
		sep = " "
	}
	return buf.String()
}

func reverse(a ints) ints {
	r := make(ints, len(a))
	for i := 0; i < len(a); i++ {
		r[i] = a[len(a)-1-i]
	}
	return r
}

