}

func (pl *ProcessList) enque(p Process) {
	pl.processList = append(pl.processList, p)
}

func (pl *ProcessList) deque() Process {
	p := pl.processList[0]
	pl.processList = pl.processList[1:]
	return p
}

func start(processList ProcessList) {
	time := 0
	for len(processList.processList) != 0 {
		process := processList.deque()
		if process.time > processList.qms {
			time += processList.qms
			process.time = process.time - processList.qms
			processList.enque(process)
		} else {
			time += process.time
			fmt.Println(process.name + " " + strconv.Itoa(time))
		}
	}

}

