// --- define queue data structure

type process struct {
	name string
	remain int
}

type queue struct {
	processes []process
	length int
}

func newQueue(initialCapacity int) *queue {
	q := make([]process, 0, initialCapacity)
	return &queue {
		processes: q,
		length: 0,
	}
}

func (q *queue) enqueue(p process) {
	q.processes = append(q.processes, p)
	q.length++
}

func (q *queue) dequeue() process {
	p := q.processes[0]
	q.processes = q.processes[1:]
	q.length--
	return p
}

// --- solution

type result struct {
	name string
	time int
}

func (r result) String() string {
	return fmt.Sprintf("%s %d", r.name, r.time)
}

func solve(quantum int, q *queue) []result {
	results := make([]result, 0, q.length)
	currentTime := 0

	for q.length > 0 {
		p := q.dequeue()
		if p.remain > quantum {
			currentTime += quantum
			p.remain -= quantum
			q.enqueue(p)
		} else {
			currentTime += p.remain
			results = append(results, result{name: p.name, time: currentTime})
		}
	}

	return results
}

// --- main (and parse)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}

	queue := newQueue(n)

	quantum, err := nextInt(sc)
	if err != nil {
		panic(err)
	}

	for i := 0; i < n; i++ {
		name := nextText(sc)
		remain, err := nextInt(sc)
		if err != nil {
			panic(err)
		}
		queue.enqueue(process{name: name, remain: remain})
	}

	results := solve(quantum, queue)

	for _, result := range results {
		fmt.Println(result)
	}
}

func nextText(sc *bufio.Scanner) string {
	sc.Scan()
	return sc.Text()
}

func nextInt(sc *bufio.Scanner) (int, error) {
	return strconv.Atoi(nextText(sc))
}

