	time  int
}

func main() {
	r := bufio.NewReader(os.Stdin)

	var n, q int
	fmt.Fscan(r, &n, &q)

	ps := make([]P, n)
	names := make([]string, n)
	for i := range ps {
		fmt.Fscan(r, &names[i])
		fmt.Fscan(r, &ps[i].time)
		ps[i].index = i
	}

	sort.Slice(ps, func(i, j int) bool {
		a, b := (ps[i].time-1)/q, (ps[j].time-1)/q
		if a == b {
			return ps[i].index < ps[j].index
		}
		return a < b
	})

	end := make([]uint8, n/8+1)
	et := 0
	for i, p := range ps {
		et += p.time
		endn := 0
		for j := 0; j <= p.index/8; j++ {
			endn += bits.OnesCount8(end[j] << uint(max(0, 8-p.index+8*j)))
		}
		aliven := p.index - endn
		fmt.Println(names[p.index], et+(n-i-1)*q*((p.time-1)/q)+aliven*q)
		end[p.index/8] |= 1 << (uint(p.index) % 8)
	}
}

