	for p := range q {
		if p.time > quantum {
			p.time -= quantum
			progress += quantum
			q <- p
		} else {
			progress += p.time
			fmt.Printf("%s %d\n", p.name, progress)

			if len(q) == 0 {
				close(q)
			}
