)

func getNextLine(scanner *bufio.Reader) string {
	var buffer string
	for {
		line, isPrefix, _ := scanner.ReadLine()
		buffer += string(line)
		if isPrefix == false {
			break
		}
	}
	return buffer
}

func getIntList(scanner *bufio.Reader) []int {
	list := strings.Split(getNextLine(scanner), " ")
	l := len(list)
	result := make([]int, l)
	for i := 0; i < l; i++ {
		result[i], _ = strconv.Atoi(list[i])
	}
	return result
}

func main() {
	fp := os.Stdin
	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
	}

	scanner := bufio.NewReader(fp)
	writer := bufio.NewWriter(os.Stdout)

	var n, q int
	fmt.Sscan(getNextLine(scanner), &n, &q)
	processes := make([]Process, n+1)
	for i := 0; i < n; i++ {
		fmt.Sscan(getNextLine(scanner), &processes[i].name, &processes[i].time)
	}
	head := 0
	tail := n
	time := 0
	n++
	for head != tail {
		p := processes[head]
		head = (head + 1) % n
		p.time -= q
		time += q
		if p.time <= 0 {
			time += p.time
			fmt.Fprintln(writer, fmt.Sprintf("%s %d", p.name, time))
			continue
		}
		processes[tail] = p
		tail = (tail + 1) % n

	}

	writer.Flush()
}

