type Queue struct {
	q [MAX_LEN]Process
	head int
	tail int
}

func GenQueue() Queue {
	return Queue{head: 0, tail: 0}
}

func (queue *Queue) IsEmpty() bool {
	return queue.head == queue.tail
}

func (queue *Queue) EnQueue(name string, time int) {
	queue.q[queue.tail] = Process{name: name, time: time}
	queue.tail = (queue.tail + 1) % MAX_LEN
}

func (queue *Queue) DeQueue() Process {
	if queue.IsEmpty() {
		panic("empty")
	}
	r := queue.q[queue.head]
	queue.head = (queue.head + 1) % MAX_LEN
	return r
}

