	for i := 0; i < n; i++ {
		sc.Scan()
		str = sc.Text()
		s := strings.Split(str, " ")
		time, _ := strconv.Atoi(s[1])
		q.EnQueue(s[0], time)
	}

	all_time := 0

	for {
		if q.IsEmpty() {
			break
		}
		p := q.DeQueue()
		if p.time <= time {
			all_time += p.time
			fmt.Printf("%s %d\n", p.name, all_time);
