type Process struct {
	name string
	time int
}

type Queue struct {
	ps    []*Process
	start int
	end   int
	len   int
}

func (q *Queue) enq(p *Process) {
	if q.len == len(q.ps) {
		panic("")
	}
	if q.end == len(q.ps) {
		q.ps[0] = p
		q.end = 0
	} else {
		q.ps[q.end] = p
	}
	q.end++
	q.len++
}

func (q *Queue) deq() *Process {
	if q.len == 0 {
		panic("")
	}
	result := q.ps[q.start]
	if q.start == len(q.ps)-1 {
		q.start = 0
	} else {
		q.start++
	}
	q.len--
	return result
}

