package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

// node, list 構造体とメソッドはALDS1_3_Aで使ったものをそのまま使う
// この課題ではpopFront(v *int)を追加する
type node struct {
	v          proc
	prev, next *node
}
type list struct {
	head, tail node
}

func newList() *list {
	nl := new(list)
	nl.head.next = &nl.tail
	nl.tail.prev = &nl.head
	return nl
}
func (ll *list) pushBack(v proc) {
	nn := new(node)
	nn.v = v
	nn.next = &ll.tail
	nn.prev = ll.tail.prev
	ll.tail.prev.next = nn
	ll.tail.prev = nn
}
func (ll *list) popBack(v *proc) (ret bool) {
	if ll.head.next == &ll.tail {
		ret = false
		return
	}
	ret = true
	*v = ll.tail.prev.v
	ll.tail.prev = ll.tail.prev.prev
	ll.tail.prev.next = &ll.tail
	return
}
func (ll *list) popFront(v *proc) (ret bool) {
	if ll.head.next == &ll.tail {
		ret = false
		return
	}
	ret = true
	*v = ll.head.next.v
	ll.head.next = ll.head.next.next
	ll.head.next.prev = &ll.head
	return
}

// ----------------------------------------
// process 構造体(proc)
// ----------------------------------------
type proc struct {
	name  string
	ptime int
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n := nextInt(sc)
	Q := nextInt(sc)
	l := newList()
	var p proc
	for i := 0; i < n; i++ {
		sc.Scan()
		p.name = sc.Text()
		p.ptime = nextInt(sc)
		l.pushBack(p) // キューに追加する
	}
	t := 0
	fprocs := make([]proc, 0)
	for l.popFront(&p) { //　キュー（先頭から取り出す）
		rt := min(Q, p.ptime) // ラインタイム(実行可能時間)を計算する(Qかp.ptimeの小さい方)
		t += rt               // 時計をランタイム分進める
		p.ptime -= rt         // p.ptimeからランタイムを引く
		if p.ptime == 0 {     // 実行完了?
			fprocs = append(fprocs, proc{p.name, t})
		} else {
			l.pushBack(p) // まだ処理が終わっていないので、キューの最後に追加
		}
	}
	wtr := bufio.NewWriter(os.Stdout)
	for i := 0; i < len(fprocs); i++ {
		fmt.Fprintf(wtr, "%s %d\n", fprocs[i].name, fprocs[i].ptime)
	}
	wtr.Flush()
}

