	time int
}

type queue struct {
	a    []process
	n    int
	head int
	tail int
}

func (q *queue) init(n int) {
	q.a = make([]process, n+1)
	q.n = n + 1
}

func (q *queue) push(p process) {
	if q.full() {
		panic("overflow")
	}
	q.a[q.tail] = p
	q.tail = (q.tail + 1) % q.n
}

func (q *queue) pop() process {
	if q.empty() {
		panic("empty")
	}
	p := q.a[q.head]
	q.head = (q.head + 1) % q.n
	return p
}

func (q *queue) full() bool {
	return q.head == (q.tail+1)%q.n
}

func (q *queue) empty() bool {
	return q.head == q.tail
}

func main() {
	var n, q int
	fmt.Scan(&n, &q)
	sc := bufio.NewScanner(os.Stdin)
