	for i := 0; i < n; i++ {
		sc.Scan()
		name := sc.Text()
		sc.Scan()
		t, _ := strconv.Atoi(sc.Text())
		qu.push(process{name, t})
	}
	// simulate
	now := 0
	for !qu.empty() {
		p := qu.pop()
		if p.time <= q {
			fmt.Println(p.name, now+p.time)
			now += p.time
		} else {
			p.time -= q
			now += q
			qu.push(p)
		}
	}
}

