func getNameAndTime(scanner *bufio.Scanner) (name string, time int) {
	scanner.Scan()
	var line = scanner.Text()
	var nameTime = strings.Split(line, " ")
	name = nameTime[0]
	time, _ = strconv.Atoi(nameTime[1])
	return name, time
}

func (queue *Queue) isFull() bool {
	return queue.head == ((queue.tail + 1) % len(queue.contents))
}

func (queue *Queue) enqueue(p Process) (err error) {
	if queue.isFull() {
		return errors.New("queue is full")
	}
	queue.contents[queue.tail] = p
	queue.tail = (queue.tail + 1) % len(queue.contents)
	return nil
}

func (queue *Queue) isEmpty() bool {
	return queue.tail == queue.head
}

func (queue *Queue) dequeue() (p Process, err error) {
	if queue.isEmpty() {
		return p, errors.New("can't dequeue case empty")
	}
	p = queue.contents[queue.head]
	queue.head = (queue.head + 1) % len(queue.contents)
	return p, nil
}

