var sc = bufio.NewScanner(os.Stdin)

type queue struct {
	q [1000000]process
	head int
	tail int
}

type process struct {
	name string
	time int
}

type processScheduler struct {
	q queue
	quantum int
	execTime int
}

func (q *queue) enqueue(p process) {
	q.q[q.tail] = p
	q.tail++
}

func (q *queue) dequeue() process {
	q.head++
	return q.q[q.head - 1]
}

func (q *queue) isEmpty() bool {
	return q.head == q.tail
}

func (ps *processScheduler) addProcess() bool {
	if ok := sc.Scan(); !ok {
		return false
	}
	pname := sc.Text()

	sc.Scan()
	ptime, _ := strconv.Atoi(sc.Text())
	ps.q.enqueue(process{pname, ptime})
	return true
}

func (ps *processScheduler) executeProcess() {

	// Get target process
	p := ps.q.dequeue()
	var leftTime int

	// Terminate Process
	if leftTime = p.time - ps.quantum; leftTime <= 0 {
		ps.execTime += p.time
		fmt.Println(p.name, ps.execTime)
		return
	}

	// re scheduling
	p.time -= ps.quantum
	ps.execTime += ps.quantum
	ps.q.enqueue(p)
}


func main() {
	sc.Split(bufio.ScanWords)
	sc.Scan()
	pnum, _ := strconv.Atoi(sc.Text())
	sc.Scan()
	quantum, _ := strconv.Atoi(sc.Text())

	ps := processScheduler{queue{}, quantum, 0}

	for i := 0; i < pnum; i++ {
		ps.addProcess()
	}

	for !ps.q.isEmpty() {
		ps.executeProcess()
	}
}

