func IsFull() bool {
	return head == (tail+1)%Max
}

func Enqueue(x *Process) (*Process, error) {
	if IsFull() {
		return nil, errors.New("Overflow")
	}
	queue[tail] = x
	tail = (tail + 1) % Max
	return x, nil
}

func Dequeue() (*Process, error) {
	if IsEmpty() {
		return nil, errors.New("Underflow")
	}
	v := queue[head]
	head = (head + 1) % Max
	return v, nil
}

