const MAX_LEN = 100000

type Process struct {
	name string
	time int
}
type Queue struct {
	container [MAX_LEN]Process
	head int
	tail int
}

func genereteQueue() Queue {
	return Queue{head: 0, tail: 0}
}

func (q *Queue) isEmpty() bool {
	return q.head == q.tail
}

func (q *Queue) enqueue(name string, time int) {
	q.container[q.tail] = Process{name: name, time: time}
	q.tail = (q.tail + 1) % MAX_LEN
}

func (q *Queue) dequeue() Process {
	if q.isEmpty() {
		fmt.Println("Empty.")
	}
	process := q.container[q.head]
	q.head = (q.head + 1) % MAX_LEN
	return process
}

var scanner = bufio.NewScanner(os.Stdin)

func main() {
	q := genereteQueue()
	scanner.Scan()
	str := scanner.Text()
	s := strings.Split(str, " ")
	//fmt.Println(scanner.Text())
	n, _ := strconv.Atoi(s[0])
	timeSlice, _ := strconv.Atoi(s[1])
	for i := 0; i < n; i++ {
		scanner.Scan()
		str := scanner.Text()
		s := strings.Split(str, " ")
		name := s[0]
		time ,_ := strconv.Atoi(s[1])
		q.enqueue(name, time)
	}
	ans := 0

	for {
		if q.isEmpty() {
			break
		}
		processing := q.dequeue()
		if processing.time <= timeSlice {
			ans += processing.time
			fmt.Printf("%s %d\n", processing.name, ans)
		} else {
			q.enqueue(processing.name, processing.time - timeSlice)
			ans += timeSlice
		}
	}
}

