func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	ss := strings.Fields(sc.Text())
	n, _ := strconv.Atoi(ss[0])
	q, _ := strconv.Atoi(ss[1])

	que := newQueue()
	for i := 0; i < n; i++ {
		sc.Scan()
		ss := strings.Fields(sc.Text())
		cputime, _ := strconv.Atoi(ss[1])
		que.enqueue(&process{name: ss[0], time: cputime})
	}

	timer, c := 0, 0
	for que.head != nil {
		u := que.dequeue()
		c = min(q, u.time)
		u.time -= c
		timer += c
		if u.time > 0 {
			que.enqueue(u)
			continue
		}
		fmt.Println(u.name, timer)
	}
}

type queue struct {
	head, tail *node
	len        int
}

type node struct {
	proc *process
	next *node
}

type process struct {
	name string
	time int
}

func (p *process) String() string {
	return fmt.Sprint(p.name + " " + strconv.Itoa(p.time))
}

func newQueue() *queue {
	return &queue{head: nil, tail: nil, len: 0}
}

func (q *queue) dequeue() *process {
	if q.len == 0 {
		return nil
	}
	headPtr := q.head
	q.head = headPtr.next
	if q.len == 1 {
		q.head, q.tail = nil, nil
	}
	q.len--
	return headPtr.proc
}

func (q *queue) enqueue(proc *process) {
	n := &node{proc: proc, next: nil}
	if q.len == 0 {
		q.head = n
		q.tail = n
	} else {
		q.tail.next = n
		q.tail = n
	}
	q.len++
}

func (q *queue) peek() *process {
	if q.len == 0 {
		return nil
	}
	return q.head.proc
}

func (p *process) consume(time *int) *process {
	if p.time < *time {
		p.time = 0
		*time -= p.time
		return p
	}
	p.time = p.time - *time
	*time = 0
	return p
}

func min(a, b int) int {
	if a > b {
		return b
	}
	return a
}

