	scanner.Scan()
	stringInput := scanner.Text()
	return strings.Split(stringInput, " ")
}

func main() {
	Initialize()
	info := StdInSlice()
	n, _ := strconv.Atoi(info[0])
	q, _ := strconv.Atoi(info[1])
	for i := 0; i < n; i++ {
		p := StdInSlice()
		name := p[0]
		time, _ := strconv.Atoi(p[1])
		Enqueue(&Process{name, time})
	}
	time := 0
	for false == IsEmpty() {
		p, _ := Dequeue()
		if (*p).time-q > 0 {
			(*p).time = (*p).time - q
			time += q
			Enqueue(p)
		} else {
			time += q + (*p).time - q
			fmt.Printf("%v %v\n", (*p).name, time)
		}
	}
}

func Initialize() {
	head = 0
	tail = 0
}

func IsEmpty() bool {
	return head == tail
}

func IsFull() bool {
	return head == (tail+1)%Max
}

func Enqueue(x *Process) (*Process, error) {
	if IsFull() {
		return nil, errors.New("Overflow")
	}
	queue[tail] = x
	tail = (tail + 1) % Max
	return x, nil
}

func Dequeue() (*Process, error) {
	if IsEmpty() {
		return nil, errors.New("Underflow")
	}
	v := queue[head]
	head = (head + 1) % Max
	return v, nil
}

