func main() {

	sc := bufio.NewScanner(os.Stdin)
	sc.Scan()
	in := sc.Text()
	ins := strings.Split(in, " ")
	// processNum, _ := strconv.Atoi(ins[0])
	quantum, _ := strconv.Atoi(ins[1])

	q := Queue{}
	for {
		sc.Scan()
		in := sc.Text()
		if len(in) == 0 {
			break
		}
		ins := strings.Split(in, " ")
		n := ins[0]
		t, _ := strconv.Atoi(ins[1])
		q.enqueue(Process{n, t})
	}

	now := 0
	for !q.isEmpty() {
		p := q.dequeue()
		if p.t > quantum {
			p.t = p.t - quantum
			q.enqueue(p)
			now = now + quantum
		} else {
			now = now + p.t
			fmt.Println(p.n + " " + strconv.Itoa(now))
		}

	}
}

type Process struct {
	n string
	t int
}

type Queue struct {
	val []Process
}

func (queue *Queue) enqueue(val Process) {
	queue.val = append(queue.val, val)
}

func (queue *Queue) dequeue() Process {
	res := queue.val[0]
	queue.val = queue.val[1:len(queue.val)]
	return res
}

func (queue *Queue) isEmpty() bool {
	return len(queue.val) == 0
}

