module Queue' = struct
  type 'a t = {
    mutable front : int;
    mutable capa  : int;
    mutable index : int;
    mutable length : int;
    mutable elems : (string * int) array
  }

  let is_empty (t: (string * int) t) = t.length = 0

  let create ?(capacity=2) () =
    let c = log10 (float_of_int capacity) /. log10 2.
            |> ceil |> ( ** ) 2. |> int_of_float in
    { front = 0;
      capa  = c;
      index = 0;
      length = 0;
      elems = Array.make c ("",0)}

  let enq (t: (string * int) t) (a: string * int) =
    let (elems: (string * int) array) = t.elems in
    elems.(t.index) <- a;
    t.length <- t.length + 1;
    t.index <- (t.index + 1) lor t.capa |> (lxor) t.capa

  let deq (t: (string * int) t) =
    let (elems: (string * int) array) = t.elems in
    let (front: int) = t.front in
    let (res: string * int) = elems.(front) in
    t.front <- (t.front+1) lor t.capa |> (lxor) t.capa;
    t.length <- t.length - 1;
    res
end

