from collections import deque

def round_robin_scheduling(N, Q, A):
    time = 0
    finished_process = []
    while A:
        process = A.popleft()
        if process[1] < Q:
            time += process[1]
            finished_process.append([process[0],time])
        else:
            time += Q
            A.append([process[0],process[1]-Q])
    else:
        return finished_process

