class MyQueue:
    def __init__(self, size):
        self.queue = [0 for i in range(size)]
        self.max_size = size
        self.head = 0
        self.tail = 0

    def initialize(self):
        self.head = self.tail = 0

    def is_empty(self):
        if self.head == self.tail:
            return True
        return False

    def is_full(self):
        if self.head == (self.tail + 1) % self.max_size:
            return True
        return False

    def enqueue(self, elm):
        if self.is_full():
            raise Exception
        self.queue[self.tail] = elm
        if self.tail + 1 == self.max_size:
            self.tail = 0
        else:
            self.tail += 1
        return self.queue

    def dequeue(self):
        if self.is_empty():
            raise Exception
        x = self.queue[self.head]
        if self.head + 1 == self.max_size:
            self.head = 0
        else:
            self.head += 1
        return x


