        if self.is_full():
            raise Exception
        self.queue[self.tail] = elm
        if self.tail + 1 == self.max_size:
            self.tail = 0
        else:
            self.tail += 1
        return self.queue

    def dequeue(self):
        if self.is_empty():
            raise Exception
        x = self.queue[self.head]
        if self.head + 1 == self.max_size:
            self.head = 0
        else:
            self.head += 1
        return x


