class Que:
    def __init__(self):
        self.head = None
        self.last = None

    def add(self, value):
        new_node = Node(value, None, self.last)
        if not self.head:
            self.head = new_node
        else:
            self.last.next = new_node
        self.last = new_node

    def popleft(self):
        if not self.head:
            return -1
        v = self.head.value

        self.head = self.head.next
        return v

    def isempty(self):
        return not self.head


