class Queue:
    def __init__(self, n):
        self.n = n
        self._l = [None for _ in range(self.n + 1)]
        self._top = 0

    def enqueue(self, x):
        if self.isFull():
            raise IndexError("queue is full")
        else:
            self._top += 1
            self._l[self._top] = x

    def dequeue(self):
        if self.isEmpty():
            raise IndexError("pop from empty queue")
        else:
            e = self._l[1]
            for i in range(1, self._top):
                self._l[i] = self._l[i+1]
            self._l[self._top] = None
            self._top -= 1
            return e

    def isEmpty(self):
        return self._top == 0

    def isFull(self):
        return self._top == self.n

