fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("filed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n:usize = read();
    let t:i32 = read();
    let mut queue: VecDeque<(String, i32)> = VecDeque::new();
    let mut cnt = 0;
    let mut ans:Vec<(String, i32)> = Vec::with_capacity(n);
    for _ in 0..n {
        let name:String = read();
        let time:i32 = read();
        queue.push_back((name, time));
    }
    while !queue.is_empty() {
        if queue[0].1 > t {
            queue[0].1 -= t;
            let tmp = queue.pop_front().unwrap();
            queue.push_back(tmp.clone());
            cnt += t;
        } else {
            let diff = t - queue[0].1;
            cnt += t-diff;
            ans.push((queue.pop_front().unwrap().0, cnt));
        }
    }
    let ans = ans.into_iter().map(|(c, k)| format!("{} {}", c, k)).collect::<Vec<String>>();
    for i in ans {
        println!("{}", i);
    }
}

