#[derive(Debug, Clone)]
struct TaskName(String);

#[derive(Debug, Clone)]
struct Task {
    name: TaskName,
    remain_time: i32, // 1 <= remain_time <= 50,000
}

#[derive(Debug)]
struct Quiz {
    n: u32,      // 1 <= n <= 100,000
    q: u32,      // 1 <= q <= 1,000
    v: Vec<Task>, // v.len() == n
}

#[derive(Debug)]
struct Answer {
    v: Vec<(TaskName, i32)>,
    // v.len() == q.n
}

impl Input {
    fn into_quiz(mut self) -> Quiz {
        let n: u32 = self.parse_next().unwrap();
        let q: u32 = self.parse_next().unwrap();
        let mut v = Vec::new();
        for _i in 0..n {
            let name = self.parse_next().unwrap();
            let time = self.parse_next().unwrap();
            v.push( Task{
                name: TaskName( name ),
                remain_time: time,
            });
        }
        Quiz { n, q, v }
    }
}

impl Quiz {
    fn solve(self) -> Answer {
        let mut deque = VecDeque::new();
        let mut vv = Vec::new();

        for e in &self.v {
            let cname = e.name.clone();
            let time = e.remain_time;
            deque.push_back( (cname, time) );
        }

        let mut current_time = 0;
        while !deque.is_empty() {
            dprintln!("t:{}", current_time);
            dprintln!(" queue:{:?}", deque);
            let (name, time) = deque.pop_front().unwrap();
            let q = self.q as i32;
            if time - q > 0 {
                dprintln!("  time:{} - q:{} > 0", time, q);
                current_time += q;
                deque.push_back( (name, time-q) );
            } else {
                dprintln!("  time:{} - q:{} <= 0", time, q);
                current_time += time;
                vv.push( (name, current_time) );
            }
        }

        Answer{
            v: vv,
        }
    }
}

impl Answer {
    fn print(self) {
        for e in self.v {
            let (TaskName(name), time) = e;
            println!("{} {}", name, time); 
        }
    }
}

