struct Queue<T> {
    data: std::collections::VecDeque<T>,
}

impl<T> Queue<T> {
    fn new() -> Self {
        Self {
            data: std::collections::VecDeque::new(),
        }
    }

    fn push(&mut self, data: T) {
        self.data.push_back(data);
    }

    fn pop(&mut self) -> Option<T> {
        self.data.pop_front()
    }

    fn size(&self) -> usize {
        self.data.len()
    }
}

