fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: isize = iterator.next().unwrap().parse().unwrap();
    let q: i32 = iterator.next().unwrap().parse().unwrap();

    let mut queue: VecDeque<Process> = VecDeque::new();
    for _i in 0..n {
        queue.push_back(
            Process {
                name: iterator.next().unwrap().to_string(),
                quantum: iterator.next().unwrap().parse().unwrap(),
            }
        );
    }

    let mut output = String::new();

    let mut time: i32 = 0;
    while !queue.is_empty() {
        let mut p = queue.pop_front().unwrap();

        if p.quantum <= q {
            time += p.quantum;
            output += &format!("{} {}\n", p.name, time);
        } else {
            p.quantum -= q;
            time += q;
            queue.push_back(p);
        }
    }

    return output.trim().to_string();
}

